PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?name ?birth_year ?citizenship
WHERE {
  ?singer a :singer ;
            :name ?name ;
            :birth_year ?birth_year ;
            :citizenship ?citizenship .
}

