PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?creatureCount)
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment [
             rdf:type :Alignment ;
             :hasName ?alignmentName
           ] ;
           :hasLanguages [
             rdf:type :Language ;
             :hasName "TreantL"
           ] .
  FILTER(LCASE(?alignmentName) != "true neutral")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?spellLabel
WHERE {
  {
    ?aasimar a :Beast ;
             :hasName "Aasimar" ;
             :canSpell ?commonSpell .
  }
  {
    ?caypup a :Beast ;
            :hasName "Caypup" ;
            :canSpell ?commonSpell .
  }
  ?commonSpell :hasName ?spellLabel .
}
GROUP BY ?spellLabel

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beastAbyssalAklo) AS ?countAbyssalAklo)
       (COUNT(?beastInfernalTerran) AS ?countInfernalTerran)
WHERE {
  {
    SELECT DISTINCT ?beastAbyssalAklo
    WHERE {
      ?beastAbyssalAklo a :Beast ;
                      :hasLanguages [
                        :hasName ?languageName1 ;
                        :spokenBy ?beastAbyssalAklo
                      ] ;
                      :hasLanguages [
                        :hasName ?languageName2 ;
                        :spokenBy ?beastAbyssalAklo
                      ]
      FILTER(CONTAINS(LCASE(?languageName1), "abyssall") && CONTAINS(LCASE(?languageName2), "aklol"))
    }
  }
  {
    SELECT DISTINCT ?beastInfernalTerran
    WHERE {
      ?beastInfernalTerran a :Beast ;
                           :hasLanguages [
                             :hasName ?languageName3 ;
                             :spokenBy ?beastInfernalTerran
                           ] ;
                           :hasLanguages [
                             :hasName ?languageName4 ;
                             :spokenBy ?beastInfernalTerran
                           ]
      FILTER(CONTAINS(LCASE(?languageName3), "infernall") && CONTAINS(LCASE(?languageName4), "terranl"))
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastName
WHERE {
  ?beast a :Beast ;
           :hasAlignment ?alignment ;
           :hasName ?beastName .
  ?alignment a :Alignment ;
             :hasName "NeutralGood" .
  FILTER(CONTAINS(LCASE(?beastName), "troll"))
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?percentage 
WHERE {
  {
    SELECT (COUNT(?dragon) AS ?totalDragons)
    WHERE {
      ?dragon a :Beast ;
              :beastCategoryName "dragon" .
    }
  }
  {
    SELECT (COUNT(?dragon) AS ?dragonsWithBothLanguages)
    WHERE {
      ?dragon a :Beast ;
              :beastCategoryName "dragon" ;
              :hasLanguages ?lang1, ?lang2 .
      ?lang1 :hasName "DraconicL" .
      ?lang2 :hasName "CommonL" .
    }
  }
  BIND((?dragonsWithBothLanguages / ?totalDragons * 100) AS ?percentage)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?dragonLanguages) AS ?AverageDragonLanguages)
WHERE {
  SELECT (COUNT(?language) AS ?dragonLanguages)
  WHERE {
    ?beast rdf:type :Beast ;
           :hasName ?name ;
           :hasLanguages ?language .
    FILTER(CONTAINS(LCASE(STR(?name)), "dragon"))
  }
  GROUP BY ?beast
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel
WHERE {
  ?beast a :Beast ;
           :hasName ?beastLabel .
  ?language1 a :Language ;
             :spokenBy ?beast ;
             :hasName "CommonL" .
  ?language2 a :Language ;
             :spokenBy ?beast ;
             :hasName "UndercommonL" .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beastName
WHERE {
  ?beast a :Beast ;
           :hasAlignment ?alignment ;
           :hasName ?beastName .
  ?alignment a :Alignment ;
               :hasName ?alignmentName .
  FILTER(?alignment = :ChaoticEvil || ?alignment = :ChaoticNeutral)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ?troxLanguageCount ?sunlordLanguageCount
WHERE {
  {
    SELECT (COUNT(?lang) AS ?troxLanguageCount)
    WHERE { :Trox :hasLanguages ?lang }
  }

  {
    SELECT (COUNT(?lang) AS ?sunlordLanguageCount)
    WHERE { :Sunlord :hasLanguages ?lang }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?alignmentName (COUNT(?beast) AS ?count)
WHERE {
  ?language rdf:type :Language ;
            :hasName "AuranL" .
  ?beast rdf:type :Beast ;
         :hasLanguages ?language ;
         :hasAlignment ?alignment .
  ?alignment rdf:type :Alignment ;
             :hasName ?alignmentName .
}
GROUP BY ?alignmentName
ORDER BY ASC(?count)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?skeletonCount ?zombieCount
WHERE {
  {
    SELECT (COUNT(?skeleton) AS ?skeletonCount)
    WHERE {
      ?skeleton rdf:type :Beast ;
                :beastCategoryName "skeleton" ;
                :hasAlignment ?alignment .
      ?alignment :hasName ?alignmentName .
      FILTER(LCASE(?alignmentName) = "true neutral")
    }
  }
  {
    SELECT (COUNT(?zombie) AS ?zombieCount)
    WHERE {
      ?zombie rdf:type :Beast ;
              :beastCategoryName "zombie" ;
              :hasAlignment ?alignment .
      ?alignment :hasName ?alignmentName .
      FILTER(LCASE(?alignmentName) = "true neutral")
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?ravenAlignmentLabel ?ghoulAlignmentLabel
WHERE {
  ?raven rdf:type :Beast ;
           :hasName "Raven" ;
           :hasAlignment ?ravenAlignment .
  ?ravenAlignment :hasName ?ravenAlignmentLabel .

  ?ghoul rdf:type :Beast ;
           :hasName "Ghoul Hound Companion" ;
           :hasAlignment ?ghoulAlignment .
  ?ghoulAlignment :hasName ?ghoulAlignmentLabel .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ((COUNT(?chaoticWolf) / COUNT(?wolf)) * 100 AS ?percentage)
WHERE {
    {
        SELECT (COUNT(?beast) AS ?wolf)
        WHERE {
            ?beast a :Beast ;
                     :hasName ?name .
            FILTER(CONTAINS(LCASE(STR(?name)), "wolf"))
        }
    }
    {
        SELECT (COUNT(?beast) AS ?chaoticWolf)
        WHERE {
            ?beast a :Beast ;
                     :hasName ?name ;
                     :hasAlignment ?alignment .
            FILTER(CONTAINS(LCASE(STR(?name)), "wolf"))
            VALUES ?alignment { :ChaoticEvil :ChaoticGood :ChaoticNeutral }
        }
    }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?percentage 
WHERE {
  {
    SELECT (COUNT(?angel) AS ?totalAngels)
    WHERE {
      ?angel rdf:type :Beast ;
               :beastCategoryName "angel" .
    }
  }
  {
    SELECT (COUNT(?angelWithAquanL) AS ?angelsWithAquanL)
    WHERE {
      ?angelWithAquanL rdf:type :Beast ;
                       :beastCategoryName "angel" ;
                       :hasLanguages ?language .
      ?language :hasName ?langName .
      FILTER(LCASE(?langName) = "aquanl")
    }
  }
  BIND((?angelsWithAquanL / ?totalAngels * 100) AS ?percentage)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (AVG(?langCount) AS ?averageLanguages)
WHERE {
  ?beast a :Beast .
  OPTIONAL {
    ?beast :hasLanguages/rdf:rest*/rdf:first ?language .
  }
  BIND(COUNT(DISTINCT ?language) AS ?langCount)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?speedValue) AS ?meanSpeedValue)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?name ;
           :beastCategoryName "spider" ;
           :hasSpeedValue ?speedValue .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel ?speedValue
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?beastLabel ;
           :hasSpeedValue ?speedValue ;
           :hasAlignment/:hasName "chaotic evil" .
}
ORDER BY DESC(?speedValue)
LIMIT 5

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?hp) AS ?maxHP)
WHERE {
  ?beast a :Beast ;
           :hasAlignment/:hasName "Chaotic Good" ;
           :hasHPValue ?hp .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (MIN(?initValue) AS ?minInitiative)
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment ?alignment ;
           :hasInitValue ?initValue .
  ?alignment rdf:type :Alignment ;
               :hasName ?alignmentName .
  FILTER(LCASE(?alignmentName) = "true neutral")
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beast (AVG(?attribute) AS ?meanAttribute)
WHERE {
  VALUES (?beast) { (:Dhampir) (:Gorgon) }
  ?beast a :Beast ;
           [ ?p ?attribute ] .
  FILTER(?p IN (:atk, :cha, :cmb, :cmd, :con, :dex))
}
GROUP BY ?beast
ORDER BY DESC(?meanAttribute)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel ?hasACValue ?hasFortValue ?hasRefValue ?hasWillValue
WHERE {
  VALUES (?beast) { (:Boggard) (:Selkie) }
  ?beast rdf:type :Beast ;
           :hasName ?beastLabel ;
           :hasACValue ?hasACValue ;
           :hasFortValue ?hasFortValue ;
           :hasRefValue ?hasRefValue ;
           :hasWillValue ?hasWillValue .
}
ORDER BY DESC(?hasACValue) DESC(?hasFortValue) DESC(?hasRefValue) DESC(?hasWillValue)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beast (AVG(?defensiveValue) AS ?meanDefensiveAttributes)
WHERE {
  VALUES ?beast { :Centaur :Medusa }
  ?beast a :Beast ;
           :hasACValue ?acValue ;
           :hasFlatFootedValue ?flatfootedValue ;
           :hasFortValue ?fortValue ;
           :hasRefValue ?refValue ;
           :hasWillValue ?willValue .
  BIND((?acValue + ?flatfootedValue + ?fortValue + ?refValue + ?willValue) AS ?defensiveValue)
}
GROUP BY ?beast
ORDER BY DESC(?meanDefensiveAttributes)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?biclopsSum ?mastodonSum
WHERE {
  :Biclops a :Beast ;
             :atk ?biclopsAtk ;
             :cha ?biclopsCha ;
             :cmb ?biclopsCmb ;
             :cmd ?biclopsCmd ;
             :con ?biclopsCon ;
             :dex ?biclopsDex ;
             :hasACValue ?biclopsAc ;
             :hasCRValue ?biclopsCr ;
             :hasFlatFootedValue ?biclopsFlatFooted ;
             :hasFortValue ?biclopsFort .

  :Mastodon a :Beast ;
              :atk ?mastodonAtk ;
              :cha ?mastodonCha ;
              :cmb ?mastodonCmb ;
              :cmd ?mastodonCmd ;
              :con ?mastodonCon ;
              :dex ?mastodonDex ;
              :hasACValue ?mastodonAc ;
              :hasCRValue ?mastodonCr ;
              :hasFlatFootedValue ?mastodonFlatFooted ;
              :hasFortValue ?mastodonFort .

  BIND(?biclopsAtk + ?biclopsCha + ?biclopsCmb + ?biclopsCmd + ?biclopsCon + ?biclopsDex + ?biclopsAc + xsd:integer(?biclopsCr) * 10 + ?biclopsFlatFooted + ?biclopsFort AS ?biclopsSum)
  BIND(?mastodonAtk + ?mastodonCha + ?mastodonCmb + ?mastodonCmd + ?mastodonCon + ?mastodonDex + ?mastodonAc + xsd:integer(?mastodonCr) * 10 + ?mastodonFlatFooted + ?mastodonFort AS ?mastodonSum)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  (AVG(?atk) AS ?avgAtk)
  (AVG(?cha) AS ?avgCha)
  (AVG(?cmb) AS ?avgCmb)
  (AVG(?cmd) AS ?avgCmd)
  (AVG(?dex) AS ?avgDex)
  (AVG(?acValue) AS ?avgACValue)
  (AVG(?crValue) AS ?avgCRValue)
  (AVG(?flatFootedValue) AS ?avgFlatFootedValue)
  (AVG(?fortValue) AS ?avgFortValue)
WHERE {
  ?golem rdf:type :Beast ;
           :beastCategoryName "golem" ;
           :atk ?atk ;
           :cha ?cha ;
           :cmb ?cmb ;
           :cmd ?cmd ;
           :dex ?dex ;
           :hasACValue ?acValue ;
           :hasCRValue ?crValue ;
           :hasFlatFootedValue ?flatFootedValue ;
           :hasFortValue ?fortValue .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?defensiveAttribute) AS ?averageDefensiveAttribute)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?name ;
           :hasACValue ?acValue ;
           :hasFlatFootedValue ?flatFootedValue ;
           :hasFortValue ?fortValue ;
           :hasRefValue ?refValue ;
           :hasTouchValue ?touchValue ;
           :hasWillValue ?willValue .
  FILTER(CONTAINS(LCASE(?name), "ogre"))
  BIND((?acValue + ?flatFootedValue + ?fortValue + ?refValue + ?touchValue + ?willValue) / 6 AS ?defensiveAttribute)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel ?atk
WHERE {
  ?beast a :Beast ;
           :hasLanguages [ :hasName "AkloL" ] ;
           :atk ?atk ;
           :hasName ?beastLabel .
}
ORDER BY DESC(?atk)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?count)
WHERE {
  ?alignment a :Alignment ;
             :hasName "Neutral Evil" .

  ?beast a :Beast ;
         :hasAlignment ?alignment ;
         :cmb ?cmbValue .
  FILTER(?cmbValue < 4)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?demon) AS ?numberOfDemons)
WHERE {
  {
    SELECT (AVG(?cmdValue) AS ?avgCMD)
    WHERE {
      ?creature a :Beast ;
                :hasCmdValue ?cmdValue .
    }
  }
  ?demon a :Beast ;
         :beastCategoryName "demon" ;
         :hasCmdValue ?demonCMD .
  FILTER(?demonCMD > ?avgCMD)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (MAX(?cmdValue) AS ?maxCMD)
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment :NeutralGood ;
           :hasCMD ?cmdValue .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?flatFootedValue) AS ?minFlatFootedValue)
WHERE {
  ?beast a :Beast ;
           :hasAlignment ?alignment ;
           :hasFlatFootedValue ?flatFootedValue .
  ?alignment a :Alignment ;
               :hasName ?alignmentName .
  FILTER(LCASE(?alignmentName) = "lawfulgood")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?trollCount)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?name ;
           :beastCategoryName "troll" ;
           :hasFlatFootedValue ?flatFootedValue .
  FILTER(?flatFootedValue >= 13 && ?flatFootedValue <= 18)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beastName
WHERE {
  ?beast a :Beast ;
           :hasAlignment [ :hasName ?alignmentName ] ;
           :hasFortValue "6"^^xsd:integer ;
           :hasName ?beastName .
  FILTER(LCASE(?alignmentName) = "truenatural")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?hp) AS ?averageHP)
WHERE {
  ?beast a :Beast ;
           :hasLanguages ?language ;
           :hasHPValue ?hp .
  ?language a :Language ;
            :hasName ?langName .
  FILTER(LCASE(?langName) = "gnomel")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?hp) AS ?minHP)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?name ;
           :str ?strength ;
           :hasHPValue ?hp .
  FILTER(CONTAINS(LCASE(STR(?name)), "dragon"))
  FILTER(?strength > 10)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?creatureCount)
WHERE {
  ?beast rdf:type :Beast ;
           :hasLanguages ?language ;
           :hasRefValue ?refValue ;
           :atk ?attack .
  ?language rdf:type :Language ;
            :hasName "HalflingL" .
  FILTER(?refValue > 10 && ?attack < 15)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ?beastName
WHERE {
    ?beast rdf:type :Beast ;
           :hasName ?beastName ;
           :hasTouchValue 11 .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?willValue) AS ?averageWillValue)
WHERE {
  ?beast a :Beast ;
           :hasLanguages [ a :Language ; :hasName "OrcL" ] ;
           :hasWillValue ?willValue .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastName
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment ?alignment ;
           :cha ?cha ;
           :str ?str ;
           :int ?int .
  ?alignment :hasName "LawfulEvil" .
  FILTER(?cha > (?str + ?int))
  ?beast :hasName ?beastName .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?count)
WHERE {
  ?language a :Language ;
            :hasName "ProteanL" .
  ?beast a :Beast ;
         :hasLanguages ?language ;
         :con ?constitution .
  FILTER(?constitution > 10)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (MAX(?con) AS ?maxConstitution)
WHERE {
  ?beast rdf:type :Beast ;
           :beastCategoryName "elemental" ;
           :con ?con .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?dex) AS ?averageDex)
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment ?alignment ;
           :dex ?dex .
  ?alignment rdf:type :Alignment ;
               :hasName ?alignmentName .
  FILTER(CONTAINS(LCASE(STR(?alignmentName)), "true neutral"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?beastLabel ;
           :dex ?beastDex .
  ?language rdf:type :Language ;
              :hasName "AbolethL" ;
              :spokenBy ?beast .
  {
    SELECT (AVG(?dex) AS ?averageDex)
    WHERE {
      ?b :rdf:type :Beast ;
           :dex ?dex .
    }
  }
  FILTER (?beastDex > ?averageDex)
}
GROUP BY ?beastLabel

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?robot) AS ?robotCount)
WHERE {
  ?robot rdf:type :Beast ;
           :beastCategoryName "robot" ;
           :int ?intelligence ;
           :hasSpeedValue ?speed .
  FILTER(?intelligence < 7 && ?speed > 10)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (MIN(?intelligence) AS ?minIntelligence)
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment/:hasName "Chaotic Neutral" ;
           :int ?intelligence .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?golemName
WHERE {
  ?golem rdf:type :Beast ;
           :beastCategoryName "golem" ;
           :str ?strength ;
           :cha ?charisma .
  FILTER(?strength < ?charisma)
  OPTIONAL { ?golem :hasName ?name }
  BIND(COALESCE(?name, "") AS ?golemName)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?wis) AS ?averageWisdom)
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment ?alignment ;
           :wis ?wis .
  ?alignment rdf:type :Alignment ;
             :hasName ?alignmentName .
  FILTER(LCASE(STR(?alignmentName)) = "lawfulneutral")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT 
  (SUM(?atk) AS ?totalAtk)
  (SUM(?cha) AS ?totalCha)
  (SUM(?cmb) AS ?totalCmb)
  (SUM(?cmd) AS ?totalCmd)
  (SUM(?con) AS ?totalCon)
  (SUM(?dex) AS ?totalDex)
  (SUM(?hasACValue) AS ?totalAC)
  (SUM(?hasCRValue) AS ?totalCR)
  (SUM(?hasFlatFootedValue) AS ?totalFlatFooted)
  (SUM(?hasFortValue) AS ?totalFort)
WHERE {
  ?beast rdf:type :Beast ;
           :hasLanguages ?lang1 ;
           :hasLanguages ?lang2 .
  ?lang1 :hasName "GnollL" .
  ?lang2 :hasName "ElvenL" .
  ?beast :atk ?atk ;
           :cha ?cha ;
           :cmb ?cmb ;
           :cmd ?cmd ;
           :con ?con ;
           :dex ?dex ;
           :hasACValue ?hasACValue ;
           :hasCRValue ?hasCRValue ;
           :hasFlatFootedValue ?hasFlatFootedValue ;
           :hasFortValue ?hasFortValue .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?androsphinxSum ?bloodQueenSum WHERE {
  ?androsphinx rdf:type :Beast ;
               :hasName "Androsphinx" ;
               :int ?androsphinxInt ;
               :wis ?androsphinxWis .
  BIND(?androsphinxInt + ?androsphinxWis AS ?androsphinxSum)

  ?bloodQueen rdf:type :Beast ;
              :hasName "Blood Queen" ;
              :int ?bloodQueenInt ;
              :wis ?bloodQueenWis .
  BIND(?bloodQueenInt + ?bloodQueenWis AS ?bloodQueenSum)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastName ?conValue
WHERE {
  ?language rdf:type :Language ;
            :hasName ?languageName .
  FILTER(CONTAINS(LCASE(?languageName), "ghoull")) .
  ?beast rdf:type :Beast ;
         :hasLanguages ?language ;
         :hasName ?beastName ;
         :con ?conValue .
}
ORDER BY DESC(?conValue)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?DarkLCount ?CyclopsLCount 
WHERE {
  {
    SELECT (COUNT(?beast) AS ?DarkLCount)
    WHERE {
      ?beast a :Beast ;
               :hasLanguages ?language .
      ?language :hasName "DarkL" .
    }
  }
  {
    SELECT (COUNT(?beast) AS ?CyclopsLCount)
    WHERE {
      ?beast a :Beast ;
               :hasLanguages ?language .
      ?language :hasName "CyclopsL" .
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?beastPolyglot) > COUNT(?beastSkald) AS ?isGreater)
WHERE {
  {
    SELECT DISTINCT ?beastPolyglot
    WHERE {
      ?beastPolyglot a :Beast ;
                     :hasLanguages/:hasName "Polyglot L" .
    }
  }
  {
    SELECT DISTINCT ?beastSkald
    WHERE {
      ?beastSkald a :Beast ;
                  :hasLanguages/:hasName "SkaldL" .
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?avgAngelXP ?avgDemonXP 
WHERE {
  {
    SELECT (AVG(?xp) AS ?avgAngelXP)
    WHERE {
      ?angel rdf:type :Beast ;
               :beastCategoryName "angel" ;
               :hasXPValue ?xp .
    }
  }
  {
    SELECT (AVG(?xp) AS ?avgDemonXP)
    WHERE {
      ?demon rdf:type :Beast ;
               :beastCategoryName "demon" ;
               :hasXPValue ?xp .
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (AVG(?dex) AS ?averageDex)
WHERE {
  VALUES ?beast { :Phoenix :Sleipnir }
  ?beast a :Beast ;
           :hasName ?name ;
           :dex ?dex .
  FILTER(CONTAINS(LCASE(STR(?name)), "phoenix") || CONTAINS(LCASE(STR(?name)), "sleipnir"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (MAX(?constitution) AS ?maxConstitution)
WHERE {
  VALUES ?beastName { "Kraken" "Leviathan" }
  ?beast a :Beast ;
           :hasName ?name ;
           :con ?constitution .
  FILTER(CONTAINS(LCASE(?name), LCASE(?beastName)))
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?cityLabel
WHERE {
  ?hardware rdf:type pv:Hardware ;
            rdfs:label ?hardwareLabel ;
            hasCategory ?category ;
            hasSupplier ?supplier .
  ?category rdf:type pv:ProductCategory ;
            rdfs:label ?categoryLabel .
  FILTER(CONTAINS(LCASE(?categoryLabel), "lcd"))
  ?supplier rdf:type pv:Supplier ;
            pv:country ?country ;
            rdfs:label ?supplierLabel .
  ?country rdf:type dbo:Country ;
           pv:name ?countryName .
  FILTER(CONTAINS(LCASE(?countryName), "us"))
  OPTIONAL { ?country rdfs:label ?cityLabel }
  BIND(COALESCE(?cityLabel, ?countryName) AS ?cityLabel)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?supplierLabel (ROUND(AVG(?priceAmount)) AS ?averagePriceEUR)
WHERE {
  ?product pv:hasSupplier ?supplier ;
           pv:price ?price .
  ?supplier rdfs:label ?supplierLabel .
  ?price pv:currency "EUR" ;
         pv:amount ?priceAmount .
}
GROUP BY ?supplierLabel

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?bomLabel (COUNT(?part) AS ?numParts) (SUM(xsd:decimal(?quantity)) AS ?totalQuantity)
WHERE {
  ?bom rdf:type pv:BillOfMaterial ;
       rdfs:label ?bomLabel .
  ?bom pv:hasBomPart ?bomPart .
  ?bomPart pv:hasPart ?part ;
           pv:quantity ?quantity .
}
GROUP BY ?bom ?bomLabel
HAVING (SUM(xsd:decimal(?quantity)) > 600)
ORDER BY DESC(?totalQuantity)

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?hardwareId ?hardwareName ?width_mm
WHERE {
  ?hardware rdf:type pv:Hardware ;
            pv:id ?hardwareId ;
            pv:name ?hardwareName ;
            pv:width_mm ?width_mm .
}
ORDER BY DESC(?width_mm)
LIMIT (SELECT ceil(count(*) * 0.1) WHERE { ?h rdf:type pv:Hardware })

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?state WHERE {
  ?owner a :owners ;
           :state ?state .
  ?professional a :professionals ;
                :state ?state .
} GROUP BY ?state

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?state
WHERE {
  {
    ?owner rdf:type :owners ;
             :state ?state .
  }
  UNION
  {
    ?professional rdf:type :professionals ;
                    :state ?state .
  }
}
GROUP BY ?state
HAVING (COUNT(DISTINCT ?owner) > 0 && COUNT(DISTINCT ?professional) > 0)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?professional_id ?last_name ?cell_number
WHERE {
  {
    ?professional a :professionals ;
                  :state "Indiana" ;
                  :professional_id ?professional_id ;
                  :last_name ?last_name ;
                  :cell_number ?cell_number .
  }
  UNION
  {
    SELECT ?professional_id ?last_name ?cell_number (COUNT(?treatment) AS ?treatment_count)
    WHERE {
      ?professional a :professionals ;
                    :professional_id ?professional_id ;
                    :last_name ?last_name ;
                    :cell_number ?cell_number .
      ?treatment a :treatments ;
                 :ref-professional ?professional .
    }
    GROUP BY ?professional_id ?last_name ?cell_number
    HAVING (?treatment_count > 2)
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professional_id ?last_name ?cell_number
WHERE {
  {
    ?professional a :professionals ;
                  :professional_id ?professional_id ;
                  :last_name ?last_name ;
                  :cell_number ?cell_number ;
                  :state "Indiana" .
  }
  UNION
  {
    SELECT ?professional_id ?last_name ?cell_number
    WHERE {
      ?professional a :professionals ;
                    :professional_id ?professional_id ;
                    :last_name ?last_name ;
                    :cell_number ?cell_number .
      {
        SELECT ?professional (COUNT(?treatment) AS ?numTreatments)
        WHERE {
          ?treatment a :treatments ;
                     :ref-professional ?professional .
        }
        GROUP BY ?professional
        HAVING (?numTreatments > 2)
      }
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?dogName
WHERE {
    ?treatment a :treatments ;
               :cost_of_treatment ?cost ;
               :ref-dog ?dog .
    ?dog a :dogs ;
         :name ?dogName .
    FILTER(?cost <= 1000)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?firstName
WHERE {
  { ?entity a :professionals ; :first_name ?firstName . }
  UNION
  { ?entity a :owners ; :first_name ?firstName . }
  MINUS {
    ?dog a :dogs ; :name ?firstName .
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?firstName
WHERE {
  { ?professional a :professionals ; :first_name ?firstName }
  UNION
  { ?owner a :owners ; :first_name ?firstName }
  MINUS
  { ?dog a :dogs ; :name ?firstName }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?professional_id ?role_code ?email_address
WHERE {
  ?professional rdf:type :professionals ;
                :professional_id ?professional_id ;
                :role_code ?role_code ;
                :email_address ?email_address .
  FILTER NOT EXISTS {
    ?treatment rdf:type :treatments ;
               :ref-professional ?professional .
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?professional_id ?role_code ?email_address
WHERE {
  ?professional a :professionals ;
                :professional_id ?professional_id ;
                :role_code ?role_code ;
                :email_address ?email_address .
  FILTER NOT EXISTS {
    ?treatment a :treatments ;
               :ref-professional ?professional .
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?owner_id ?first_name ?last_name (COUNT(?dog) AS ?dog_count)
WHERE {
  ?dog a :dogs ;
         :ref-owner ?owner .
  ?owner a :owners ;
           :owner_id ?owner_id ;
           :first_name ?first_name ;
           :last_name ?last_name .
}
GROUP BY ?owner_id ?first_name ?last_name
ORDER BY DESC(?dog_count)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?owner_id ?first_name ?last_name
WHERE {
  ?dog a :dogs ;
         :ref-owner ?owner .
  ?owner a :owners ;
           :owner_id ?owner_id ;
           :first_name ?first_name ;
