PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?courseName ?courseId (COUNT(?section) AS ?sectionCount)
WHERE {
  ?course a :courses ;
            :course_name ?courseName ;
            :course_id ?courseId .
  OPTIONAL {
    ?section a :sections ;
             :ref-course ?course .
  }
}
GROUP BY ?courseName ?courseId
HAVING (?sectionCount <= 2)

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?course_name ?course_id
WHERE {
  {
    SELECT ?course (COUNT(?section) AS ?section_count)
    WHERE {
      ?course a :courses .
      OPTIONAL { 
        ?section a :sections ;
                 :ref-course ?course .
      }
    }
    GROUP BY ?course
    HAVING (?section_count < 2)
  }
  ?course :course_name ?course_name ;
          :course_id ?course_id .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?semesterName ?semesterId (COUNT(?student) AS ?studentCount)
WHERE {
  ?enrolment rdf:type :student_enrolment ;
             :ref-student ?student ;
             :ref-semester ?semester .
  ?semester rdf:type :semesters ;
            :semester_name ?semesterName ;
            :semester_id ?semesterId .
}
GROUP BY ?semesterName ?semesterId
ORDER BY DESC(?studentCount)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?firstName ?middleName ?lastName ?studentId
WHERE {
  ?student rdf:type :students ;
           :first_name ?firstName ;
           :middle_name ?middleName ;
           :last_name ?lastName ;
           :student_id ?studentId .
  {
    SELECT ?studentId (COUNT(DISTINCT ?degreeProgram) AS ?programCount)
    WHERE {
      ?enrolment :ref-degree_program ?degreeProgram ;
                 :student_id ?studentId .
    }
    GROUP BY ?studentId
    HAVING (?programCount = 2)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?first_name ?middle_name ?last_name ?student_id
WHERE {
  ?student rdf:type :students ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name ;
           :student_id ?student_id .

  ?enrolment :ref-student ?student ;
             :semester_id ?semester_id ;
             :degree_program_id ?degreeProgramId1 .

  ?enrolment2 :ref-student ?student ;
              :semester_id ?semester_id ;
              :degree_program_id ?degreeProgramId2 .

  FILTER(?degreeProgramId1 != ?degreeProgramId2)
}
GROUP BY ?first_name ?middle_name ?last_name ?student_id
HAVING (COUNT(DISTINCT ?degreeProgramId1) >= 2)

