PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?student_id ?first_name ?middle_name ?last_name (COUNT(?enrolment) AS ?number_of_enrollments)
WHERE {
  ?enrolment rdf:type :student_enrolment ;
             :ref-student ?student .
  ?student rdf:type :students ;
           :student_id ?student_id ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name .
}
GROUP BY ?student_id ?first_name ?middle_name ?last_name
ORDER BY DESC(?number_of_enrollments)
LIMIT 1

