WHERE {
  ?student rdf:type :students ;
           :ref-current_address ?address ;
           :last_name ?lastName .
  ?address :state_province_county "North Carolina" .
  FILTER NOT EXISTS {
    ?enrolment :ref-student ?student ;
               :ref-degree_program ?degreeProgram .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?transcript_id ?transcript_date
WHERE {
  ?transcript a :transcripts ;
              :transcript_id ?transcript_id ;
              :transcript_date ?transcript_date .
  {
    SELECT ?transcript (COUNT(?tc) AS ?courseCount)
    WHERE {
      ?tc :ref-transcript ?transcript .
    }
    GROUP BY ?transcript
    HAVING (?courseCount >= 2)
  }
}
GROUP BY ?transcript_id ?transcript_date

