PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?address_id ?line_1 ?line_2
WHERE {
    ?student a :students ;
               :ref-current_address/:address_id ?address_id .
    ?address a :addresses ;
               :address_id ?address_id ;
               :line_1 ?line_1 ;
               :line_2 ?line_2 .
}
GROUP BY ?address_id ?line_1 ?line_2
ORDER BY DESC(COUNT(?student))
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?maxCount ?enrollmentId
WHERE {
  {
    SELECT (COUNT(?course) AS ?maxCount) ?studentCourseId
    WHERE {
      ?transcriptContents :ref-student_course ?studentEnrolmentCourses .
      ?studentEnrolmentCourses :course_id ?course .
      ?studentEnrolmentCourses :student_enrolment_id ?studentCourseId .
    }
    GROUP BY ?studentCourseId
    ORDER BY DESC(?maxCount)
    LIMIT 1
  }
  ?studentEnrolmentCourses :student_enrolment_id ?enrollmentId .
  FILTER (?studentEnrolmentCourses :student_enrolment_id = ?studentCourseId)
}

