PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?transcript_id ?transcript_date (COUNT(?student_course) AS ?result_count)
WHERE {
  ?transcript a :transcripts ;
              :transcript_id ?transcript_id ;
              :transcript_date ?transcript_date .
  OPTIONAL { 
    ?transcript_contents :ref-transcript ?transcript ;
                         :ref-student_course ?student_course .
  }
}
GROUP BY ?transcript ?transcript_id ?transcript_date
ORDER BY ASC(?result_count)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
