PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?addressLine1 ?city ?stateProvinceCounty ?country ?zipPostcode
WHERE {
  ?student a :students ;
             (:ref-current_address | :ref-permanent_address) ?address .
  ?address a :addresses ;
             :line_1 ?addressLine1 ;
             :city ?city ;
             :state_province_county ?stateProvinceCounty ;
             :country ?country ;
             :zip_postcode ?zipPostcode .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
