PREFIX : <http://valuenet/ontop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?student_id ?first_name ?last_name ?middle_name ?email_address ?cell_mobile_number ?date_first_registered ?date_left ?other_student_details
WHERE {
  ?student a :students ;
             :student_id ?student_id ;
             :first_name ?first_name ;
             :last_name ?last_name ;
             :middle_name ?middle_name ;
             :email_address ?email_address ;
             :cell_mobile_number ?cell_mobile_number ;
             :date_first_registered ?date_first_registered ;
             :date_left ?date_left ;
             :other_student_details ?other_student_details .
}
ORDER BY DESC(?first_name) DESC(?last_name)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
