PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?studentFirstName ?studentLastName ?cellMobileNumber ?emailAddress ?dateFirstRegistered ?dateLeft ?otherStudentDetails
WHERE {
  ?student rdf:type :students ;
           :first_name ?studentFirstName ;
           :last_name ?studentLastName ;
           :cell_mobile_number ?cellMobileNumber ;
           :email_address ?emailAddress ;
           :date_first_registered ?dateFirstRegistered ;
           :date_left ?dateLeft ;
           :other_student_details ?otherStudentDetails .
}
ORDER BY DESC(?studentLastName) DESC(?studentFirstName)

