PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?firstName
WHERE {
  {
    ?student a :students ;
               :first_name ?firstName ;
               :ref-permanent_address [ :country "Haiti" ] .
  }
  UNION
  {
    ?student a :students ;
               :first_name ?firstName ;
               :cell_mobile_number "09700166582" .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?firstName
WHERE {
  ?student a :students ;
             :first_name ?firstName .
  FILTER(?student :cell_mobile_number = "09700166582" || 
         EXISTS { 
           ?student :ref-permanent_address ?permanentAddress .
           ?permanentAddress a :addresses ;
                           :country "Haiti" .
         })
}

