PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?language
WHERE {
  ?country rdf:type :country ;
           :governmentform "republic" ;
           :ref-countrycode ?countryCode .
  ?countryLanguage rdf:type :countrylanguage ;
                   :ref-countrycode ?countryCode ;
                   :language ?language .
  FILTER(?language != "")
}
GROUP BY ?language
HAVING (COUNT(DISTINCT ?country) = 1)

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?languageLabel
WHERE {
  ?country rdf:type :country ;
           :governmentform "republic"^^xsd:string .
  ?countrylanguage rdf:type :countrylanguage ;
                   :ref-countrycode ?country ;
                   :language ?language .
  FILTER NOT EXISTS {
    ?otherCountry rdf:type :country ;
                  :governmentform "republic"^^xsd:string ;
                  != ?country .
    ?otherCountryLanguage rdf:type :countrylanguage ;
                        :ref-countrycode ?otherCountry ;
                        :language ?language .
  }
  OPTIONAL { ?language rdfs:label ?languageLabel }
  BIND(COALESCE(?languageLabel, STR(?language)) AS ?languageLabel)
}
GROUP BY ?language ?languageLabel
HAVING (COUNT(DISTINCT ?country) = 1)

