WHERE {
  ?country a :country ;
           :indepyear ?indepYear .
  FILTER(?indepYear < 1930)
  ?langInfo a :countrylanguage ;
            :ref-countrycode ?country ;
            :isofficial "T" ;
            :language ?language .
}

