  ?countrylanguage rdf:type :countrylanguage ;
                   :ref-countrycode ?country ;
                   :isofficial "T" ;
                   :language ?language .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryLabel
WHERE {
  ?country rdf:type :country ;
           :surfacearea ?surfaceArea .
  {
    SELECT (MAX(?europeSurfaceArea) AS ?maxEuropeSurfaceArea)
    WHERE {
      ?europeCountry rdf:type :country ;
                     :continent "Europe"^^xsd:string ;
                     :surfacearea ?europeSurfaceArea .
    }
  }
  FILTER(?surfaceArea > ?maxEuropeSurfaceArea)
  OPTIONAL { ?country :name ?countryLabel }
}
GROUP BY ?country ?countryLabel
HAVING (?countryLabel != "")

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  ?europeCountry rdf:type :country ;
                 :region "Europe" ;
                 :surfacearea ?maxEuropeArea .
  FILTER NOT EXISTS {
    ?otherEuropeCountry rdf:type :country ;
                        :region "Europe" ;
                        :surfacearea ?otherEuropeArea .
    FILTER(?otherEuropeArea > ?maxEuropeArea)
  }
  ?country rdf:type :country ;
           :name ?countryName ;
           :surfacearea ?countryArea .
  FILTER(?countryArea > ?maxEuropeArea)
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName (MIN(?asianPopulation) AS ?minAsianPopulation)
WHERE {
  ?country rdf:type :country ;
           :continent "Africa" ;
           :population ?africanPopulation .
  ?asianCountry rdf:type :country ;
                :continent "Asia" ;
                :population ?asianPopulation .
}
GROUP BY ?countryName
HAVING (?africanPopulation < ?minAsianPopulation)

