PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?africanCountryName
WHERE {
  ?africanCountry rdf:type :country ;
                  :continent "Africa" ;
                  :population ?africanPopulation .

  ?asianCountry rdf:type :country ;
                :continent "Asia" ;
                :population ?asiaPopulation .

  FILTER(?africanPopulation < ?asiaPopulation)

  ?africanCountry :name ?africanCountryName
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  ?asianCountry rdf:type :country ;
                :continent "Asia" ;
                :population ?asianPopulation .
  FILTER NOT EXISTS {
    ?africanCountry rdf:type :country ;
                    :continent "Africa" ;
                    :population ?africanPopulation .
    FILTER(?africanPopulation >= ?asianPopulation)
  }
  ?asianCountry :name ?countryName
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryLabel
WHERE {
  {
    SELECT (MAX(?africanPopulation) AS ?maxAfricanPopulation)
    WHERE {
      ?africanCountry rdf:type :country ;
                      :continent "Africa" ;
                      :population ?africanPopulation .
    }
  }
  ?asianCountry rdf:type :country ;
                :continent "Asia" ;
                :population ?asianPopulation ;
                :name ?countryLabel .
  FILTER(?asianPopulation > ?maxAfricanPopulation)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
