PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryCode
WHERE {
  ?country a :country ;
             :code ?countryCode .
  FILTER NOT EXISTS {
    ?lang a :countrylanguage ;
            :ref-countrycode ?country ;
            :language "English" .
  }
}

