PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryCode
WHERE {
  ?country a :country ;
           :code ?countryCode ;
           :governmentform ?governmentForm .
  FILTER(LCASE(?governmentForm) != "republic")

  OPTIONAL {
    ?language a :countrylanguage ;
              :ref-countrycode ?country ;
              :language "English" .
