PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName ?language (MAX(?percentage) AS ?maxPercentage)
WHERE {
  ?countryLanguage a :countrylanguage ;
                   :ref-countrycode ?country ;
                   :language ?language ;
                   :percentage ?percentage .
  ?country a :country ;
           :name ?countryName .
}
GROUP BY ?countryName ?language
HAVING (?percentage = MAX(?percentage))

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countrycode ?language (MAX(?percentage) AS ?maxPercentage)
WHERE {
  ?cl a :countrylanguage ;
        :countrycode ?countrycode ;
        :language ?language ;
        :percentage ?percentage .
}
GROUP BY ?countrycode ?language

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?country) AS ?totalCountries)
WHERE {
  ?languageInstance a :countrylanguage ;
                  :language "Spanish" ;
                  :percentage ?percentage .
  ?languageInstance :ref-countrycode ?country .
  FILTER NOT EXISTS {
    ?otherLanguageInstance a :countrylanguage ;
                         :ref-countrycode ?country ;
                         :language "Spanish" ;
                         :percentage ?otherPercentage .
    FILTER(?otherPercentage > ?percentage)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?country) AS ?numberOfCountries)
WHERE {
  ?languageInstance a :countrylanguage ;
                    :language "Spanish" ;
                    :percentage ?percentage ;
                    :ref-countrycode ?country .
  FILTER(?percentage > 50.0)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (COUNT(?caypupAbil) AS ?caypupCount) (COUNT(?aasimarAbil) AS ?aasimarCount)
WHERE {
  OPTIONAL { 
    ?caypup a :Beast ;
              :hasName "Caypup" ;
              :hasSpecAbils ?caypupAbil .
  }
  OPTIONAL { 
    ?aasimar a :Beast ;
               :hasName "Aasimar" ;
               :hasSpecAbils ?aasimarAbil .
  }
}
GROUP BY (:Caypup) (:Aasimar)

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?beast1) > COUNT(?beast2) AS ?result)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?beast1) AS ?count1)
    WHERE {
      ?beast1 rdf:type :Beast ;
              :hasLanguages / :hasName ?languageName .
      FILTER(CONTAINS(LCASE(?languageName), "abyssall") && CONTAINS(LCASE(?languageName), "aklol"))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?beast2) AS ?count2)
    WHERE {
      ?beast2 rdf:type :Beast ;
              :hasLanguages / :hasName ?languageName .
      FILTER(CONTAINS(LCASE(?languageName), "infernall") && CONTAINS(LCASE(?languageName), "terranl"))
    }
  }
}
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?beast) AS ?robotCount)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?name ;
           :beastCategoryName "robot" .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastName
WHERE {
  ?coldResists a :Resists ;
               :hasName "Cold" .
  ?beast a :Beast ;
         :hasResists ?coldResists ;
         :hasName ?beastName .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?percentage 
WHERE {
  {
    SELECT (COUNT(?dragon) AS ?totalDragons)
    WHERE {
      ?dragon a :Beast ;
                :beastCategoryName "dragon" .
    }
  }
  {
    SELECT (COUNT(?dragon) AS ?dragonsWithBothLanguages)
    WHERE {
      ?dragon a :Beast ;
                :beastCategoryName "dragon" ;
                :hasLanguages ?language1, ?language2 .
      ?language1 :hasName "DraconicL" .
      ?language2 :hasName "CommonL" .
    }
  }
  BIND((?dragonsWithBothLanguages / ?totalDragons * 100) AS ?percentage)
}
FILTER(?totalDragons > 0)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastType (AVG(?languageCount) AS ?averageLanguages)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?beastLabel .
  FILTER(CONTAINS(LCASE(STR(?beastLabel)), "dragon") || CONTAINS(LCASE(STR(?beastLabel)), "demon"))
  BIND(IF(CONTAINS(LCASE(STR(?beastLabel)), "dragon"), "Dragon", "Demon") AS ?beastType)
  {
    SELECT ?beast (COUNT(?language) AS ?languageCount)
    WHERE {
      ?beast :hasLanguages ?language .
    }
    GROUP BY ?beast
  }
}
GROUP BY ?beastType

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>

SELECT (COUNT(?troxLang) AS ?troxLanguagesCount) (COUNT(?sunlordLang) AS ?sunlordLanguagesCount)
WHERE {
  OPTIONAL { :Trox :hasLanguages ?troxLang }
  OPTIONAL { :Sunlord :hasLanguages ?sunlordLang }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(?beast) AS ?count)
WHERE {
  ?beast rdf:type :Beast ;
           :hasAlignment ?alignment ;
           :hasLanguages ?language .
  ?alignment a :Alignment ;
               :hasName ?alignmentName .
  FILTER(CONTAINS(LCASE(?alignmentName), "lawfulneutral"))
  ?language a :Language ;
              :hasName ?languageName .
  FILTER(CONTAINS(LCASE(?languageName), "giantl"))
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?skeletonPercentage ?zombiePercentage 
WHERE {
  {
    SELECT ((COUNT(?skeleton) / COUNT(?beast)) * 100 AS ?skeletonPercentage)
    WHERE {
      ?beast a :Beast ;
             :hasAlignment ?alignment .
      FILTER(CONTAINS(LCASE(STR(?beast)), "skeleton"))
      ?alignment :hasName ?alignmentName .
      FILTER(CONTAINS(LCASE(?alignmentName), "truenatural"))
    }
  }
  {
    SELECT ((COUNT(?zombie) / COUNT(?beast)) * 100 AS ?zombiePercentage)
    WHERE {
      ?beast a :Beast ;
             :hasAlignment ?alignment .
      FILTER(CONTAINS(LCASE(STR(?beast)), "zombie"))
      ?alignment :hasName ?alignmentName .
      FILTER(CONTAINS(LCASE(?alignmentName), "truenatural"))
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ?ravenAlignment ?ghoulAlignment
WHERE {
  ?raven rdf:type :Beast ;
           :hasName "Raven" ;
           :hasAlignment ?ravenAlignment .
  ?ravenAlignment :hasName ?ravenAlignmentLabel .

  ?ghoul rdf:type :Beast ;
           :hasName "Ghoul Hound Companion" ;
           :hasAlignment ?ghoulAlignment .
  ?ghoulAlignment :hasName ?ghoulAlignmentLabel .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?percentage 
WHERE {
  {
    SELECT (COUNT(?beast) AS ?chaoticCount)
    WHERE {
      ?beast a :Beast ;
               :hasAlignment ?alignment .
      FILTER(?alignment IN (:ChaoticEvil, :ChaoticGood, :ChaoticNeutral))
    }
  }
  {
    SELECT (COUNT(?beast) AS ?totalWolves)
    WHERE {
      ?beast a :Beast ;
               :hasName ?name .
      FILTER(CONTAINS(LCASE(?name), "wolf"))
    }
  }
  BIND((?chaoticCount / ?totalWolves * 100) AS ?percentage)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?percentage 
WHERE {
  {
    SELECT (COUNT(?angel) AS ?totalAngels)
    WHERE {
      ?angel rdf:type :Beast ;
             :beastCategoryName "angel" .
    }
  }
  {
    SELECT (COUNT(?angel) AS ?angelsSpeakingAquanL)
    WHERE {
      ?angel rdf:type :Beast ;
             :beastCategoryName "angel" ;
             :hasLanguages ?language .
      ?language rdf:type :Language ;
                :hasName ?langName .
      FILTER(LCASE(?langName) = "aquanl")
    }
  }
  BIND((?angelsSpeakingAquanL / ?totalAngels * 100) AS ?percentage)
}
GROUP BY ?percentage

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?langCount) AS ?averageLanguages)
WHERE {
  ?beast a :Beast .
  OPTIONAL {
    ?beast :hasLanguages _:languageList .
    _:languageList rdf:first _:language .
  }
  BIND(COUNT(DISTINCT _:language) AS ?langCount)
}
GROUP BY ?beast

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel ?speedValue
WHERE {
  ?beast a :Beast ;
           :hasAlignment/:hasName "Chaotic Evil" ;
           :hasSpeedValue ?speedValue ;
           :hasName ?beastLabel .
}
ORDER BY DESC(?speedValue)
LIMIT 5

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (MAX(?hp) AS ?maxHP)
WHERE {
  ?beast a :Beast ;
           :hasAlignment ?alignment ;
           :hasHPValue ?hp .
  ?alignment a :Alignment ;
               :hasName "chaotic good" .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?crValue) AS ?averageCR)
WHERE {
  ?beast a :Beast ;
           :hasLanguages ?language ;
           :hasCRValue ?crValue .
  ?language a :Language ;
            :hasName ?languageLabel .
  FILTER(LCASE(?languageLabel) = "celestiall")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (MIN(?initValue) AS ?minInitiative)
WHERE {
  ?beast a :Beast ;
           :hasAlignment ?alignment ;
           :hasInitValue ?initValue .
  ?alignment a :Alignment ;
             :hasName ?alignmentName .
  FILTER(CONTAINS(LCASE(STR(?alignmentName)), "true neutral"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?golemName ?xpValue
WHERE {
  ?golem a :Beast ;
           :beastCategoryName "golem" ;
           :hasXPValue ?xpValue ;
           :hasName ?golemName .
}
ORDER BY DESC(?xpValue)
LIMIT 3

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?abaiaAtk ?vampireAtk ?abaiaCha ?vampireCha ?abaiaCmb ?vampireCmb ?abaiaCmd ?vampireCmd ?abaiaCon ?vampireCon ?abaiaDex ?vampireDex ?abaiaAcValue ?vampireAcValue ?abaiaCrValue ?vampireCrValue ?abaiaFlatFootedValue ?vampireFlatFootedValue ?abaiaFortValue ?vampireFortValue ?abaiaHpValue ?vampireHpValue
WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Abaia> :hasName "Abaia" ;
           :atk ?abaiaAtk ;
           :cha ?abaiaCha ;
           :cmb ?abaiaCmb ;
           :cmd ?abaiaCmd ;
           :con ?abaiaCon ;
           :dex ?abaiaDex ;
           :hasACValue ?abaiaAcValue ;
           :hasCRValue ?abaiaCrValue ;
           :hasFlatFootedValue ?abaiaFlatFootedValue ;
           :hasFortValue ?abaiaFortValue ;
           :hasHPValue ?abaiaHpValue .
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Vampire> :hasName "vampire" ;
             :atk ?vampireAtk ;
             :cha ?vampireCha ;
             :cmb ?vampireCmb ;
             :cmd ?vampireCmd ;
             :con ?vampireCon ;
             :dex ?vampireDex ;
             :hasACValue ?vampireAcValue ;
             :hasCRValue ?vampireCrValue ;
             :hasFlatFootedValue ?vampireFlatFootedValue ;
             :hasFortValue ?vampireFortValue ;
             :hasHPValue ?vampireHpValue .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast ?hasACValue ?hasFortValue
WHERE {
  VALUES ?beastName { "Boggard" "Selkie" }
  ?beast :hasName ?beastName ;
           :hasACValue ?hasACValue ;
           :hasFortValue ?hasFortValue .
}
ORDER BY DESC(?hasACValue) DESC(?hasFortValue)
LIMIT 2

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?biclopsTotal ?mastodonTotal
WHERE {
  :Biclops 
    :atk ?biclopsAtk ;
    :cha ?biclopsCha ;
    :cmb ?biclopsCmb ;
    :cmd ?biclopsCmd ;
    :con ?biclopsCon ;
    :dex ?biclopsDex ;
    :hasACValue ?biclopsAc ;
    :hasCRValue ?biclopsCr ;
    :hasFlatFootedValue ?biclopsFlatFooted ;
    :hasFortValue ?biclopsFort .

  :Mastodon 
    :atk ?mastodonAtk ;
    :cha ?mastodonCha ;
    :cmb ?mastodonCmb ;
    :cmd ?mastodonCmd ;
    :con ?mastodonCon ;
    :dex ?mastodonDex ;
    :hasACValue ?mastodonAc ;
    :hasCRValue ?mastodonCr ;
    :hasFlatFootedValue ?mastodonFlatFooted ;
    :hasFortValue ?mastodonFort .

  BIND(?biclopsAtk + ?biclopsCha + ?biclopsCmb + ?biclopsCmd + ?biclopsCon + ?biclopsDex + ?biclopsAc + xsd:integer(?biclopsCr) + ?biclopsFlatFooted + ?biclopsFort AS ?biclopsTotal)
  BIND(?mastodonAtk + ?mastodonCha + ?mastodonCmb + ?mastodonCmd + ?mastodonCon + ?mastodonDex + ?mastodonAc + xsd:integer(?mastodonCr) + ?mastodonFlatFooted + ?mastodonFort AS ?mastodonTotal)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?defensiveAttribute) AS ?averageDefensiveAttribute)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?name ;
           :hasACValue ?acValue ;
           :hasFlatFootedValue ?flatFootedValue ;
           :hasFortValue ?fortValue ;
           :hasRefValue ?refValue ;
           :hasWillValue ?willValue .
  FILTER(CONTAINS(LCASE(STR(?name)), "ogre"))
  BIND((?acValue + ?flatFootedValue + ?fortValue + ?refValue + ?willValue) / 5 AS ?defensiveAttribute)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel ?maxAtk
WHERE {
  {
    SELECT (MAX(?atk) AS ?maxAtk)
    WHERE {
      ?otherBeast rdf:type :Beast ;
                  :hasLanguages [ :hasName "AkloL" ] ;
                  :atk ?atk .
    }
  }
  ?beast rdf:type :Beast ;
         :hasLanguages [ :hasName "AkloL" ] ;
         :atk ?atk ;
         :hasName ?beastLabel .
  FILTER(?atk = ?maxAtk)
}
GROUP BY ?beastLabel ?maxAtk

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?count)
WHERE {
  ?alignment a :Alignment ;
             :hasName "Neutral Evil" .
  ?beast a :Beast ;
         :hasAlignment ?alignment ;
         :cmb ?cmbValue .
  FILTER(?cmbValue < 4)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (MIN(?cmb) AS ?minCMB)
WHERE {
  ?beast a :Beast ;
           :hasLanguages ?language ;
           :cmb ?cmb .
  ?language a :Language ;
            :hasName "IgnanL" .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?beast) AS ?NumberOfDemons)
WHERE {
  {
    SELECT (AVG(?cmdValue) AS ?averageCMD)
    WHERE {
      ?beast a :Beast ;
               :hasCMD ?cmdValue .
    }
  }
  ?beast a :Beast ;
           :beastCategoryName "demon" ;
           :hasCMD ?cmdValue .
  FILTER (?cmdValue > ?averageCMD)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (MAX(?cmd) AS ?maxCMD)
WHERE {
  ?beast a :Beast ;
           :hasAlignment ?alignment ;
           :cmd ?cmd .
  ?alignment a :Alignment ;
               :hasName "neutral good" .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastLabel
WHERE {
  ?beast rdf:type :Beast ;
           :hasACValue ?acValue ;
           :hasLanguages ?language .
  ?language :hasName ?languageName .
  FILTER(CONTAINS(LCASE(?languageName), "dwarvenl"))
  FILTER(?acValue > 12)
  OPTIONAL { ?beast :hasName ?beastLabel }
  BIND(COALESCE(?beastLabel, STR(?beast)) AS ?displayLabel)
}
GROUP BY ?displayLabel

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?fortValue) AS ?maxFortValue)
WHERE {
  ?beast a :Beast ;
           :hasLanguages ?language ;
           :hasFortValue ?fortValue .
  ?language a :Language ;
            :hasName "GoblinL" .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastName
WHERE {
  ?beast a :Beast ;
           :hasAlignment [ :hasName ?alignment ] ;
           :hasFortValue "6"^^xsd:integer ;
           :hasName ?beastName .
  FILTER(LCASE(?alignment) = "true neutral")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
