SELECT (MAX(?con) AS ?maxConstitution)
WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?name ;
           :beastCategoryName "elemental" ;
           :con ?con .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?dex) AS ?averageDexterity)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment ?alignment ;
         :dex ?dex .
  ?alignment rdf:type :Alignment ;
             :hasName ?alignmentName .
  FILTER(CONTAINS(LCASE(STR(?alignmentName)), "true neutral"))
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?creatureName
WHERE {
  ?beast :rdf:type :Beast ;
         :hasLanguages :AbolethL ;
         :dex ?dex ;
         :hasName ?creatureName .
}
GROUP BY ?creatureName ?dex
HAVING (?dex > (SELECT AVG(?avgDex) WHERE { 
  SELECT (AVG(?dexterity) AS ?avgDex)
  WHERE {
    ?b :rdf:type :Beast ;
       :dex ?dexterity .
  }
}))

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
