PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT 
  (SUM(?atk) AS ?totalAtk)
  (SUM(?cha) AS ?totalCha)
  (SUM(?cmb) AS ?totalCmb)
  (SUM(?cmd) AS ?totalCmd)
  (SUM(?con) AS ?totalCon)
  (SUM(?dex) AS ?totalDex)
  (SUM(?hasACValue) AS ?totalAC)
  (SUM(?hasCRValue) AS ?totalCR)
  (SUM(?hasFlatFootedValue) AS ?totalFlatFooted)
  (SUM(?hasFortValue) AS ?totalFort)
WHERE {
  ?beast rdf:type :Beast ;
           :hasLanguages ?lang1 ;
           :hasLanguages ?lang2 .
  ?lang1 :hasName "CommonL" .
  ?lang2 :hasName "ElvenL" .
  ?beast :atk ?atk ;
           :cha ?cha ;
           :cmb ?cmb ;
           :cmd ?cmd ;
           :con ?con ;
           :dex ?dex ;
           :hasACValue ?hasACValue ;
           :hasCRValue ?hasCRValue ;
           :hasFlatFootedValue ?hasFlatFootedValue ;
           :hasFortValue ?hasFortValue .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beast (AVG(?stat) AS ?averageStat)
WHERE {
  VALUES (?beast) { (:Baalzebul :Dagon) }
  ?beast a :Beast ;
           [ ?property ?stat ] .
  FILTER(isNumeric(?stat))
}
GROUP BY ?beast

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beastName ?conValue
WHERE {
  ?language a :Language ;
            :hasName "GhoulL" .
  ?beast a :Beast ;
         :spokenBy ?language ;
         :hasName ?beastName ;
         :con ?conValue .
}
ORDER BY DESC(?conValue)
LIMIT 1

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?beastDark) AS ?darkCount) (COUNT(?beastCyclops) AS ?cyclopsCount) ((COUNT(?beastDark) > COUNT(?beastCyclops)) AS ?isGreater)
WHERE {
  {
    SELECT DISTINCT ?beastDark
    WHERE {
      ?beast a :Beast ;
             :hasLanguages ?language .
      ?language :hasName "DarkL" .
    }
  }
  UNION
  {
    SELECT DISTINCT ?beastCyclops
    WHERE {
      ?beast a :Beast ;
             :hasLanguages ?language .
      ?language :hasName "CyclopsL" .
    }
  }
}
GROUP BY ?darkCount ?cyclopsCount

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?beastPolyglot) AS ?polyglotCount) (COUNT(?beastSkald) AS ?skaldCount) 
       ((COUNT(?beastPolyglot) > COUNT(?beastSkald)) AS ?isGreater)
WHERE {
  OPTIONAL {
    ?beastPolyglot a :Beast ;
                   :hasLanguages :PolyglotL .
  }
  OPTIONAL {
    ?beastSkald a :Beast ;
                :hasLanguages :SkaldL .
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?commonLanguageLabel ?commonAlignmentLabel
WHERE {
  :Lamia a :Beast ;
           :hasLanguages ?lamiaLanguage ;
           :hasAlignment ?lamiaAlignment .

  :Lilith a :Beast ;
            :hasLanguages ?lilithLanguage ;
            :hasAlignment ?lilithAlignment .

  FILTER(?lamiaLanguage = ?lilithLanguage)
  FILTER(?lamiaAlignment = ?lilithAlignment)

  ?lamiaLanguage :hasName ?commonLanguageLabel .
  ?lamiaAlignment :hasName ?commonAlignmentLabel .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?dex) AS ?averageDexterity)
WHERE {
  VALUES ?beast { :Phoenix :Sleipnir }
  ?beast a :Beast ;
           :hasName ?name ;
           :dex ?dex .
  FILTER(CONTAINS(LCASE(STR(?name)), "phoenix") || CONTAINS(LCASE(STR(?name)), "sleipnir"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
