PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?constitution) AS ?maxConstitution)
WHERE {
  VALUES ?beast { :Leviathan :AstralLeviathan :StygianLeviathan }
  ?beast a :Beast ;
           :hasName ?name ;
           :con ?constitution .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ?beastName WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?beastName ;
           :cha ?charisma .
  FILTER(?charisma > 20 && (LCASE(?beastName) = "kitsune" || LCASE(?beastName) = "rusalka"))
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beastName WHERE {
  ?beast rdf:type :Beast ;
           :hasName ?beastName ;
           :str ?strValue .
  FILTER(?beast IN (:Amon :Cetus))
  FILTER(?strValue >= 15 && ?strValue <= 25)
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
SELECT ?cityLabel
WHERE {
  ?supplier rdf:type pv:Supplier ;
            pv:country ?country ;
            pv:name ?supplierName .
  ?country rdf:type dbo:Country ;
           rdfs:label ?countryLabel .
  FILTER(CONTAINS(LCASE(?countryLabel), "united states"))
  ?hardware rdf:type pv:Hardware ;
            pv:hasCategory ?category ;
            pv:hasSupplier ?supplier .
  ?category rdfs:label "LCD" .
}

PREFIX creativecommons: <http://creativecommons.org/ns#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX ecc: <https://ns.eccenca.com/>
PREFIX eccdi: <https://vocab.eccenca.com/di/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ns2: <http://purl.org/dc/terms/>
PREFIX ns3: <https://text2sparql.aksw.org/2025/corporate/queries/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX shui: <https://vocab.eccenca.com/shui/>
PREFIX vann: <http://purl.org/vocab/vann/>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX wgs1: <http://www.w3.org/2003/01/geo/wgs84_pos#>

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?managerLabel ?percentage
WHERE {
  ?manager rdf:type pv:Manager ;
           rdfs:label ?managerLabel ;
           pv:memberOf ?department .

  {
    SELECT ?manager (COUNT(?employee) AS ?totalTeamSize)
    WHERE {
      ?manager pv:hasDirectReport ?employee .
    }
    GROUP BY ?manager
  }

  {
    SELECT ?manager (COUNT(?employee) AS ?sameDeptCount)
    WHERE {
      ?manager pv:hasDirectReport ?employee ;
               pv:memberOf ?department .

      ?employee pv:memberOf ?employeeDepartment .

      FILTER(?department = ?employeeDepartment)
    }
    GROUP BY ?manager
  }

  BIND(100 * xsd:float(?sameDeptCount) / xsd:float(?totalTeamSize) AS ?percentage)
}
GROUP BY ?managerLabel ?percentage

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?hardwareID ?hardwareName ?width
WHERE {
  ?hardware rdf:type pv:Hardware ;
            pv:id ?hardwareID ;
            pv:name ?hardwareName ;
            pv:width_mm ?width .
  FILTER(?width > 0)

  {
    SELECT (PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY ?otherWidth) AS ?percentileWidth)
    WHERE {
      ?otherHardware rdf:type pv:Hardware ;
                     pv:width_mm ?otherWidth .
      FILTER(?otherWidth > 0)
    }
  }

  FILTER(?width >= ?percentileWidth)
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?state
WHERE {
  {
    SELECT DISTINCT ?state
    WHERE {
      ?owner a :owners ;
               :state ?state .
    }
  } AS ?statesWithOwners
  INTERSECT
  {
    SELECT DISTINCT ?state
    WHERE {
      ?professional a :professionals ;
                    :state ?state .
    }
  } AS ?statesWithProfessionals
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?state AS ?stateLabel
WHERE {
  {
    ?owner a :owners ;
             :state ?state .
  }
  UNION
  {
    ?professional a :professionals ;
                    :state ?state .
  }
}
GROUP BY ?state
HAVING (COUNT(DISTINCT ?owner) > 0 && COUNT(DISTINCT ?professional) > 0)
ORDER BY ?state

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?professional_id ?last_name ?cell_number
WHERE {
  {
    ?professional a :professionals ;
                  :state "Indiana" ;
                  :professional_id ?professional_id ;
                  :last_name ?last_name ;
                  :cell_number ?cell_number .
  }
  UNION
  {
    SELECT ?professional_id ?last_name ?cell_number
    WHERE {
      ?professional a :professionals ;
                    :professional_id ?professional_id ;
                    :last_name ?last_name ;
                    :cell_number ?cell_number .
      ?treatment a :treatments ;
                 :ref-professional ?professional .
    }
    GROUP BY ?professional_id ?last_name ?cell_number
    HAVING (COUNT(?treatment) > 2)
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professional_id ?last_name ?cell_number
WHERE {
  ?professional a :professionals ;
                :professional_id ?professional_id ;
                :last_name ?last_name ;
                :cell_number ?cell_number .
  OPTIONAL {
    ?professional :state "Indiana" .
  }
  {
    SELECT ?professional (COUNT(?treatment) AS ?treatment_count)
    WHERE {
      ?treatment a :treatments ;
                 :ref-professional ?professional .
    }
    GROUP BY ?professional
    HAVING (?treatment_count > 2)
  }
}

