PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?dogName ?treatmentDate
WHERE {
  ?dog a :dogs ;
         :name ?dogName ;
         :ref-breed_code ?breed .
  ?breed a :breeds ;
           :breed_code ?breedCode .
  ?treatment a :treatments ;
             :ref-dog ?dog ;
             :date_of_treatment ?treatmentDate .
  {
    SELECT ?breed
    WHERE {
      ?dog a :dogs ;
           :ref-breed_code ?breed .
    }
    GROUP BY ?breed
    ORDER BY ASC(COUNT(?dog))
    LIMIT 1
  }
}
FILTER EXISTS {
  ?dog a :dogs ;
       :ref-breed_code ?breed .
  FILTER(?breed = (
    SELECT ?breed
    WHERE {
      ?dog a :dogs ;
           :ref-breed_code ?breed .
    }
    GROUP BY ?breed
    ORDER BY ASC(COUNT(?dog))
    LIMIT 1
  ))
}

