WHERE {
  {
    SELECT (AVG(?age) AS ?avgAge)
    WHERE {
      ?dog a :dogs ;
             :age ?age .
    }
  }
  ?dog a :dogs ;
         :age ?age .
  FILTER (?age < ?avgAge)
}

