PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?dog) AS ?count)
WHERE {
  {
    SELECT (AVG(?age) AS ?averageAge)
    WHERE {
      ?dog a :dogs ;
             :age ?age .
      BIND(xsd:float(?age) AS ?fAge)
    }
  }
  ?dog a :dogs ;
         :age ?age .
  FILTER(xsd:integer(?age) < ?averageAge)
}

