PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?courseName ?courseId (COUNT(?section) AS ?sectionCount)
WHERE {
    ?course a :courses ;
              :course_name ?courseName ;
              :course_id ?courseId .
    OPTIONAL { 
        ?section a :sections ;
                 :ref-course ?course .
    }
}
GROUP BY ?courseName ?courseId
HAVING (?sectionCount < 2)

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?firstName ?middleName ?lastName ?studentId
WHERE {
  ?student a :students ;
             :first_name ?firstName ;
             :middle_name ?middleName ;
             :last_name ?lastName ;
             :student_id ?studentId .
  {
    SELECT ?student
    WHERE {
      ?enrolment a :student_enrolment ;
                   :degree_program_id ?programId ;
                   :semester_id ?semesterId ;
                   :ref-student ?student .
    }
    GROUP BY ?student
    HAVING(COUNT(DISTINCT ?programId) >= 2)
  }
}

