                    :ref-degree_program ?degreeProgram ;
                    :ref-student ?student .
  ?degreeProgram :degree_summary_name ?degreeSummaryName .
  FILTER(CONTAINS(LCASE(?degreeSummaryName), "bachelor"))
  ?student a :students ;
           :first_name ?firstName ;
           :middle_name ?middleName ;
           :last_name ?lastName .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
