PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?programId ?summaryDescription (COUNT(?studentEnrolment) AS ?enrollmentCount)
WHERE {
  ?studentEnrolment a :student_enrolment ;
                    :ref-degree_program ?degreeProgram ;
                    :student_id ?studentId .
  ?degreeProgram a :degree_programs ;
                 :degree_program_id ?programId ;
                 :degree_summary_description ?summaryDescription .
}
GROUP BY ?programId ?summaryDescription
ORDER BY DESC(?enrollmentCount)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
