PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?first_name ?middle_name ?last_name ?student_id (COUNT(?enrolment) AS ?number_of_enrollments)
WHERE {
  ?student rdf:type :students ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name ;
           :student_id ?student_id .
  ?enrolment rdf:type :student_enrolment ;
             :ref-student ?student .
}
GROUP BY ?student ?first_name ?middle_name ?last_name ?student_id
ORDER BY DESC(?number_of_enrollments)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
