WHERE {
  ?student rdf:type :students ;
           :ref-current_address/:address_id ?address_id .
  ?address rdf:type :addresses ;
           :address_id ?address_id ;
           :line_1 ?line_1 ;
           :line_2 ?line_2 .
}
GROUP BY ?address_id ?line_1 ?line_2
ORDER BY DESC(?student_count)
LIMIT 1

