SELECT ?semester_id
WHERE {
  ?enrolment_a :ref-degree_program ?degreeProgramMasters ;
               :semester_id ?semester_id ;
               rdf:type :student_enrolment .
  ?degreeProgramMasters :degree_summary_name "Master" .

  ?enrolment_b :ref-degree_program ?degreeProgramBachelors ;
               :semester_id ?semester_id ;
               rdf:type :student_enrolment .
  ?degreeProgramBachelors :degree_summary_name "Bachelor" .
}
GROUP BY ?semester_id
HAVING (COUNT(DISTINCT ?degreeProgramMasters) > 0 && COUNT(DISTINCT ?degreeProgramBachelors) > 0)

