WHERE {
  VALUES ?countryURI { <http://valuenet/ontop/country/code-ABW> }
  ?countryURI rdf:type :country ;
              :name "Aruba" ;
              :code ?countryCode .
  ?languageInfo rdf:type :countrylanguage ;
