WHERE {
  ?countrylanguage1 a :countrylanguage ;
                    :ref-countrycode ?country ;
                    :language "English" ;
                    :isofficial "T" .
  ?countrylanguage2 a :countrylanguage ;
                    :ref-countrycode ?country ;
                    :language "French" ;
                    :isofficial "T" .
  ?country a :country ;
           :name ?countryName .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  ?countryLanguageEnglish a :countrylanguage ;
                        :countrycode ?countryCode ;
                        :isofficial "T"^^xsd:string ;
                        :language "English" ;
                        :ref-countrycode ?country .

  ?countryLanguageFrench a :countrylanguage ;
                       :countrycode ?countryCode ;
                       :isofficial "T"^^xsd:string ;
                       :language "French" ;
                       :ref-countrycode ?country .

  ?country a :country ;
           :name ?countryName .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?countryName
WHERE {
  ?countrylanguage a :countrylanguage ;
                   :isofficial "T"^^xsd:string ;
                   :language ?lang ;
                   :ref-countrycode ?country .
  ?country a :country ;
           :name ?countryName .
  FILTER(?lang = "English" || ?lang = "Dutch")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  ?countrylanguage a :countrylanguage ;
                   :isofficial "T"^^xsd:string ;
                   :language ?lang ;
                   :ref-countrycode ?country .
  ?country a :country ;
           :name ?countryName .
  FILTER(?lang = "English" || ?lang = "Dutch")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?language (SUM(?percentage) AS ?totalPercentage)
WHERE {
  ?country rdf:type :country ;
           :continent "Asia" ;
           :code ?countryCode .
  ?countryLanguage rdf:type :countrylanguage ;
                   :ref-countrycode ?country ;
                   :language ?language ;
                   :percentage ?percentage .
}
GROUP BY ?language
ORDER BY DESC(?totalPercentage)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?languageLabel
WHERE {
  ?country rdf:type :country ;
           :governmentform "republic" ;
           :code ?countryCode .

  ?lang rdf:type :countrylanguage ;
        :ref-countrycode ?countryCode ;
        :language ?languageLabel .

  FILTER NOT EXISTS {
    ?otherCountry rdf:type :country ;
                  :governmentform "republic" ;
                  :code ?otherCountryCode .

    ?otherLang rdf:type :countrylanguage ;
               :ref-countrycode ?otherCountryCode ;
               :language ?languageLabel .

    FILTER(?otherCountry != ?country)
  }
}
GROUP BY ?languageLabel
HAVING (COUNT(DISTINCT ?country) = 1)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?cityName ?population
WHERE {
  ?city a :city ;
          :name ?cityName ;
          :countrycode ?countryCode .
  ?countryLanguage a :countrylanguage ;
                   :ref-countrycode ?country ;
                   :language "English" ;
                   :countrycode ?countryCode .
  ?country a :country .
  ?city :population ?population .
}
ORDER BY DESC(?population)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityName (MAX(?population) AS ?maxPopulation)
WHERE {
  ?countrylanguage a :countrylanguage ;
                   :language "English" ;
                   :ref-countrycode ?country .
  ?city a :city ;
        :ref-countrycode ?country ;
        :name ?cityName ;
        :population ?population .
}
GROUP BY ?cityName
ORDER BY DESC(?maxPopulation)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
