PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?lifeExpectancy) AS ?meanLifeExpectancy)
WHERE {
  ?country rdf:type :country ;
           :name ?countryName ;
           :lifeexpectancy ?lifeExpectancy .
  FILTER NOT EXISTS {
    ?language :ref-countrycode ?country ;
               :language "English" ;
               :isofficial "T" .
  }
}

