PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(DISTINCT ?language) AS ?totalLanguages)
WHERE {
  ?country rdf:type :country ;
           :indepyear ?indepYear .
  FILTER(?indepYear < 1930)
  ?countryLanguage rdf:type :countrylanguage ;
                   :ref-countrycode ?country ;
                   :isofficial "T" ;
                   :language ?language .
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName
WHERE {
  {
    SELECT (MAX(?surfaceArea) AS ?maxEuropeSurfaceArea)
    WHERE {
      ?europeCountry rdf:type :country ;
                     :continent "Europe" ;
                     :surfacearea ?surfaceArea .
    }
  }
  ?country rdf:type :country ;
           :name ?countryName ;
           :surfacearea ?countrySurfaceArea .
  FILTER (?countrySurfaceArea > ?maxEuropeSurfaceArea)
}

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  ?country rdf:type :country ;
           :name ?countryName ;
           :surfacearea ?area .
  FILTER(?area > (
    SELECT (MAX(?europeArea) AS ?maxEuropeArea)
    WHERE {
      ?europeCountry rdf:type :country ;
                     :region "Europe" ;
                     :surfacearea ?europeArea .
    }
  ))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  ?africanCountry rdf:type :country ;
                  :continent "Africa" ;
                  :population ?africanPopulation .
  ?asianCountry rdf:type :country ;
                :continent "Asia" ;
                :population ?asianPopulation .
  FILTER(?africanPopulation < ?asianPopulation)
  ?africanCountry :name ?countryName .
}
GROUP BY ?countryName

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?africanCountryName (MIN(?asianPopulation) AS ?minAsianPopulation)
WHERE {
  ?africanCountry rdf:type :country ;
                  :continent "Africa" ;
                  :population ?africanPopulation .
  ?asianCountry rdf:type :country ;
                :continent "Asia" ;
                :population ?asianPopulation .
}
GROUP BY ?africanCountryName
HAVING (?africanPopulation < ?minAsianPopulation)
ORDER BY ?africanCountryName

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  {
    SELECT (MAX(?africanPopulation) AS ?maxAfricanPopulation)
    WHERE {
      ?africanCountry rdf:type :country ;
                      :continent "Africa" ;
                      :population ?africanPopulation .
    }
  }
  ?country rdf:type :country ;
           :continent "Asia" ;
           :population ?asianPopulation .
  FILTER(?asianPopulation > ?maxAfricanPopulation)
  ?country :name ?countryName .
}
GROUP BY ?countryName

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryLabel
WHERE {
  {
    SELECT (MAX(?africanPopulation) AS ?maxAfricanPopulation)
    WHERE {
      ?africanCountry rdf:type :country ;
                      :continent "Africa" ;
                      :population ?africanPopulation .
    }
  }
  ?country rdf:type :country ;
           :continent "Asia" ;
           :population ?asianPopulation .
  FILTER(?asianPopulation > ?maxAfricanPopulation)
  OPTIONAL { ?country :name ?countryName }
  BIND(COALESCE(?countryName, STR(?country)) AS ?countryLabel)
}
GROUP BY ?countryLabel

