PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?code
WHERE {
  ?country a :country ;
             :code ?code ;
             :governmentform ?governmentForm .
  FILTER(?governmentForm != "Republic")
  OPTIONAL {
    ?language :ref-countrycode ?country ;
               :language "English" .
  }
  FILTER(!BOUND(?language))
