PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?cityName
WHERE {
  ?country rdf:type :country ;
           :continent "Europe" ;
           :code ?countryCode .
  FILTER NOT EXISTS {
    ?language rdf:type :countrylanguage ;
              :ref-countrycode ?country ;
              :isofficial "T" ;
              :language "English" .
  }
  ?city rdf:type :city ;
        :ref-countrycode ?country ;
        :name ?cityName .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?cityName
WHERE {
  ?city a :city ;
          :name ?cityName ;
          :ref-countrycode ?country .
  ?country a :country ;
             :continent "Europe"^^xsd:string .
  FILTER NOT EXISTS {
    ?lang a :countrylanguage ;
            :ref-countrycode ?country ;
            :language "English"^^xsd:string ;
            :isofficial "true"^^xsd:string .
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
