PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?name ?population ?headofstate
WHERE {
  ?country rdf:type :country ;
           :name ?name ;
           :population ?population ;
           :headofstate ?headofstate ;
           :surfacearea ?surfacearea .
}
ORDER BY DESC(?surfacearea)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?district (COUNT(?city) AS ?numberOfCities)
WHERE {
  {
    SELECT (AVG(?population) AS ?avgPopulation)
    WHERE {
      ?city a :city ;
              :population ?population .
    }
  }
  ?city a :city ;
          :district ?district ;
          :population ?population .
  FILTER(?population > ?avgPopulation)
}
GROUP BY ?district

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?district (COUNT(?city) AS ?cityCount)
WHERE {
  {
    SELECT (AVG(?population) AS ?avgPopulation)
    WHERE {
      ?city a :city ;
              :population ?population .
    }
  }
  ?city a :city ;
          :district ?district ;
          :population ?population .
  FILTER(?population > ?avgPopulation)
}
GROUP BY ?district

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?governmentform (SUM(?population) AS ?totalPopulation)
WHERE {
    ?country rdf:type :country ;
             :governmentform ?governmentform ;
             :lifeexpectancy ?lifeexpectancy ;
             :population ?population .
    FILTER(?lifeexpectancy > 72)
}
GROUP BY ?governmentform

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?continent (AVG(?lifeexpectancy) AS ?avgLifeExpectancy) (SUM(?population) AS ?totalPopulation)
WHERE {
  ?country rdf:type :country ;
           :continent ?continent ;
           :lifeexpectancy ?lifeexpectancy ;
           :population ?population .
}
GROUP BY ?continent
HAVING (AVG(?lifeexpectancy) < 72.0)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?continent (SUM(?population) AS ?totalPopulation) (AVG(?lifeexpectancy) AS ?averageLifeExpectancy)
WHERE {
  ?country rdf:type :country ;
           :continent ?continent ;
           :population ?population ;
           :lifeexpectancy ?lifeexpectancy .
}
GROUP BY ?continent
HAVING (?averageLifeExpectancy < 72.0)

