PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName
WHERE {
  ?country rdf:type :country ;
           :name ?countryName ;
           :continent "Europe" ;
           :population 78000 .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?population) AS ?totalPopulation) (AVG(?surfacearea) AS ?averageArea)
WHERE {
  ?country rdf:type :country ;
           :continent "North America" ;
           :surfacearea ?surfacearea ;
           :population ?population .
  FILTER (?surfacearea > 3000.0)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
SELECT (SUM(?population) AS ?TotalPopulation) (AVG(?surfacearea) AS ?AverageSurfaceArea)
WHERE {
  ?country rdf:type :country ;
           :continent "North America" ;
           :surfacearea ?surfacearea ;
           :population ?population .
  FILTER(?surfacearea > 3000)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryName ?language ?maxPercentage
WHERE {
  ?country a :country ;
             :name ?countryName .
  ?lang a :countrylanguage ;
          :ref-countrycode ?country ;
          :language ?language ;
          :percentage ?percentage .
  FILTER(?isofficial = "T")
  {
    SELECT ?country (MAX(?percentage) AS ?maxPercentage)
    WHERE {
      ?lang a :countrylanguage ;
              :ref-countrycode ?country ;
              :percentage ?percentage .
      FILTER(?isofficial = "T")
    }
    GROUP BY ?country
  }
  FILTER(?percentage = ?maxPercentage)
}
GROUP BY ?countryName ?language ?maxPercentage

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryCode ?language (MAX(?percentage) AS ?maxPercentage)
WHERE {
  ?languageInstance a :countrylanguage ;
                  :countrycode ?countryCode ;
                  :language ?language ;
                  :percentage ?percentage .
}
GROUP BY ?countryCode ?language

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(?country) AS ?totalCountries)
WHERE {
  {
    SELECT ?country (MAX(?percentage) AS ?maxPercentage)
    WHERE {
      ?language :language "Spanish" ;
                :percentage ?percentage ;
                :ref-countrycode ?country .
    }
    GROUP BY ?country
  }
  ?language :language "Spanish" ;
            :percentage ?percentage ;
            :ref-countrycode ?country .
  FILTER(?percentage = ?maxPercentage)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?countryCode
WHERE {
  ?languageInstance a :countrylanguage ;
                  :language "Spanish" ;
                  :percentage ?percentage ;
                  :ref-countrycode ?country .
  ?country :code ?countryCode .
  FILTER(?percentage > 50)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?spell WHERE {
  ?spellA :canSpell ?spell .
  ?spellC :canSpell ?spell .
  FILTER EXISTS {
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#aasimar> :canSpell ?spell .
  }
  FILTER EXISTS {
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#caypup> :canSpell ?spell .
  }
}
GROUP BY ?spell

SELECT (COUNT(DISTINCT ?beastA) > COUNT(DISTINCT ?beastB) AS ?result)
WHERE {
  { 
    SELECT DISTINCT ?beastA 
    WHERE {
      ?beastA rdf:type :Beast .
      ?beastA :hasLanguages ?lang1 .
      ?beastA :hasLanguages ?lang2 .
      ?lang1 :hasName "AbyssalL" .
      ?lang2 :hasName "AkloL" .
    }
  }

  {
    SELECT DISTINCT ?beastB 
    WHERE {
      ?beastB rdf:type :Beast .
      ?beastB :hasLanguages ?lang3 .
      ?beastB :hasLanguages ?lang4 .
      ?lang3 :hasName "InfernalL" .
      ?lang4 :hasName "TerranL" .
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ((?both_languages_count / ?total_dragons_count) * 100 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?dragon) AS ?both_languages_count)
    WHERE {
      ?dragon rdf:type :Beast .
      ?dragon :beastCategoryName "dragon" .
      ?dragon :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#DraconicL> .
      ?dragon :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#CommonL> .
    }
  }

  {
    SELECT (COUNT(DISTINCT ?dragon) AS ?total_dragons_count)
    WHERE {
      ?dragon rdf:type :Beast .
      ?dragon :beastCategoryName "dragon" .
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?languageCount) AS ?averageLanguages)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName "dragon" .
  ?beast :hasLanguages ?language .
  {
    SELECT ?beast (COUNT(?language) AS ?languageCount)
    WHERE {
      ?beast :hasLanguages ?language
    }
    GROUP BY ?beast
  }
}

SELECT 
  (COUNT(DISTINCT ?skeletonTrueNeutral) / COUNT(DISTINCT ?skeletonTotal) * 100 AS ?skeletonPercentage),
  (COUNT(DISTINCT ?zombieTrueNeutral) / COUNT(DISTINCT ?zombieTotal) * 100 AS ?zombiePercentage),
  (IF(?skeletonPercentage > ?zombiePercentage, "Yes", "No") AS ?result)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?skeleton) AS ?skeletonTotal)
    WHERE { 
      ?skeleton rdf:type :Beast ;
                :beastCategoryName "skeleton" .
    }
  }

  {
    SELECT (COUNT(DISTINCT ?zombie) AS ?zombieTotal)
    WHERE { 
      ?zombie rdf:type :Beast ;
              :beastCategoryName "zombie" .
    }
  }

  {
    SELECT (COUNT(DISTINCT ?skeletonTrueNeutral) AS ?skeletonTrueNeutralCount)
    WHERE { 
      ?skeletonTrueNeutral rdf:type :Beast ;
                           :beastCategoryName "skeleton" ;
                           :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#TrueNeutral> .
    }
  }

  {
    SELECT (COUNT(DISTINCT ?zombieTrueNeutral) AS ?zombieTrueNeutralCount)
    WHERE { 
      ?zombieTrueNeutral rdf:type :Beast ;
                         :beastCategoryName "zombie" ;
                         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#TrueNeutral> .
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ((?count_chaos / ?count_total) * 100 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?beast) AS ?count_chaos)
    WHERE {
      ?beast rdf:type :Beast .
      ?beast :hasAlignment ?alignment .
      VALUES ?alignment { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticEvil> 
                          <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticGood>
                          <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticNeutral> }
    }
  }

  {
    SELECT (COUNT(DISTINCT ?beast) AS ?count_total)
    WHERE {
      ?beast rdf:type :Beast .
    }
  }
}

SELECT 
  (COUNT(?angel) AS ?totalAngels)
  (COUNT(?speaksAquan) AS ?speaksAquanCount)
  ((?speaksAquanCount / ?totalAngels * 100) AS ?percentage)
WHERE {
  ?angel rdf:type :Beast .
  ?angel :beastCategoryName "angel" .

  OPTIONAL {
    ?angel :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#AquanL> .
    BIND(1 AS ?speaksAquan)
  }
}
GROUP BY ?totalAngels

SELECT (IF(?sangudaemonSpeed > ?eblisSpeed, "Yes", "No") AS ?result)
WHERE {
  ?sangudaemon rdf:type :Beast ;
               rdfs:label "Sangudaemon" ;
               :hasSpeedValue ?sangudaemonSpeed .

  ?eblis rdf:type :Beast ;
         rdfs:label "Eblis" ;
         :hasSpeedValue ?eblisSpeed .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?speed) AS ?meanSpeed)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName "spider" ;
         :hasSpeedValue ?speed .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?creatureName ?speedValue 
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticEvil> ;
         :hasSpeedValue ?speedValue ;
         :hasName ?creatureName .
}
ORDER BY DESC(?speedValue)
LIMIT 5

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?hpValue) AS ?maxHP)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticGood> ;
         :hasHPValue ?hpValue .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?abaiaLabel ?vampireLabel 
WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Abaia> 
    a :Beast ;
    :hasName ?abaiaLabel .

  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Vampire> 
    a :Beast ;
    :hasName ?vampireLabel .

  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Abaia> 
    :hasCRValue ?abaia_cr ;
    :hasHPValue ?abaia_hp ;
    :hasACValue ?abaia_ac .

  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Vampire> 
    :hasCRValue ?vamp_cr ;
    :hasHPValue ?vamp_hp ;
    :hasACValue ?vamp_ac .

  FILTER(
    (?abaia_cr > ?vamp_cr) ||
    (?abaia_hp > ?vamp_hp) ||
    (?abaia_ac > ?vamp_ac)
  )
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?dhampirAverage ?gorgonAverage WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Dhampir> 
    :atk ?d_atk ;
    :cha ?d_cha ;
    :cmb ?d_cmb ;
    :cmd ?d_cmd ;
    :con ?d_con ;
    :dex ?d_dex ;
    :hasACValue ?d_ac ;
    :hasCRValue ?d_cr ;
    :hasFlatFootedValue ?d_ff ;
    :hasFortValue ?d_fort ;
    :hasHPValue ?d_hp ;
    :hasInitValue ?d_init ;
    :hasLevel ?d_level ;
    :hasRefValue ?d_ref ;
    :hasSpeedValue ?d_speed ;
    :hasTouchValue ?d_touch ;
    :hasWillValue ?d_will ;
    :int ?d_int ;
    :str ?d_str ;
    :wis ?d_wis .

  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Gorgon> 
    :atk ?g_atk ;
    :cha ?g_cha ;
    :cmb ?g_cmb ;
    :cmd ?g_cmd ;
    :con ?g_con ;
    :dex ?g_dex ;
    :hasACValue ?g_ac ;
    :hasCRValue ?g_cr ;
    :hasFlatFootedValue ?g_ff ;
    :hasFortValue ?g_fort ;
    :hasHPValue ?g_hp ;
    :hasInitValue ?g_init ;
    :hasLevel ?g_level ;
    :hasRefValue ?g_ref ;
    :hasSpeedValue ?g_speed ;
    :hasTouchValue ?g_touch ;
    :hasWillValue ?g_will ;
    :int ?g_int ;
    :str ?g_str ;
    :wis ?g_wis .

  BIND( ( ?d_atk + ?d_cha + ?d_cmb + ?d_cmd + ?d_con + ?d_dex + ?d_ac + ?d_cr + ?d_ff + ?d_fort + ?d_hp + ?d_init + ?d_level + ?d_ref + ?d_speed + ?d_touch + ?d_will + ?d_int + ?d_str + ?d_wis ) / 20 AS ?dhampirAverage )

  BIND( ( ?g_atk + ?g_cha + ?g_cmb + ?g_cmd + ?g_con + ?g_dex + ?g_ac + ?g_cr + ?g_ff + ?g_fort + ?g_hp + ?g_init + ?g_level + ?g_ref + ?g_speed + ?g_touch + ?g_will + ?g_int + ?g_str + ?g_wis ) / 20 AS ?gorgonAverage )
}

SELECT ?boggardName ?selkieName 
WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Boggard> 
    :hasACValue ?boggardAC ;
    :hasCRValue ?boggardCR ;
    :hasFlatFootedValue ?boggardFlatFooted ;
    :hasFortValue ?boggardFort ;
    :hasWillValue ?boggardWill ;
    :hasRefValue ?boggardRef ;
    :hasInitValue ?boggardInit .

  ?selkie 
    :hasACValue ?selkieAC ;
    :hasCRValue ?selkieCR ;
    :hasFlatFootedValue ?selkieFlatFooted ;
    :hasFortValue ?selkieFort ;
    :hasWillValue ?selkieWill ;
    :hasRefValue ?selkieRef ;
    :hasInitValue ?selkieInit .

  ?boggard rdfs:label ?boggardName .
  ?selkie rdfs:label ?selkieName .
  FILTER(LCASE(STR(?selkieName)) = "selkie")
}
FILTER (
  ?boggardAC >= ?selkieAC &&
  ?boggardCR >= ?selkieCR &&
  ?boggardFlatFooted >= ?selkieFlatFooted &&
  ?boggardFort >= ?selkieFort &&
  ?boggardWill >= ?selkieWill &&
  ?boggardRef >= ?selkieRef &&
  ?boggardInit >= ?selkieInit
)

SELECT ?beastName, AVG(?defValue) AS ?meanDefensive 
WHERE {
  ?beast rdf:type :Beast ;
         rdfs:label ?beastName .
  ?beast :hasACValue ?ac ;
         :hasFlatFootedValue ?flatFooted ;
         :hasFortValue ?fort .
  BIND( (xsd:float(?ac) + xsd:float(?flatFooted) + xsd:float(?fort)) / 3 AS ?defValue )
}
GROUP BY ?beastName
HAVING (?beastName = "Centaur" || ?beastName = "Medusa")

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?biclopsTotal ?mastodonTotal WHERE {
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Biclops> 
        :atk ?bAtk ;
        :cha ?bCha ;
        :cmb ?bCmb ;
        :cmd ?bCmd ;
        :con ?bCon ;
        :dex ?bDex ;
        :hasACValue ?bAC ;
        :hasCRValue ?bCR ;
        :hasFlatFootedValue ?bFlat ;
        :hasFortValue ?bFort .
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Mastodon> 
        :atk ?mAtk ;
        :cha ?mCha ;
        :cmb ?mCmb ;
        :cmd ?mCmd ;
        :con ?mCon ;
        :dex ?mDex ;
        :hasACValue ?mAC ;
        :hasCRValue ?mCR ;
        :hasFlatFootedValue ?mFlat ;
        :hasFortValue ?mFort .
    BIND( ?bAtk + ?bCha + ?bCmb + ?bCmd + ?bCon + ?bDex + ?bAC + ?bCR + ?bFlat + ?bFort AS ?biclopsTotal )
    BIND( ?mAtk + ?mCha + ?mCmb + ?mCmd + ?mCon + ?mDex + ?mAC + ?mCR + ?mFlat + ?mFort AS ?mastodonTotal )
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result
WHERE {
  :Satyr 
    :atk ?s_atk ;
    :cha ?s_cha ;
    :cmb ?s_cmb ;
    :cmd ?s_cmd ;
    :con ?s_con ;
    :dex ?s_dex ;
    :hasACValue ?s_ac ;
    :hasCRValue ?s_cr ;
    :hasFlatFootedValue ?s_flat ;
    :hasFortValue ?s_fort ;
    :hasHPValue ?s_hp ;
    :hasInitValue ?s_init ;
    :hasLevel ?s_level ;
    :hasRefValue ?s_ref ;
    :hasSpeedValue ?s_speed ;
    :hasTouchValue ?s_touch ;
    :hasWillValue ?s_will ;
    :hasXPValue ?s_xp ;
    :int ?s_int ;
    :str ?s_str ;
    :wis ?s_wis .

  :Cacodaemon 
    :atk ?c_atk ;
    :cha ?c_cha ;
    :cmb ?c_cmb ;
    :cmd ?c_cmd ;
    :con ?c_con ;
    :dex ?c_dex ;
    :hasACValue ?c_ac ;
    :hasCRValue ?c_cr ;
    :hasFlatFootedValue ?c_flat ;
    :hasFortValue ?c_fort ;
    :hasHPValue ?c_hp ;
    :hasInitValue ?c_init ;
    :hasLevel ?c_level ;
    :hasRefValue ?c_ref ;
    :hasSpeedValue ?c_speed ;
    :hasTouchValue ?c_touch ;
    :hasWillValue ?c_will ;
    :hasXPValue ?c_xp ;
    :int ?c_int ;
    :str ?c_str ;
    :wis ?c_wis .

  BIND(
    IF(
      ((
        ?s_atk + 
        ?s_cha + 
        ?s_cmb + 
        ?s_cmd + 
        ?s_con + 
        ?s_dex + 
        ?s_ac + 
        ?s_cr + 
        ?s_flat + 
        ?s_fort + 
        ?s_hp + 
        ?s_init + 
        ?s_level + 
        ?s_ref + 
        ?s_speed + 
        ?s_touch + 
        ?s_will + 
        ?s_xp + 
        ?s_int + 
        ?s_str + 
        ?s_wis
      ) / 20 >
      ((
        ?c_atk + 
        ?c_cha + 
        ?c_cmb + 
        ?c_cmd + 
        ?c_con + 
        ?c_dex + 
        ?c_ac + 
        ?c_cr + 
        ?c_flat + 
        ?c_fort + 
        ?c_hp + 
        ?c_init + 
        ?c_level + 
        ?c_ref + 
        ?c_speed + 
        ?c_touch + 
        ?c_will + 
        ?c_xp + 
        ?c_int + 
        ?c_str + 
        ?c_wis
      ) / 20
      , "Satyr", "Cacodaemon") AS ?result
  )
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  (AVG(?str) AS ?averageStr)
  (AVG(?dex) AS ?averageDex)
  (AVG(?con) AS ?averageCon)
  (AVG(?int) AS ?averageInt)
  (AVG(?wis) AS ?averageWis)
  (AVG(?cha) AS ?averageCha)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName "golem" ;
         :str ?str ;
         :dex ?dex ;
         :con ?con ;
         :int ?int ;
         :wis ?wis ;
         :cha ?cha .
}

SELECT (AVG(?minStat) AS ?averageMinStat) WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName "wolf" ;
         :str ?str ;
         :dex ?dex ;
         :con ?con ;
         :int ?int ;
         :wis ?wis ;
         :cha ?cha .
  BIND(MIN(?str, ?dex, ?con, ?int, ?wis, ?cha) AS ?minStat)
}
GROUP BY ?beast

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?skeletonName (AVG(?acValue) AS ?averageAC)
WHERE {
  ?skeleton rdf:type :Beast ;
            :beastCategoryName "skeleton" ;
            :hasACValue ?acValue ;
            :hasName ?skeletonName .
}
GROUP BY ?skeletonName

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
