PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?atk) AS ?averageAtk)
WHERE {
  ?robot rdf:type :Beast ;
         :beastCategoryName "robot" ;
         :atk ?atk .
}

SELECT (MIN(?cmbValue) AS ?minCMB)
WHERE {
  ?beast rdf:type :Beast ;
         :hasLanguages ?language ;
         : cmb ?cmbValue .
  ?language :hasName "IgnanL" .
}
GROUP BY ?minCMB

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?cmd) AS ?maxCmd)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment ?alignment ;
         :cmd ?cmd .
  ?alignment rdf:type :Alignment ;
             :hasName ?alignName .
  FILTER(LCASE(STR(?alignName)) = "neutral good")
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?flatFootedValue) AS ?minimumFlatFootedValue)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment :LawfulGood ;
         :hasFlatFootedValue ?flatFootedValue .
}

SELECT (COUNT(?beast) AS ?trollCount)
WHERE {
  ?beast rdf:type :Beast .
  ?beast :hasFlatFootedValue ?flatFootedValue .
  FILTER(
    LCASE(STR(?beast)) CONTAINS "troll" ||
    EXISTS { ?beast :beastCategoryName ?category . FILTER(LCASE(STR(?category)) CONTAINS "troll") }
  )
  FILTER(?flatFootedValue >= 13 && ?flatFootedValue <= 18)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?fortValue) AS ?maxFort)
WHERE {
  ?beast rdf:type :Beast ;
         :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#GoblinL> ;
         :hasFortValue ?fortValue .
}

SELECT (MIN(xsd:integer(?hp)) AS ?minHP) 
WHERE {
  ?dragon rdf:type :Beast ;
          :beastCategoryName "dragon" ;
          :str ?str ;
          :hasHPValue ?hp .
  FILTER (?str > 10)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?creature ?name ?refValue 
WHERE {
  ?creature rdf:type :Beast ;
            :hasName ?name ;
            :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticEvil> ;
            :hasRefValue ?refValue .

  {
    SELECT (MAX(?ref) AS ?maxRef)
    WHERE {
      ?c rdf:type :Beast ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticEvil> ;
         :hasRefValue ?ref .
    }
  }

  FILTER(?refValue = ?maxRef)
}
GROUP BY ?creature ?name ?refValue
ORDER BY DESC(?refValue)

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>

SELECT ?beast {
  ?beast rdf:type :Beast ;
         :beastCategoryName "spider" ;
         :hasTouchValue 11 .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?touchValue) AS ?minimumTouchValue)
WHERE {
    ?beast rdf:type :Beast ;
           :hasLanguages ?language ;
           :hasInitValue ?initValue ;
           :hasTouchValue ?touchValue .
    ?language rdf:type :Language ;
              :hasName "DruidicL" .
    FILTER (?initValue < 2)
}

SELECT ?beastType 
WHERE {
  ?entity rdf:type :Beast ;
          :beastCategoryName "zombie" ;
          :cha ?cha .
  FILTER(?cha >= 3 && ?cha <= 7)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast ?name ?cha ?str ?int 
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment ?alignment ;
         :cha ?cha ;
         :str ?str ;
         :int ?int ;
         :hasName ?name .
  ?alignment :hasName "LawfulEvil" .
  FILTER(?cha > (?str + ?int))
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?count)
WHERE {
  ?language rdf:type :Language ;
            :hasName ?langName .
  ?beast rdf:type :Beast ;
         :spokenBy ?language ;
         :con ?con .
  FILTER(LCASE(STR(?langName)) = "proteanl" && ?con > 10)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?con) AS ?maxCon)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName "elemental" ;
         :con ?con .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?intelligence) AS ?minIntelligence)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticNeutral> ;
         :int ?intelligence .
}

SELECT (SUM(?baalzebulStats) / COUNT(?baalzebulProp) AS ?baalzebulAvg)
       (SUM(?dagonStats) / COUNT(?dagonProp) AS ?dagonAvg)
       (IF(SUM(?baalzebulStats) / COUNT(?baalzebulProp) > SUM(?dagonStats) / COUNT(?dagonProp), TRUE, FALSE) AS ?result)
WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Baalzebul> a :Beast ;
    ?baalzebulProp ?baalzebulStats .

  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Dagon> a :Beast ;
    ?dagonProp ?dagonStats .
}
GROUP BY <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Baalzebul>
         <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Dagon>

SELECT (COUNT(?polyBeast) > COUNT(?skaldBeast) AS ?isGreater)
WHERE {
  { 
    ?polyBeast rdf:type :Beast .
    ?polyBeast :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#PolyglotL> .
  }
  UNION
  {
    ?skaldBeast rdf:type :Beast .
    ?skaldBeast :hasLanguages ?lang .
    ?lang :hasName ?langName .
    FILTER(LCASE(STR(?langName)) = "skaldl")
  }
}

SELECT ?commonLanguage (SAMETERM(?alignmentLamia, ?alignmentLilith) AS ?alignmentsMatch)
WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Lamia> :hasAlignment ?alignmentLamia ;
    :hasLanguages ?langsLamia .

  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Lilith> :hasAlignment ?alignmentLilith ;
    :hasLanguages ?langsLilith .

  # Find common languages
  FILTER (REGEX(STR(?langsLamia), STR(?langsLilith)) || REGEX(STR(?langsLilith), STR(?langsLamia)))

  # Extract the common language value
  BIND(STRAFTER(STRBEFORE(STR(?langsLamia), "^^"), "#") AS ?commonLanguage)
}

SELECT ?employeeName 
WHERE {
  ?service rdf:type pv:Service ;
           pv:price ?price .
  ?price pv:amount ?priceAmount .

  VALUES ?maxPrice {
    (SELECT MAX(?pAmount) 
     WHERE {
       ?s rdf:type pv:Service ;
          pv:price ?p .
       ?p pv:amount ?pAmount .
     })
  }

  ?service pv:hasProductManager ?employee .
  ?employee pv:name ?employeeName .

  FILTER (?priceAmount = ?maxPrice)
}
GROUP BY ?priceAmount ?employeeName

