PREFIX : <http://valuenet/ontop/>
SELECT ?battleName ?date ?result WHERE {
  ?b rdf:type :battle ;
     :name ?battleName ;
     :date ?date ;
     :result ?result .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?battleId ?battleName 
WHERE {
  ?battle rdf:type :battle ;
          :id ?battleId ;
          :name ?battleName .

  ?ship rdf:type :ship ;
        :ref-lost_in_battle ?battle ;
        :ship_type "Brig" .
}
GROUP BY ?battleId ?battleName

SELECT ?shipId ?shipName 
WHERE {
  ?death :ref-caused_by_ship ?ship .
  ?ship :id ?shipId ;
        :name ?shipName .
  ?death :injured ?injuredCount .
}
GROUP BY ?ship ?shipId ?shipName 
HAVING (SUM(?injuredCount) = (
  SELECT MAX(?sumInjuries)
  WHERE {
    ?d :ref-caused_by_ship ?s .
    ?s :id ?sid ;
       :name ?sname .
    ?d :injured ?icount .
    BIND(SUM(?icount) AS ?sumInjuries)
  }
))
ORDER BY DESC(SUM(?injuredCount))
LIMIT 1

PREFIX : <http://valuenet/ontop/>
