SELECT ?model 
WHERE {
    {
        ?maker rdf:type :car_makers ;
               :fullname "General Motors" .
        ?modelList :ref-maker ?maker ;
                    :model ?model .
    }
    UNION
    {
        ?carData rdf:type :cars_data ;
                 :weight ?weight ;
                 :ref ?carName .
        ?carName :make ?make ;
                 :ref-model ?modelList .
        ?modelList :model ?model .
        FILTER(?weight > 3500)
    }
}

SELECT COUNT(?car) 
WHERE {
  ?car rdf:type :cars_data .
  ?car :cylinders ?cylinders .
  FILTER (?cylinders > 6)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?modelLabel (MAX(?horsepower) AS ?maxHorsepower)
WHERE {
  ?car rdf:type :cars_data ;
       :cylinders 4 ;
       :ref ?modelName ;
       :horsepower ?horsepower .

  ?modelName rdf:type :car_names ;
              :model ?modelLabel .
}
GROUP BY ?modelLabel
ORDER BY DESC(?maxHorsepower)

SELECT ?makeid ?make 
WHERE {
  ?carData rdf:type :cars_data .
  ?carData :cylinders ?cylinders .
  ?carData :horsepower ?horsepower .
  ?carData :ref ?carName .

  ?carName rdf:type :car_names .
  ?carName :makeid ?makeid .
  ?carName :make ?make .

  FILTER (?cylinders <= 3)

  {
    SELECT (MIN(?minHorsepower) AS ?minHorsepower)
    WHERE {
      ?carData2 rdf:type :cars_data .
      ?carData2 :horsepower ?minHorsepower .
    }
  }

  FILTER (?horsepower > ?minHorsepower)
}

SELECT ?makeid ?model 
WHERE {
  :cars_data :ref ?car_name .
  :cars_data :cylinders ?cylinders .
  :cars_data :horsepower ?hp .

  { SELECT (MIN(?min_hp) AS ?overall_min)
    WHERE { :cars_data :horsepower ?min_hp }
  } .

  ?car_name :makeid ?makeid .
  ?car_name :model ?model .

  FILTER (?cylinders < 4 && ?hp > ?overall_min)
}

