PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?model 
WHERE {
  ?carData rdf:type :cars_data ;
           :weight ?weight ;
           :ref ?carName .
  ?carName rdf:type :car_names ;
           :make ?make ;
           :model ?model .
  FILTER(?weight < 3500 && ?make != "Ford Motor Company")
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryname WHERE {
  ?c rdf:type :countries ;
     :countryname ?countryname .

  OPTIONAL {
    ?maker rdf:type :car_makers ;
           :ref-country ?c .
  }

  FILTER (!BOUND(?maker))
}

SELECT DISTINCT ?makerId ?makerName 
WHERE {
  ?maker rdf:type :car_makers .
  ?maker :id ?makerId .
  ?maker :fullname ?makerName .

  {
    SELECT ?maker (COUNT(?modelList) AS ?modelCount)
    WHERE {
      ?modelList rdf:type :model_list .
      ?modelList :ref-maker ?maker .
    }
    GROUP BY ?maker
    HAVING (?modelCount >= 2)
  }
}
GROUP BY ?maker ?makerId ?makerName
HAVING (COUNT(?maker) > 3)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryid ?countryname 
WHERE {
  { 
    ?maker a :car_makers ;
           :ref-country ?country .
    ?country a :countries ;
             :countryid ?countryid ;
             :countryname ?countryname .
  }
  UNION
  {
    ?maker a :car_makers ;
           :car_makers-maker "fiat" ;
           :ref-country ?country .
    ?country a :countries ;
             :countryid ?countryid ;
             :countryname ?countryname .
  }
}
GROUP BY ?countryid ?countryname
HAVING (COUNT(?maker) > 3)

SELECT ?songName ?releaseYear 
WHERE {
  SELECT ?singer (MIN(?age) AS ?minAge)
  WHERE {
    ?singer rdf:type :singer ;
            :age ?age .
  }
  GROUP BY ?singer
} .
?singer rdf:type :singer ;
        :name ?songName ;
        :song_release_year ?releaseYear .

SELECT ?songName ?releaseYear 
WHERE {
  ?singer rdf:type :singer ;
          :age ?age ;
          :song_name ?songName ;
          :song_release_year ?releaseYear .

  VALUES ?minAge { (MIN(?age)) }
}
GROUP BY ?singer ?songName ?releaseYear

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?country WHERE {
  ?singer rdf:type :singer ;
          :age ?age ;
          :country ?country .
  FILTER (?age > 20)
}

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?songName
WHERE {
  ?singer rdf:type :singer ;
          :age ?age ;
          :song_name ?songName .

  {
    SELECT (AVG(?avgAge) AS ?averageAge)
    WHERE {
      ?singer rdf:type :singer ;
              :age ?avgAge .
    }
    GROUP BY ?singer
  }

  BIND(STRDT(?age, xsd:integer) AS ?ageInt)

  FILTER(?ageInt > ?averageAge)
}

