PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?capacity 
WHERE {
  ?stadium rdf:type :stadium ;
           :name ?name ;
           :average ?average ;
           :capacity ?capacity .
}
ORDER BY DESC(?average)
LIMIT 1

SELECT ?name ?capacity 
WHERE {
  ?stadium :average ?average .
  ?stadium :name ?name .
  ?stadium :capacity ?capacity .
  {
    SELECT MAX(?avg) AS ?maxAverage
    WHERE { ?s :average ?avg }
  }
  FILTER (?average = ?maxAverage)
}
GROUP BY ?stadium ?name ?capacity

SELECT ?stadium_name 
WHERE {
  ?stadium rdf:type :stadium .
  ?stadium :name ?stadium_name .
}
FILTER NOT EXISTS {
  ?concert rdf:type :concert .
  ?concert :ref-stadium ?stadium .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
