PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?country 
WHERE {
  ?singer1 a :singer ;
    :age ?age1 ;
    :country ?country .
  FILTER(?age1 > 40)

  ?singer2 a :singer ;
    :age ?age2 ;
    :country ?country .
  FILTER(?age2 < 30)

  FILTER(?country = ?country)
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?stadiumName 
WHERE {
  ?stadium rdf:type :stadium ;
           :name ?stadiumName .
  MINUS {
    ?concert rdf:type :concert ;
             :ref-stadium ?stadium ;
             :year "2014" .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?concertName ?theme (COUNT(?singerInConcert) AS ?numSingers)
WHERE {
  ?concert a :concert ;
    :concert_name ?concertName ;
    :theme ?theme .

  {
    SELECT ?concert ?singerInConcert
    WHERE {
      ?singerInConcert a :singer_in_concert ;
        :ref-concert ?concert .
    }
  }
}
GROUP BY ?concert ?concertName ?theme

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
