SELECT ?singerName WHERE {
  ?concert rdf:type :concert ;
           :year "2014" ;
           :ref-stadium ?stadium .

  ?singerInConcert rdf:type :singer_in_concert ;
                   :ref-concert ?concert ;
                   :ref-singer ?singer .

  ?singer rdf:type :singer ;
          :name ?singerName .
}

PREFIX : <http://valuenet/ontop/>
