PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?document_id ?template_id ?document_description 
WHERE {
  ?document rdf:type :documents ;
            :document_name "Robbin CV" ;
            :document_id ?document_id ;
            :template_id ?template_id ;
            :document_description ?document_description .
}

SELECT ?template_id ?template_type_code 
WHERE {
  ?document :ref-template ?template .
  ?template :template_id ?template_id ;
            :template_type_code ?template_type_code .

  # Calculate the maximum document count
  {
    SELECT (MAX(COUNT(?doc)) AS ?maxCount)
    WHERE {
      ?t :ref-template ?doc .
    }
    GROUP BY ?t
  }
} 
GROUP BY ?template ?template_id ?template_type_code 
HAVING (COUNT(?document) = ?maxCount)

SELECT ?templateId ?typeCode 
WHERE {
  ?template a :templates .
  ?template :template_id ?templateId .
  ?template :template_type_code ?typeCode .

  {
    SELECT ?template (COUNT(?document) AS ?count)
    WHERE {
      ?document a :documents .
      ?document :ref-template ?template .
    }
    GROUP BY ?template
  } 
  FILTER (?count = (
    SELECT MAX(?maxCount)
    WHERE {
      ?template2 a :templates .
      ?template2 :template_id ?templateId2 .
      ?template2 :template_type_code ?typeCode2 .

      {
        SELECT ?template2 (COUNT(?document) AS ?maxCount)
        WHERE {
          ?document a :documents .
          ?document :ref-template ?template2 .
        }
        GROUP BY ?template2
      }
    }
  ))
}
GROUP BY ?templateId ?typeCode 
HAVING (?count = MAX(?count))
LIMIT 1

SELECT ?template_id 
WHERE {
  ?template rdf:type :templates ;
            :template_id ?template_id .

  OPTIONAL {
    ?document rdf:type :documents ;
              :ref-template ?template .
  }

  FILTER NOT EXISTS { BOUND(?document) }
}

