PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?document_id ?document_name (COUNT(?paragraph) AS ?paragraph_count)
WHERE {
  ?document rdf:type :documents ;
            :document_id ?document_id ;
            :document_name ?document_name .

  ?paragraph rdf:type :paragraphs ;
             :ref-document ?document .
}
GROUP BY ?document ?document_id ?document_name

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?docId 
WHERE {
  ?doc a :documents ;
       :document_id ?docId .

  {
    SELECT ?docId (COUNT(?para) AS ?count)
    WHERE {
      ?para a :paragraphs ;
            :ref-document ?doc ;
            :document_id ?docId .
    }
    GROUP BY ?docId
    HAVING (?count >= 2)
  }
}

SELECT ?document_id ?document_name 
WHERE {
  ?doc a :documents ;
       :document_id ?document_id ;
       :document_name ?document_name .

  {
    SELECT (MAX(?count) AS ?maxCount)
    WHERE {
      ?d a :documents .
      {
        SELECT ?d (COUNT(?para) AS ?count)
        WHERE {
          ?para a :paragraphs ;
                :ref-document ?d .
        }
        GROUP BY ?d
      }
    }
  }

  {
    SELECT ?doc (COUNT(?para) AS ?count)
    WHERE {
      ?para a :paragraphs ;
            :ref-document ?doc .
    }
    GROUP BY ?doc
  }

  FILTER(?count = ?maxCount)
}

SELECT DISTINCT ?docId 
WHERE {
  {
    SELECT ?docId (COUNT(?paragraph) AS ?count)
    WHERE {
      ?paragraph :document_id ?docId .
    }
    GROUP BY ?docId
  }
  BIND(MIN(?count) AS ?minCount)
  {
    SELECT ?docId (COUNT(?paragraph) AS ?count)
    WHERE {
      ?paragraph :document_id ?docId .
    }
    GROUP BY ?docId
  }
  FILTER (?count = ?minCount)
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?state WHERE {
  { 
    ?owner rdf:type :owners ;
           :state ?state .
  }
  UNION
  { 
    ?professional rdf:type :professionals ;
                   :state ?state .
  }
}
GROUP BY ?state

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professional_id ?last_name ?cell_number 
WHERE {
  { 
    ?professional rdf:type :professionals .
    ?professional :state "IN" .
    ?professional :professional_id ?professional_id .
    OPTIONAL { ?professional :last_name ?last_name }
    OPTIONAL { ?professional :cell_number ?cell_number }
  } UNION {
    ?professional rdf:type :professionals .
    ?professional :professional_id ?professional_id .
    OPTIONAL { ?professional :last_name ?last_name }
    OPTIONAL { ?professional :cell_number ?cell_number }

    {
      SELECT ?professional (COUNT(*) AS ?treatmentCount)
      WHERE {
        ?treatment rdf:type :treatments .
        ?treatment :ref-professional ?professional .
      }
      GROUP BY ?professional
    }
    FILTER(?treatmentCount > 2)
  }
}
GROUP BY ?professional_id ?last_name ?cell_number

SELECT DISTINCT ?professional_id ?last_name ?cell_number 
WHERE {
  ?professional rdf:type :professionals .
  ?professional :professional_id ?professional_id .
  ?professional :last_name ?last_name .
  ?professional :cell_number ?cell_number .

  {
    ?professional :state "Indiana" .
  }
  UNION
  {
    SELECT ?professional 
    WHERE {
      ?treatment rdf:type :treatments .
      ?treatment :ref-professional ?professional .
    }
    GROUP BY ?professional
    HAVING (COUNT(?treatment) > 2)
  }
}
GROUP BY ?professional_id ?last_name ?cell_number

SELECT DISTINCT ?firstName WHERE {
  { 
    ?professional rdf:type :professionals ;
                   :first_name ?firstName .
    NOT EXISTS {
      ?dog rdf:type :dogs ;
           :name ?firstName .
    }
  }
  UNION
  { 
    ?owner rdf:type :owners ;
           :first_name ?firstName .
    NOT EXISTS {
      ?dog rdf:type :dogs ;
           :name ?firstName .
    }
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?firstName 
WHERE {
  {
    ?professional rdf:type :professionals ;
                   :first_name ?firstName .
  }
  UNION
  {
    ?owner rdf:type :owners ;
           :first_name ?firstName .
  }
  MINUS
  {
    ?dog rdf:type :dogs ;
         :name ?firstName .
  }
}
ORDER BY LCASE(?firstName)

SELECT ?breedName 
WHERE {
  {
    SELECT ?breed (COUNT(*) AS ?count)
    WHERE {
      ?dog rdf:type :dogs .
      ?dog :ref-breed_code ?breed .
    }
    GROUP BY ?breed
  }

  ?breed rdf:type :breeds .
  ?breed :breed_name ?breedName .

  {
    SELECT (MAX(?maxCount) AS ?targetCount)
    WHERE {
      ?dog2 rdf:type :dogs .
      ?dog2 :ref-breed_code ?breed2 .
      GROUP BY ?breed2
      HAVING (COUNT(*) AS ?maxCount)
    }
  }

  FILTER (?count = ?targetCount)
}
GROUP BY ?breedName

SELECT ?treatmentTypeDescription 
WHERE {
  {
    SELECT ?treatmentType (SUM(?cost) AS ?totalCost)
    WHERE {
      ?treatment a :treatments ;
                 :cost_of_treatment ?cost ;
                 :ref-treatment_type_code ?treatmentType .
    }
    GROUP BY ?treatmentType
  }

  ?treatmentType a :treatment_types ;
                 :treatment_type_description ?treatmentTypeDescription .

  FILTER(?totalCost = (SELECT MIN(?tc) WHERE {
    ?tr a :treatments ;
       :cost_of_treatment ?c ;
       :ref-treatment_type_code ?tt .
    ?tt a :treatment_types .
    { SELECT (SUM(?c) AS ?tc) WHERE {} }
  }))
}
GROUP BY ?treatmentTypeDescription

SELECT ?description 
WHERE {
  ?tt rdf:type :treatment_types .
  ?tt :treatment_type_description ?description .

  {
    SELECT ?tt (SUM(?cost) AS ?totalCost)
    WHERE {
      ?treatment rdf:type :treatments .
      ?treatment :ref-treatment_type_code ?tt .
      ?treatment :cost_of_treatment ?cost .
    }
    GROUP BY ?tt
  } 
  WHERE { 
    ?tt rdf:type :treatment_types .
  }

  FILTER(?totalCost = (
    SELECT MIN(?sum) 
    WHERE {
      ?treatment rdf:type :treatments .
      ?treatment :ref-treatment_type_code ?tt2 .
      ?treatment :cost_of_treatment ?c .
      {
        SELECT ?tt2 (SUM(?c) AS ?sum)
        WHERE {
          ?treatment2 rdf:type :treatments .
          ?treatment2 :ref-treatment_type_code ?tt2 .
          ?treatment2 :cost_of_treatment ?c .
        }
        GROUP BY ?tt2
      }
    }
  ))
}
GROUP BY ?description

