SELECT ?owner_id ?zip_code (SUM(?cost) AS ?total_cost)
WHERE {
  ?owner rdf:type :owners .
  ?dog rdf:type :dogs ;
       :ref-owner ?owner ;
       :dog_id ?dog_id .
  ?treatment rdf:type :treatments ;
             :ref-dog ?dog ;
             :cost_of_treatment ?cost .
  ?owner :owner_id ?owner_id ;
         :zip_code ?zip_code .
}
GROUP BY ?owner_id ?zip_code
ORDER BY DESC(?total_cost)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
