PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?ownerFirstName ?dogName
WHERE {
  ?owner rdf:type :owners ;
         :first_name ?ownerFirstName .

  ?dog rdf:type :dogs ;
       :name ?dogName ;
       :ref-owner ?owner .
}

SELECT ?dogName (GROUP_CONCAT(?treatmentDate; SEPARATOR=", ") AS ?treatmentDates)
WHERE {
  ?dog rdf:type :dogs .
  ?dog :name ?dogName .

  ?dog :ref-breed_code ?breed .
  ?breed :breed_code ?rareBreedCode .

  {
    SELECT ?breedCode 
    WHERE {
      ?dog rdf:type :dogs .
      ?dog :ref-breed_code ?breed .
      ?breed :breed_code ?breedCode .
    }
    GROUP BY ?breedCode
    HAVING (COUNT(DISTINCT ?dog) = (
      SELECT MIN(?count)
      WHERE {
        SELECT ?b COUNT(DISTINCT ?d) AS ?count
        WHERE {
          ?d rdf:type :dogs .
          ?d :ref-breed_code ?br .
          ?br :breed_code ?b .
        }
        GROUP BY ?b
      }
    ))
  }

  OPTIONAL {
    ?treatment rdf:type :treatments .
    ?treatment :ref-dog ?dog .
    ?treatment :date_of_treatment ?treatmentDate .
  }
}
GROUP BY ?dogName

SELECT ?dogName ?treatmentDate 
WHERE {
  ?dog rdf:type :dogs .
  ?dog :breed_code ?breedCode .
  ?dog :name ?dogName .

  ?treatment rdf:type :treatments .
  ?treatment :ref-dog ?dog .
  ?treatment :date_of_treatment ?treatmentDate .

  {
    SELECT ?breedCode (COUNT(?dog) AS ?count)
    WHERE {
      ?dog rdf:type :dogs .
      ?dog :breed_code ?breedCode .
    }
    GROUP BY ?breedCode
  }

  {
    SELECT MIN(?minCount) AS ?rarestCount
    WHERE {
      ?breedCodeGroup (COUNT(?dogInGroup)) ?minCount .
    }
  }

  FILTER (?count = ?rarestCount)
}
GROUP BY ?dogName ?treatmentDate

