SELECT ?manager_name ?district 
WHERE {
  ?shop :number_products ?num_products .
  {
    SELECT (MAX(?num_products) AS ?max_num_products)
    WHERE { ?shop :number_products ?num_products }
    GROUP BY ?shop
  }
  FILTER (?num_products = ?max_num_products)
  ?shop :manager_name ?manager_name ;
        :district ?district .
}

