        :name ?name ;
        :location ?location ;
        :district ?district .
}
ORDER BY DESC(?numberOfProducts)

SELECT ?shopName 
WHERE {
  ?shop rdf:type :shop ;
        :number_products ?numberProducts ;
        :name ?shopName .
  {
    SELECT (AVG(?avgNumber) AS ?avgProducts)
    WHERE {
      ?shop2 rdf:type :shop ;
             :number_products ?avgNumber .
    }
  }
  FILTER (?numberProducts > ?avgProducts)
}

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?shopName
WHERE {
  ?shop rdf:type :shop ;
        :number_products ?numProducts ;
        :name ?shopName .

  {
    SELECT (AVG(?avgNum) AS ?average)
    WHERE {
      ?s rdf:type :shop ;
         :number_products ?avgNum .
    }
  }

  FILTER(?numProducts > ?average)
}

SELECT ?employeeName WHERE {
  SELECT ?employeeName WHERE {
    ?evaluation a :evaluation ;
                :bonus ?bonus .

    ?evaluation :ref-employee ?employee .

    ?employee a :employee ;
              :name ?employeeName .

    FILTER(?bonus = (SELECT MAX(?b) WHERE { ?e a :evaluation ; :bonus ?b }))
  }
}
GROUP BY ?employeeName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
