PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?shopName 
WHERE {
  ?shop rdf:type :shop ;
        :name ?shopName .
  OPTIONAL {
    ?hiring :ref-shop ?shop ;
            :ref-employee ?employee .
  }
  FILTER (!BOUND(?hiring))
}

SELECT 
  ?hiring,
  ?employee_id,
  ?is_full_time,
  ?shop_id,
  ?start_from,
  ?employee_name,
  ?shop_name,
  ?shop_district,
  ?shop_manager_name,
  ?shop_location,
  ?shop_number_products
WHERE {
  ?hiring rdf:type :hiring .

  ?hiring :employee_id ?employee_id ;
          :is_full_time ?is_full_time ;
          :shop_id ?shop_id ;
          :start_from ?start_from .

  ?hiring :ref-employee ?employee .
  ?employee :name ?employee_name .

  ?hiring :ref-shop ?shop .
  ?shop :name ?shop_name ;
        :district ?shop_district ;
        :manager_name ?shop_manager_name ;
        :location ?shop_location ;
        :number_products ?shop_number_products .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?district 
WHERE {
  ?shop :district ?district ;
        :number_products ?products .

  {
    SELECT ?district (MIN(?p) AS ?minProducts) (MAX(?p) AS ?maxProducts)
    WHERE {
      ?s :district ?district ;
         :number_products ?p .
    }
    GROUP BY ?district
  }

  FILTER(?minProducts < 3000 && ?maxProducts > 5000)
}

