PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?airportName (COUNT(?flight) AS ?flightCount)
WHERE {
  ?airport rdf:type :airports ;
           :city "Aberdeen" ;
           :airportname ?airportName .

  ?flight rdf:type :flights ;
          :ref-sourceairport ?airport .
}
GROUP BY ?airportName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?airportCode 
WHERE {
  ?airport rdf:type :airports .
  ?airport :airportcode ?airportCode .

  {
    SELECT ?airportUri (COUNT(?flight) AS ?totalFlights)
    WHERE {
      ?flight rdf:type :flights .
      ?flight :ref-sourceairport ?airportUri .
    }
    GROUP BY ?airportUri
  } UNION {
    SELECT ?airportUri (COUNT(?flight) AS ?totalFlights)
    WHERE {
      ?flight rdf:type :flights .
      ?flight :ref-destairport ?airportUri .
    }
    GROUP BY ?airportUri
  }
}
GROUP BY ?airportCode 
ORDER BY ASC(?totalFlights)
LIMIT 1

