PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?flightNo WHERE {
  ?flight rdf:type :flights ;
          :flightno ?flightNo ;
          :destairport ?destAirportCode .

  ?airport rdf:type :airports ;
           :city ?cityName ;
           :airportcode ?destAirportCode .

  FILTER(LCASE(STR(?cityName)) = "aberdeen")
}

SELECT ?flightno WHERE {
  ?flight rdf:type :flights .
  ?flight :ref-destairport ?airport .
  ?airport :airportname "Aberdeen" .
}

SELECT ?a ?name 
WHERE {
  ?a rdf:type :airports .
  ?a :airportname ?name .
  NOT EXISTS { ?f :ref-destairport ?a }
  NOT EXISTS { ?f :ref-sourceairport ?a }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?airport ?airportName 
WHERE {
  ?airport rdf:type :airports .
  ?airport :airportname ?airportName .
  FILTER NOT EXISTS {
    ?flight :ref-sourceairport ?airport .
  }
  FILTER NOT EXISTS {
    ?flight :ref-destairport ?airport .
  }
}

SELECT ?museum_id ?name 
WHERE {
  ?museum rdf:type :museum ;
          :museum_id ?museum_id ;
          :name ?name ;
          :num_of_staff ?num_of_staff .

  {
    SELECT (MAX(?max_num) AS ?max_num)
    WHERE {
      ?museum rdf:type :museum ;
              :num_of_staff ?max_num .
    }
  }
}
FILTER (?num_of_staff = ?max_num)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?openYear ?numOfStaff 
WHERE {
  ?museum rdf:type :museum ;
          :name "Plaza Museum" ;
          :open_year ?openYear ;
          :num_of_staff ?numOfStaff .
}

SELECT ?museumName 
WHERE {
  ?museum rdf:type :museum ;
          :open_year ?openYear ;
          :num_of_staff ?staffCount ;
          :name ?museumName .

  FILTER(?openYear > 2010)
}

GROUP BY ?museumName
HAVING (?staffCount > (
  SELECT MIN(?minStaff) 
  WHERE {
    ?museumMin rdf:type :museum ;
               :open_year ?openYearMin ;
               :num_of_staff ?minStaff .
    FILTER(?openYearMin > 2010)
  }
))

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?visitor ?id ?name ?age 
WHERE {
  ?visit rdf:type :visit ;
         :ref-visitor ?visitor .
  ?visitor rdf:type :visitor ;
           :id ?id ;
           :name ?name ;
           :age ?age .
}
GROUP BY ?visitor ?id ?name ?age
HAVING (COUNT(?visit) > 1)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?visitorId ?visitorName ?membershipLevel (MAX(?spent) AS ?maxSpent)
WHERE {
  ?visit a :visit ;
    :ref-visitor ?visitor ;
    :total_spent ?spent .

  ?visitor a :visitor ;
    :id ?visitorId ;
    :name ?visitorName ;
    :level_of_membership ?membershipLevel .
}
GROUP BY ?visitor ?visitorId ?visitorName ?membershipLevel
ORDER BY DESC(?maxSpent)

SELECT ?museumId ?name 
WHERE {
  ?museum rdf:type :museum ;
          :museum_id ?museumId ;
          :name ?name .

  {
    SELECT ?museum (COUNT(*) AS ?visitCount)
    WHERE {
      ?visit rdf:type :visit ;
             :ref-museum ?museum .
    }
    GROUP BY ?museum
    ORDER BY DESC(?visitCount)
    LIMIT 1
  }
}
GROUP BY ?museumId ?name

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?museumName 
WHERE {
  ?museum rdf:type :museum ;
          :name ?museumName .
  OPTIONAL {
    ?visit rdf:type :visit ;
           :ref-museum ?museum .
  }
}
GROUP BY ?museum ?museumName
HAVING (COUNT(?visit) = 0)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?visitorName 
WHERE {
  ?visit1 a :visit ;
    :ref-museum ?museum1 ;
    :ref-visitor ?visitor .

  ?museum1 a :museum ;
    :open_year ?year1 .

  ?visit2 a :visit ;
    :ref-museum ?museum2 ;
    :ref-visitor ?visitor .

  ?museum2 a :museum ;
    :open_year ?year2 .

  ?visitor a :visitor ;
    :name ?visitorName .

  FILTER(?year1 < 2009 && ?year2 > 2011)
}

SELECT (COUNT(?visitor) AS ?count)
WHERE {
  ?visitor rdf:type :visitor .
  NOT EXISTS {
    ?visit rdf:type :visit .
    ?visit :ref-visitor ?visitor .
    ?visit :ref-museum ?museum .
    ?museum :open_year ?year .
    FILTER (?year > 2010)
  }
}

