PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?id WHERE {
  ?highschooler rdf:type :highschooler ;
                :name ?name ;
                :id ?id .
  FILTER(LCASE(STR(?name)) = "kyle")
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name WHERE {
  ?kyle rdf:type :highschooler ;
        :name ?kyleName .
  FILTER(LCASE(STR(?kyleName)) = "kyle")

  ?friendship rdf:type :friend ;
               :ref-friend ?kyle ;
               :ref-student ?student .

  ?student rdf:type :highschooler ;
           :name ?name
}

SELECT (COALESCE(?kyleName, "Unknown") AS ?kyleLabel) (COUNT(DISTINCT ?friend) AS ?friendCount)
WHERE {
  ?kyle rdf:type :highschooler ;
        :name ?kyleName .
  FILTER(CONTAINS(LCASE(STR(?kyleName)), "kyle"))

  ?friend :ref-student ?kyle .
}
GROUP BY ?kyleName

SELECT ?id 
WHERE {
  ?s rdf:type :highschooler .
  ?s :id ?id .
}
MINUS {
  ?f rdf:type :friend .
  ?f :ref-student ?s .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?id 
WHERE {
  ?highschooler rdf:type :highschooler .
  ?highschooler :id ?id .

  OPTIONAL {
    ?friend :ref-friend ?highschooler .
  }

  OPTIONAL {
    ?like :ref-liked ?highschooler .
  }

  FILTER(BOUND(?friend) && BOUND(?like))
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?id 
WHERE {
  ?student rdf:type :highschooler ;
           :id ?id .

  OPTIONAL { 
    ?friend rdf:type :friend ;
            :student_id ?id .
  }

  OPTIONAL { 
    ?like rdf:type :likes ;
          :liked_id ?id .
  }

  FILTER(BOUND(?friend) && BOUND(?like))
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name 
WHERE {
  ?hs rdf:type :highschooler ;
     :id ?hsId ;
     :name ?name .

  {
    SELECT (MAX(?count) AS ?maxCount)
    WHERE {
      ?like rdf:type :likes ;
            :liked_id ?likedId .
      ?liked rdf:type :highschooler ;
             :id ?likedId .
      {
        SELECT ?likedId (COUNT(*) AS ?count)
        WHERE {
          ?like2 rdf:type :likes ;
                 :liked_id ?likedId .
        }
        GROUP BY ?likedId
      }
    }
  }

  ?like3 rdf:type :likes ;
         :liked_id ?hsId .

  {
    SELECT ?hsId (COUNT(*) AS ?count)
    WHERE {
      ?like4 rdf:type :likes ;
             :liked_id ?hsId .
    }
    GROUP BY ?hsId
  }

  FILTER(?count = ?maxCount)
}
GROUP BY ?name

SELECT ?studentName 
WHERE {
  ?likes rdf:type :likes .
  ?likes :student_id ?studentId .

  ?highSchooler rdf:type :highschooler ;
                :id ?studentId ;
                :name ?studentName .
}
GROUP BY ?studentName ?studentId 
HAVING (COUNT(?likes) = (
  SELECT MAX(?likeCount)
  WHERE {
    ?likes2 rdf:type :likes .
    ?likes2 :student_id ?studentId2 .

    ?highSchooler2 rdf:type :highschooler ;
                  :id ?studentId2 ;
                  :name ?studentName2 .
  }
  GROUP BY ?studentName2 ?studentId2
))
ORDER BY DESC(COUNT(?likes)) 
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name 
WHERE {
  ?s rdf:type :highschooler ;
     :name ?name .
  {
    SELECT ?s (COUNT(?like) AS ?count)
    WHERE {
      ?like rdf:type :likes ;
            :ref-student ?s .
    }
    GROUP BY ?s
  } 
  FILTER (?count >= 2)
}
GROUP BY ?name
ORDER BY ?name

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?studentName 
WHERE {
  ?student rdf:type :highschooler ;
           :grade ?grade ;
           :name ?studentName .

  ?friendship rdf:type :friend ;
              :ref-friend ?student ;
              :student_id ?studentId .

  FILTER(?grade > 5)
}
GROUP BY ?student ?studentName
HAVING (COUNT(DISTINCT ?friendship) >= 2)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?grade) AS ?averageGrade)
WHERE {
  ?student rdf:type :highschooler .
  ?student :id ?studentId .
  ?student :grade ?grade .

  {
    SELECT DISTINCT ?studentId
    WHERE {
      ?friend rdf:type :friend .
      ?friend :ref-friend ?student .
      ?friend :student_id ?studentId .
    }
  } UNION {
    SELECT DISTINCT ?studentId
    WHERE {
      ?like rdf:type :likes .
      ?like :ref-liked ?student .
      ?like :student_id ?studentId .
    }
  }
}

