PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name WHERE {
  ?singer rdf:type :singer ;
          :birth_year ?birthYear ;
          :name ?name .
  FILTER( ?birthYear = 1948.0 || ?birthYear = 1949.0 )
}

SELECT ?name
WHERE {
  # Subquery to find the maximum net worth
  { SELECT (MAX(?nw) AS ?maxNW)
    WHERE {
      ?s rdf:type :singer ;
         :net_worth_millions ?nw .
    }
  }

  # Main query to select singers with the maximum net worth
  ?singer rdf:type :singer ;
          :net_worth_millions ?maxNW ;
          :name ?name.
}

SELECT ?name 
WHERE {
  ?singer rdf:type :singer ;
          :net_worth_millions ?netWorth ;
          :name ?name .

  VALUES ?maxNetWorth {
    (SELECT MAX(?nw) AS ?maxNW WHERE {
      ?s rdf:type :singer ;
         :net_worth_millions ?nw .
    })
  }

  FILTER (?netWorth = ?maxNetWorth)
}
GROUP BY ?name

