PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?description WHERE {
  ?course rdf:type :courses ;
          :course_name "math" ;
          :course_description ?description .
}

SELECT ?departmentName ?departmentId 
WHERE {
  ?degree a :degree_programs .
  ?degree :ref-department ?department .

  ?department a :departments .
  ?department :department_name ?departmentName .
  ?department :department_id ?departmentId .

  {
    SELECT ?department (COUNT(?degree) AS ?count)
    WHERE {
      ?degree a :degree_programs .
      ?degree :ref-department ?department .
    }
    GROUP BY ?department
  }

  {
    SELECT MAX(?maxCount) AS ?targetCount
    WHERE {
      ?degree a :degree_programs .
      ?degree :ref-department ?department .
      ?department a :departments .

      {
        SELECT ?department (COUNT(?degree) AS ?maxCount)
        WHERE {
          ?degree a :degree_programs .
          ?degree :ref-department ?department .
        }
        GROUP BY ?department
      }
    }
  }

  FILTER (?count = ?targetCount)
}

