PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?student_id ?first_name ?middle_name ?last_name 
WHERE {
  ?enrolment rdf:type :student_enrolment ;
             :ref-student ?student ;
             :degree_program_id ?degree_program ;
             :semester_id ?semester .

  ?student rdf:type :students ;
           :student_id ?student_id ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name .
}
GROUP BY ?student_id ?first_name ?middle_name ?last_name ?semester
HAVING (COUNT(DISTINCT ?degree_program) >= 2)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?student_id ?first_name ?middle_name ?last_name
WHERE {
  ?enrolment rdf:type :student_enrolment ;
             :ref-student ?student ;
             :ref-degree_program ?degree_program ;
             :ref-semester ?semester .

  ?student rdf:type :students ;
           :student_id ?student_id ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name .

  {
    SELECT ?student ?semester (COUNT(?degree_program) AS ?count)
    WHERE {
      ?enrolment2 rdf:type :student_enrolment ;
                 :ref-student ?student ;
                 :ref-degree_program ?degree_program ;
                 :ref-semester ?semester .
    }
    GROUP BY ?student ?semester
  } 
  FILTER (?count = 2)
}
GROUP BY ?student_id ?first_name ?middle_name ?last_name

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?firstName ?middleName ?lastName WHERE {
  ?student rdf:type :students ;
           :first_name ?firstName ;
           :middle_name ?middleName ;
           :last_name ?lastName .

  ?enrolment rdf:type :student_enrolment ;
             :ref-student ?student ;
             :ref-degree_program ?degreeProgram .

  ?degreeProgram rdf:type :degree_programs ;
                  :degree_summary_name "Bachelor" .
}

SELECT ?studentId ?firstName ?middleName ?lastName ?enrollmentCount
WHERE {
  ?student rdf:type :students .
  ?student :first_name ?firstName ;
           :middle_name ?middleName ;
           :last_name ?lastName ;
           :student_id ?studentId .

  {
    SELECT ?student (COUNT(?enrollment) AS ?enrollmentCount)
    WHERE {
      ?enrollment rdf:type :student_enrolment .
      ?enrollment :ref-student ?student .
    }
    GROUP BY ?student
  }
}
GROUP BY ?student ?firstName ?middleName ?lastName ?studentId
ORDER BY DESC(?enrollmentCount)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
