SELECT ?semester_name 
WHERE {
  ?semester rdf:type :semesters ;
            :semester_name ?semester_name .
  OPTIONAL {
    ?enrolment rdf:type :student_enrolment ;
               :ref-semester ?semester .
  }
  FILTER ( !BOUND(?enrolment) )
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?semesterName 
WHERE {
  ?semester a :semesters ;
            :semester_name ?semesterName .
  FILTER NOT EXISTS {
    ?enrolment :ref-semester ?semester .
  }
}

SELECT ?courseName 
WHERE {
  ?course rdf:type :courses ;
          :course_id ?courseId ;
          :course_name ?courseName .

  {
    SELECT ?courseId (COUNT(?studentCourse) AS ?enrollmentCount)
    WHERE {
      ?studentCourse rdf:type :student_enrolment_courses ;
                     :course_id ?courseId .
    }
    GROUP BY ?courseId
    ORDER BY DESC(?enrollmentCount)
    LIMIT 1
  } 
}

SELECT ?lastName 
WHERE {
  ?student rdf:type :students .
  ?student :last_name ?lastName .

  # Check if student lives in North Carolina (either current or permanent address)
  { 
    ?student :ref-current_address ?address .
    ?address rdf:type :addresses .
    ?address :state_province_county "North Carolina" .
  } 
  UNION 
  { 
    ?student :ref-permanent_address ?address .
    ?address rdf:type :addresses .
    ?address :state_province_county "North Carolina" .
  }

  # Ensure student has no degree program enrolment
  NOT EXISTS {
    ?enrolment rdf:type :student_enrolment .
    ?enrolment :ref-student ?student .
    ?enrolment :ref-degree_program ?degreeProgram .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
