SELECT ?cellMobileNumber WHERE {
  ?student rdf:type :students ;
           :first_name ?firstName ;
           :last_name ?lastName ;
           :cell_mobile_number ?cellMobileNumber .

  FILTER(LCASE(STR(?firstName)) = "timmothy" && LCASE(STR(?lastName)) = "ward")
}

SELECT ?firstName ?middleName ?lastName 
WHERE {
  ?student rdf:type :students ;
           :date_first_registered ?registrationDate ;
           :first_name ?firstName ;
           :middle_name ?middleName ;
           :last_name ?lastName .

  {
    SELECT MIN(?d) AS ?minDate
    WHERE {
      ?s rdf:type :students ;
         :date_first_registered ?d .
    }
  }

  FILTER(?registrationDate = ?minDate)
}
GROUP BY ?firstName ?middleName ?lastName

