PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?firstName 
WHERE {
  ?student rdf:type :students ;
           :current_address_id ?currentAddressId ;
           :permanent_address_id ?permanentAddressId ;
           :first_name ?firstName .
  FILTER(?currentAddressId != ?permanentAddressId)
}

SELECT ?address_id ?line_1 ?line_2 
WHERE {
  ?address a :addresses ;
           :address_id ?address_id ;
           :line_1 ?line_1 ;
           :line_2 ?line_2 .

  {
    SELECT ?address (COUNT(?student) AS ?count)
    WHERE {
      ?student a :students ;
               :ref-current_address ?address .
    }
    GROUP BY ?address
    ORDER BY DESC(?count)
    LIMIT 1
  } 
}
GROUP BY ?address_id ?line_1 ?line_2

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?address_id ?line_1 ?line_2 
WHERE {
  ?student rdf:type :students .
  {
    ?student :ref-current_address ?address .
  } UNION {
    ?student :ref-permanent_address ?address .
  }
  ?address rdf:type :addresses ;
           :address_id ?address_id ;
           :line_1 ?line_1 ;
           :line_2 ?line_2 .
}
GROUP BY ?address ?address_id ?line_1 ?line_2 
ORDER BY DESC(COUNT(DISTINCT ?student)) 
LIMIT 1

SELECT ?transcriptDate ?transcriptId 
WHERE {
  ?transcript rdf:type :transcripts ;
              :transcript_date ?transcriptDate ;
              :transcript_id ?transcriptId .

  {
    SELECT (MIN(?count) AS ?minCount)
    WHERE {
      ?content rdf:type :transcript_contents ;
               :ref-transcript ?transcript .
      {
        SELECT ?transcript (COUNT(?content) AS ?count)
        WHERE {
          ?content rdf:type :transcript_contents ;
                   :ref-transcript ?transcript .
        }
        GROUP BY ?transcript
      }
    }
  }

  {
    SELECT ?transcript (COUNT(?content) AS ?count)
    WHERE {
      ?content rdf:type :transcript_contents ;
               :ref-transcript ?transcript .
    }
    GROUP BY ?transcript
  }

  FILTER(?count = ?minCount)
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?semesterUri ?semesterName 
WHERE {
  ?enrolment1 rdf:type :student_enrolment ;
             :ref-degree_program ?degreeProgram1 ;
             :ref-semester ?semesterUri .
  ?degreeProgram1 rdf:type :degree_programs ;
                  :degree_summary_name ?masterDegree .
  FILTER(CONTAINS(LCASE(STR(?masterDegree)), "master"))

  ?enrolment2 rdf:type :student_enrolment ;
             :ref-degree_program ?degreeProgram2 ;
             :ref-semester ?semesterUri .
  ?degreeProgram2 rdf:type :degree_programs ;
                  :degree_summary_name ?bachelorDegree .
  FILTER(CONTAINS(LCASE(STR(?bachelorDegree)), "bachelor"))

  ?semesterUri rdf:type :semesters ;
               :semester_name ?semesterName .
}
GROUP BY ?semesterUri ?semesterName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?semester_id 
WHERE {
  ?enrolment_master rdf:type :student_enrolment ;
                    :ref-degree_program ?degree_master .
  ?degree_master rdf:type :degree_programs ;
                 :degree_summary_name "Master" .
  ?enrolment_master :ref-semester ?semester .

  ?enrolment_bachelor rdf:type :student_enrolment ;
                     :ref-degree_program ?degree_bachelor .
  ?degree_bachelor rdf:type :degree_programs ;
                  :degree_summary_name "Bachelor" .
  ?enrolment_bachelor :ref-semester ?semester .

  ?semester rdf:type :semesters ;
            :semester_id ?semester_id .
}

