SELECT ?student_id ?first_name ?last_name ?middle_name ?ssn ?email_address ?cell_mobile_number ?date_first_registered ?date_left ?current_address_id ?permanent_address_id ?other_student_details 
WHERE {
  ?student rdf:type :students ;
           :student_id ?student_id ;
           :first_name ?first_name ;
           :last_name ?last_name ;
           :middle_name ?middle_name ;
           :ssn ?ssn ;
           :email_address ?email_address ;
           :cell_mobile_number ?cell_mobile_number ;
           :date_first_registered ?date_first_registered ;
           :date_left ?date_left ;
           :current_address_id ?current_address_id ;
           :permanent_address_id ?permanent_address_id ;
           :other_student_details ?other_student_details .
}
ORDER BY DESC(?last_name) ASC(?first_name)

SELECT ?course_id ?section_description ?section_id ?section_name 
WHERE {
  ?section rdf:type :sections ;
           :section_name "h" ;
           :course_id ?course_id ;
