SELECT ?country WHERE {
  ?channel rdf:type :tv_channel .
  ?channel :country ?country .
}
MINUS
{
  ?channel rdf:type :tv_channel .
  ?cartoon rdf:type :cartoon .
  ?cartoon :written_by "Todd Casey" .
  ?cartoon :ref-channel ?channel .
}

SELECT DISTINCT ?country 
WHERE {
  ?channel rdf:type :tv_channel ;
           :country ?country .
}
MINUS [
  SELECT DISTINCT ?country 
  WHERE {
    ?cartoon rdf:type :cartoon ;
             :written_by "Todd Casey" ;
             :ref-channel ?channel .
    ?channel rdf:type :tv_channel ;
             :country ?country .
  }
]

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?seriesName ?country 
WHERE {
  ?channel rdf:type :tv_channel ;
           :series_name ?seriesName ;
           :country ?country .

  ?cartoon rdf:type :cartoon ;
           :ref-channel ?channel ;
           :directed_by ?director .

  FILTER (CONTAINS(LCASE(STR(?director)), "ben jones") || 
          CONTAINS(LCASE(STR(?director)), "michael chang"))
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?seriesName ?country 
WHERE {
  ?channel rdf:type :tv_channel ;
           :series_name ?seriesName ;
           :country ?country .

  {
    SELECT ?channel 
    WHERE {
      ?cartoon1 rdf:type :cartoon ;
                :directed_by "Ben Jones" ;
                :ref-channel ?channel .
    }
  } UNION {
    SELECT ?channel 
    WHERE {
      ?cartoon2 rdf:type :cartoon ;
                :directed_by "Michael Chang" ;
                :ref-channel ?channel .
    }
  }

  FILTER(REGEX(STR(?seriesName), ".*", "i"))
}
GROUP BY ?seriesName ?country

SELECT ?channelId 
WHERE {
  ?channel rdf:type :tv_channel .
  ?channel :tv_channel-id ?channelId .
}
MINUS
{
  SELECT ?channelId 
  WHERE {
    ?cartoon rdf:type :cartoon .
    ?cartoon :directed_by "Ben Jones" .
    ?cartoon :ref-channel ?channel .
    ?channel :tv_channel-id ?channelId .
  }
}

