SELECT 
  (MAX(?areaCode) AS ?maxAreaCode)
  (MIN(?areaCode) AS ?minAreaCode)
WHERE {
  {
    ?areaCodeState :area_code ?areaCode .
  }
  UNION
  {
    ?votes :area_code ?areaCode .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
