PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?state ?created 
WHERE {
  ?vote rdf:type :votes ;
        :state ?state ;
        :created ?created .
}

SELECT ?contestantName ?contestantNumber 
WHERE {
  ?vote :ref-contestant_number ?contestant .
  ?contestant :contestant_name ?contestantName ;
             :contestant_number ?contestantNumber .
}
GROUP BY ?contestant 
HAVING (COUNT(?vote) = MIN(COUNT(?vote)))
ORDER BY COUNT(?vote)
LIMIT 1

