SELECT (COUNT(DISTINCT ?lang) AS ?count)
WHERE {
  ?lang rdf:type :countrylanguage ;
        :countrycode "AFG" ;
        :isofficial "T" .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?lang) AS ?count)
WHERE {
  ?country rdf:type :country ;
           :code "AFG" .
  ?lang rdf:type :countrylanguage ;
        :isofficial "T" ;
        :ref-countrycode ?country .
}
GROUP BY ?country

SELECT ?countryName 
WHERE {
  {
    SELECT ?country (COUNT(?language) AS ?langCount)
    WHERE {
      ?language rdf:type :countrylanguage .
      ?language :ref-countrycode ?country .
    }
    GROUP BY ?country
    ORDER BY DESC(?langCount)
    LIMIT 1
  }

  ?country rdf:type :country .
  ?country :name ?countryName .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
