SELECT (COUNT(DISTINCT ?country) AS ?numberOfNations)
WHERE {
  ?lang1 rdf:type :countrylanguage ;
         :language "English" ;
         :ref-countrycode ?country .

  ?lang2 rdf:type :countrylanguage ;
         :language "Dutch" ;
         :ref-countrycode ?country .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?countryName 
WHERE {
  ?lang1 rdf:type :countrylanguage ;
         :ref-countrycode ?country ;
         :language ?lang1Name .

  ?lang2 rdf:type :countrylanguage ;
         :ref-countrycode ?country ;
         :language ?lang2Name .

  FILTER(LCASE(STR(?lang1Name)) = "french" && LCASE(STR(?lang2Name)) != "french")

  ?country :name ?countryName .
}
GROUP BY ?countryName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?countryName 
WHERE {
  {
    ?langEng rdf:type :countrylanguage ;
             :isofficial "T" ;
             :language ?engLang .
    FILTER(LCASE(STR(?engLang)) = "english")
    ?langEng :ref-countrycode ?country .
  }
  UNION
  {
    ?langFra rdf:type :countrylanguage ;
             :isofficial "T" ;
             :language ?fraLang .
    FILTER(LCASE(STR(?fraLang)) = "french")
    ?langFra :ref-countrycode ?country .
  }
  ?country rdf:type :country ;
           :name ?countryName .
}
GROUP BY ?countryName
HAVING (COUNT(DISTINCT ?engLang) >= 1 && COUNT(DISTINCT ?fraLang) >= 1)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName 
WHERE {
  ?lang1 rdf:type :countrylanguage ;
         :ref-countrycode ?country ;
         :language "English" ;
         :isofficial "T" .

  ?lang2 rdf:type :countrylanguage ;
         :ref-countrycode ?country ;
         :language "French" ;
         :isofficial "T" .

  ?country rdf:type :country ;
           :name ?countryName .
}
GROUP BY ?countryName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?continent 
WHERE {
  ?countrylang rdf:type :countrylanguage ;
               :language "Chinese" ;
               :ref-countrycode ?country .
  ?country rdf:type :country ;
           :continent ?continent .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?region 
WHERE {
  ?countrylang rdf:type :countrylanguage ;
               :language ?language ;
               :ref-countrycode ?country .
  ?country rdf:type :country ;
           :region ?region .
  FILTER (?language = "English" || ?language = "Dutch")
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityName (MAX(?population) AS ?maxPopulation)
WHERE {
  ?city rdf:type :city ;
        :name ?cityName ;
        :countrycode ?countryCode ;
        :population ?population .

  ?countryLanguage rdf:type :countrylanguage ;
                    :ref-countrycode ?country ;
                    :countrycode ?countryCode ;
                    :language "English" ;
                    :isofficial "T" .
}
GROUP BY ?cityName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityName ?population 
WHERE {
  ?city rdf:type :city ;
        :name ?cityName ;
        :ref-countrycode ?country ;
        :population ?population .

  ?country rdf:type :country ;
           :code ?countryCode .

  ?language rdf:type :countrylanguage ;
            :ref-countrycode ?country ;
            :language "English" .
}
ORDER BY DESC(?population)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

CONSTRUCT {
  ?country
    :name ?countryName ;
    :population ?population ;
    :lifeexpectancy ?lifeExpectancy .
}
WHERE {
  SELECT ?country ?countryName ?population ?lifeExpectancy 
  WHERE {
    ?country rdf:type :country ;
             :name ?countryName ;
             :population ?population ;
             :lifeexpectancy ?lifeExpectancy ;
             :surfacearea ?surfaceArea ;
             :continent "Asia" .
  }
  ORDER BY DESC(?surfaceArea)
  LIMIT 1
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?lifeExpectancy) AS ?avgLifeExpectancy)
WHERE {
  ?cl rdf:type :countrylanguage ;
     :language ?lang ;
     :isofficial ?isOfficial ;
     :ref-countrycode ?co .
  ?co rdf:type :country ;
     :lifeexpectancy ?lifeExpectancy .
  FILTER(REGEX(STR(?lang), "english", "i") && !REGEX(STR(?isOfficial), "yes", "i"))
}
GROUP BY ?co

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?lifeExpectancy) AS ?meanLifeExpectancy)
WHERE {
  ?countryLanguage rdf:type :countrylanguage ;
    :language "English" ;
    :isofficial "no" ;
    :ref-countrycode ?country .

  ?country rdf:type :country ;
    :lifeexpectancy ?lifeExpectancy .
}
GROUP BY ?country

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?population) AS ?total_population)
WHERE {
  ?country rdf:type :country ;
           :name ?countryName ;
           :population ?population .

  FILTER NOT EXISTS {
    ?language rdf:type :countrylanguage ;
              :ref-countrycode ?country ;
              :language "English" .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?language 
WHERE {
  ?countryLanguage rdf:type :countrylanguage ;
    :isofficial "T" ;
    :ref-countrycode ?country ;
    :language ?language .

  ?country rdf:type :country ;
    :headofstate ?headOfState .

  FILTER(LCASE(STR(?headOfState)) = "beatrix")
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?language 
WHERE {
    ?countryLanguage rdf:type :countrylanguage ;
                     :ref-countrycode ?country ;
                     :isofficial "true" ;
                     :language ?language .
    ?country rdf:type :country ;
             :indepyear ?indepYear .
    FILTER(?indepYear < 1930 && ?indepYear > 0)
}

SELECT ?africanCountry WHERE {
  ?africanCountry rdf:type :country .
  ?africanCountry :region "Africa" .
  ?africanCountry :population ?popAfr .

  FILTER (
    NOT EXISTS {
      ?asianCountry rdf:type :country .
      ?asianCountry :region "Asia" .
      ?asianCountry :population ?popAsi .
      WHERE { ?popAsi <= ?popAfr }
    }
  )
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryAfricanLabel
WHERE {
  ?countryAfrican rdf:type :country ;
                  :continent "Africa" ;
                  :population ?popAfrican .

  ?countryAfrican :name ?countryAfricanLabel .

  FILTER NOT EXISTS {
    ?countryAsian rdf:type :country ;
                  :continent "Asia" ;
                  :population ?popAsian .

    FILTER (?popAsian <= ?popAfrican)
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?asiaCountryName 
WHERE {
  ?asiaCountry rdf:type :country ;
               :continent "Asia" ;
               :population ?asiaPop ;
               :name ?asiaCountryName .

  {
    SELECT (MAX(?africaPop) AS ?maxAfricaPop)
    WHERE {
      ?africaCountry rdf:type :country ;
                     :continent "Africa" ;
                     :population ?africaPop .
    }
  }

  FILTER (?asiaPop > ?maxAfricaPop)
}
GROUP BY ?asiaCountryName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryCode WHERE {
  ?languageInstance rdf:type :countrylanguage ;
                    :countrycode ?countryCode ;
                    :language ?lang .
  FILTER (?lang != "English")
}

SELECT ?countrycode 
WHERE {
  ?language rdf:type :countrylanguage ;
            :language ?lang ;
            :countrycode ?countrycode .
  FILTER(NOT CONTAINS(LCASE(STR(?lang)), "english"))
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?code WHERE {
  ?country rdf:type :country ;
           :code ?code ;
           :governmentform ?govForm .

  FILTER (?govForm != "Republic")

  FILTER NOT EXISTS {
    ?lang rdf:type :countrylanguage ;
          :ref-countrycode ?country ;
          :language "English" ;
          :isofficial "T" .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?countryCode 
WHERE {
  ?country rdf:type :country ;
           :code ?countryCode ;
           :governmentform ?governmentForm .
  ?language rdf:type :countrylanguage ;
            :ref-countrycode ?country ;
            :language ?lang .
  FILTER(LCASE(STR(?lang)) != "english" && LCASE(STR(?governmentForm)) != "republic")
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityName 
WHERE {
  ?city rdf:type :city ;
        :ref-countrycode ?country ;
        :name ?cityName .

  ?country rdf:type :country ;
           :region "Europe" .

  ?langInst rdf:type :countrylanguage ;
            :ref-countrycode ?country ;
            :isofficial ?isOfficial ;
            :language ?language .

  FILTER(?isOfficial != true && LCASE(STR(?language)) = "english")
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityName 
WHERE {
  ?country_uri rdf:type :country ;
               :region "Asia"^^xsd:string ;
               :code ?countryCode .

  ?language_uri rdf:type :countrylanguage ;
                :ref-countrycode ?country_uri ;
                :language "Chinese"^^xsd:string ;
                :isofficial "T"^^xsd:string .

  ?city_uri rdf:type :city ;
            :ref-countrycode ?country_uri ;
            :name ?cityName .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName ?indepYear ?surfaceArea 
WHERE {
  ?country rdf:type :country ;
           :name ?countryName ;
           :indepyear ?indepYear ;
           :surfacearea ?surfaceArea ;
           :population ?pop .

  # Find the minimum :population
  {
    SELECT (MIN(?p) AS ?minPop)
    WHERE {
      ?c rdf:type :country ;
         :population ?p .
    }
  }

  FILTER (?pop = ?minPop)
}
GROUP BY ?countryName ?indepYear ?surfaceArea

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName ?indepYear ?surfaceArea 
WHERE {
  ?country rdf:type :country ;
           :name ?countryName ;
           :population ?population ;
           :surfacearea ?surfaceArea .
  OPTIONAL { ?country :indepyear ?indepYear }
}
ORDER BY ASC(?population)
LIMIT 1

SELECT ?countryName ?population ?leader ?maxArea
WHERE {
  {
    SELECT (MAX(?surfacearea) AS ?maxArea)
    WHERE {
      ?country a :country ;
               :surfacearea ?surfacearea .
    }
  }

  ?country a :country ;
           :surfacearea ?maxArea ;
           :name ?countryName ;
           :population ?population ;
           :headofstate ?leader .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName ?population ?headOfState
WHERE {
  ?country :name ?countryName ;
           :population ?population ;
           :headofstate ?headOfState ;
           :surfacearea ?surfaceArea .

  {
    SELECT (MAX(?sa) AS ?maxSurfaceArea)
    WHERE {
      ?c :surfacearea ?sa .
    }
  }

  FILTER (?surfaceArea = ?maxSurfaceArea)
}
GROUP BY ?countryName ?population ?headOfState
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?district (COUNT(?city) AS ?count)
WHERE {
  ?city rdf:type :city ;
        :district ?district ;
        :population ?pop .
  {
    SELECT (AVG(?avgPop) AS ?avgPopulation)
    WHERE {
      ?cityAvg rdf:type :city ;
               :population ?avgPop .
    }
  }
  FILTER(?pop > ?avgPopulation)
}
GROUP BY ?district

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?governmentForm (SUM(?population) AS ?totalPopulation)
WHERE {
  ?country rdf:type :country ;
           :governmentform ?governmentForm ;
           :lifeexpectancy ?lifeExpectancy ;
           :population ?population .
}
GROUP BY ?governmentForm
HAVING (AVG(?lifeExpectancy) > 72)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?continent (AVG(?lifeExpectancy) AS ?averageLifeExpectancy) (SUM(?population) AS ?totalPopulation)
WHERE {
  ?country rdf:type :country ;
           :lifeexpectancy ?lifeExpectancy ;
           :population ?population ;
           :continent ?continent .
}
GROUP BY ?continent
HAVING (?averageLifeExpectancy < 72)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName 
WHERE {
  ?country rdf:type :country ;
           :name ?countryName ;
           :continent "Europe" ;
           :population ?pop .
  FILTER(?pop >= 75000 && ?pop <= 85000)
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryName 
WHERE {
  ?country rdf:type :country ;
           :continent "Europe" ;
           :population 80000 ;
           :name ?countryName .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?population) AS ?totalPopulation) (AVG(?surfaceArea) AS ?averageArea)
WHERE {
  ?country rdf:type :country ;
           :continent "North America" ;
           :surfacearea ?surfaceArea ;
           :population ?population .
  FILTER (?surfaceArea > 3000)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
SELECT ?cityName ?population WHERE {
  ?city rdf:type :city ;
        :name ?cityName ;
        :population ?population .
  FILTER(?population >= 160000 && ?population <= 900000)
}

SELECT ?countryName ?language 
WHERE {
  ?country :name ?countryName .
  ?lang :ref-countrycode ?country ;
        :percentage ?percentage ;
        :language ?language .
  NOT EXISTS {
    ?otherLang :ref-countrycode ?country ;
               :percentage ?otherPercentage .
    FILTER (?otherPercentage > ?percentage)
  }
}
GROUP BY ?country

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?country) AS ?count)
WHERE {
  ?lang rdf:type :countrylanguage ;
        :language "Spanish" ;
        :ref-countrycode ?country .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryCode 
WHERE {
  ?lang rdf:type :countrylanguage ;
        :language "Spanish" ;
        :percentage ?percentage ;
        :countrycode ?countryCode .
}
GROUP BY ?countryCode 
ORDER BY DESC(?percentage)

SELECT ?beast (STR(?label) AS ?name) WHERE {
  ?beast a :Beast ;
         :hasAlignment :ChaoticGood .
  ?beast :hasLanguages ?lang .
  FILTER NOT EXISTS {
    ?beast :hasLanguages :DraconicL .
  }
  ?beast :hasName ?label .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?count) 
WHERE {
  ?beast a :Beast ;
         :hasLanguages ?language .
  ?language a :Language ;
            :hasName "TreantL" .
  FILTER NOT EXISTS {
    ?beast :hasAlignment ?alignment .
    ?alignment a :Alignment ;
               :hasName "TrueNeutral" .
  }
}

SELECT ( (COUNT(DISTINCT ?dragon) * 100) / ?total_dragons ) AS ?percentage
WHERE {
  ?dragon a :Beast;
          :beastCategoryName "dragon";
          :hasLanguages ?lang1;
          :hasLanguages ?lang2.
  ?lang1 a :Language;
         :hasName "DraconicL".
  ?lang2 a :Language;
         :hasName "CommonL".
}
BIND ( (SELECT (COUNT(DISTINCT ?dragon_total) AS ?total_dragons)
        WHERE { ?dragon_total a :Beast; :beastCategoryName "dragon" }) AS ?total_dragons )

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?avgDragons ?avgDemons
WHERE {
  # Average number of languages for dragons
  {
    SELECT (AVG(?langCount) AS ?avgDragons)
    WHERE {
      SELECT ?dragon (COUNT(?lang) AS ?langCount)
      WHERE {
        ?dragon a :Beast ;
                :beastCategoryName "dragon" ;
                :hasLanguages ?lang .
      }
      GROUP BY ?dragon
    }
  }
  UNION
  {
    SELECT (AVG(?langCount) AS ?avgDemons)
    WHERE {
      SELECT ?demon (COUNT(?lang) AS ?langCount)
      WHERE {
        ?demon a :Beast ;
                :beastCategoryName "demon" ;
                :hasLanguages ?lang .
      }
      GROUP BY ?demon
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast ?name WHERE {
  ?beast a :Beast ;
         :hasAlignment :LawfulEvil ;
         :hasLanguages :CommonL .
  ?beast :hasName ?name .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?skeleton) AS ?skeletonCount) (COUNT(DISTINCT ?zombie) AS ?zombieCount)
WHERE {
  ?skeleton a :Beast ;
            :beastCategoryName "skeleton" ;
            :hasAlignment ?skeletonAlignment .
  ?skeletonAlignment :hasName "TrueNeutral" .
  ?zombie a :Beast ;
          :beastCategoryName "zombie" ;
          :hasAlignment ?zombieAlignment .
  ?zombieAlignment :hasName "TrueNeutral" .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (
  (COUNT(DISTINCT ?angel) * 100.0 / COUNT(?angel)) AS ?percentage
) WHERE {
  ?angel a :Beast ;
         :beastCategoryName "angel" .
  OPTIONAL {
    ?angel :hasLanguages ?language .
    ?language a :Language ;
              :hasName "AquanL" .
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?speed) AS ?meanSpeed)
WHERE {
  ?beast a :Beast ;
         :beastCategoryName "spider" ;
         :hasSpeedValue ?speed .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast (SUM(?value) AS ?total) 
WHERE {
  ?beast a :Beast .
  BIND(STR(?beast) AS ?uri) .
  FILTER(STRSTARTS(?uri, "http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Satyr") || STRSTARTS(?uri, "http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Cacodaemon"))

  OPTIONAL { ?beast :atk ?atk . BIND(xsd:integer(?atk) AS ?value) }
  OPTIONAL { ?beast :cha ?cha . BIND(xsd:nonNegativeInteger(?cha) AS ?value) }
  OPTIONAL { ?beast :con ?con . BIND(xsd:nonNegativeInteger(?con) AS ?value) }
  OPTIONAL { ?beast :dex ?dex . BIND(xsd:nonNegativeInteger(?dex) AS ?value) }
  OPTIONAL { ?beast :str ?str . BIND(xsd:nonNegativeInteger(?str) AS ?value) }
  OPTIONAL { ?beast :wis ?wis . BIND(xsd:nonNegativeInteger(?wis) AS ?value) }
  OPTIONAL { ?beast :int ?int . BIND(xsd:nonNegativeInteger(?int) AS ?value) }
  OPTIONAL { ?beast :cmb ?cmb . BIND(xsd:integer(?cmb) AS ?value) }
  OPTIONAL { ?beast :cmd ?cmd . BIND(xsd:nonNegativeInteger(?cmd) AS ?value) }
  OPTIONAL { ?beast :hasACValue ?hasACValue . BIND(xsd:nonNegativeInteger(?hasACValue) AS ?value) }
  OPTIONAL { ?beast :hasCRValue ?hasCRValue . BIND(xsd:float(?hasCRValue) AS ?value) }
  OPTIONAL { ?beast :hasFlatFootedValue ?hasFlatFootedValue . BIND(xsd:nonNegativeInteger(?hasFlatFootedValue) AS ?value) }
  OPTIONAL { ?beast :hasFortValue ?hasFortValue . BIND(xsd:integer(?hasFortValue) AS ?value) }
  OPTIONAL { ?beast :hasHPValue ?hasHPValue . BIND(xsd:integer(?hasHPValue) AS ?value) }
  OPTIONAL { ?beast :hasInitValue ?hasInitValue . BIND(xsd:integer(?hasInitValue) AS ?value) }
  OPTIONAL { ?beast :hasRefValue ?hasRefValue . BIND(xsd:integer(?hasRefValue) AS ?value) }
  OPTIONAL { ?beast :hasSpeedValue ?hasSpeedValue . BIND(xsd:nonNegativeInteger(?hasSpeedValue) AS ?value) }
  OPTIONAL { ?beast :hasTouchValue ?hasTouchValue . BIND(xsd:nonNegativeInteger(?hasTouchValue) AS ?value) }
  OPTIONAL { ?beast :hasWillValue ?hasWillValue . BIND(xsd:integer(?hasWillValue) AS ?value) }
  OPTIONAL { ?beast :hasXPValue ?hasXPValue . BIND(xsd:nonNegativeInteger(?hasXPValue) AS ?value) }
}
GROUP BY ?beast
ORDER BY DESC(?total)

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?attribute (AVG(?value) AS ?average) WHERE {
  {
    ?beast a :Beast ;
           :beastCategoryName "skeleton" .
    ?beast :hasACValue ?value .
    BIND("AC" AS ?attribute)
  }
  UNION
  {
    ?beast a :Beast ;
           :beastCategoryName "skeleton" .
    ?beast :hasFortValue ?value .
    BIND("Fortitude" AS ?attribute)
  }
  UNION
  {
    ?beast a :Beast ;
           :beastCategoryName "skeleton" .
    ?beast :hasRefValue ?value .
    BIND("Reflex" AS ?attribute)
  }
  UNION
  {
    ?beast a :Beast ;
           :beastCategoryName "skeleton" .
    ?beast :hasWillValue ?value .
    BIND("Will" AS ?attribute)
  }
} GROUP BY ?attribute ORDER BY DESC(?average) LIMIT 1

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?value) AS ?lowestDefensiveAttribute)
WHERE {
  {
    ?ogre a :Beast ;
          :beastCategoryName "ogre" .
    ?ogre :hasACValue ?value .
  }
  UNION
  {
    ?ogre a :Beast ;
          :beastCategoryName "ogre" .
    ?ogre :hasFortValue ?value .
  }
  UNION
  {
    ?ogre a :Beast ;
          :beastCategoryName "ogre" .
    ?ogre :hasWillValue ?value .
  }
  UNION
  {
    ?ogre a :Beast ;
          :beastCategoryName "ogre" .
    ?ogre :hasRefValue ?value .
  }
  UNION
  {
    ?ogre a :Beast ;
          :beastCategoryName "ogre" .
    ?ogre :hasHPValue ?value .
  }
}

SELECT ?beastName
WHERE {
  ?language a :Language ;
            :hasName "AkloL" ;
            :spokenBy ?beast .
  ?beast :hasName ?beastName .
  ?beast :atk ?atk .
  FILTER(?atk = (SELECT MAX(?atk2) WHERE {
    ?language2 a :Language ;
              :hasName "AkloL" ;
              :spokenBy ?beast2 .
    ?beast2 :atk ?atk2 .
  }))
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?atk) AS ?avgAtk) WHERE {
  ?robot a :Beast ;
         :beastCategoryName "robot" ;
         :atk ?atk .
}

SELECT (COUNT(?demon) AS ?count) {
  ?demon a :Beast ;
         :beastCategoryName "demon" ;
         :cmd ?cmd .
  FILTER(?cmd > (SELECT (AVG(?cmd2) AS ?avgCmd) WHERE { ?beast2 a :Beast ; :cmd ?cmd2 . } ))
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
