SELECT ?beast WHERE {
  ?beast a :Beast ;
         :beastCategoryName "spider" ;
         :hasTouchValue 11 .
}

SELECT COUNT(*) WHERE {
  ?language :hasName "ProteanL" .
  ?beast :hasLanguages ?language .
  ?beast :con ?con .
  FILTER(?con > 10)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast WHERE {
  ?beast a :Beast ;
         :hasName "golem" ;
         :str ?str ;
         :cha ?cha .
  FILTER (xsd:integer(?str) < xsd:integer(?cha))
}

SELECT (AVG(?wis) AS ?averageWisdom) {
  ?beast :hasAlignment ?alignment.
  ?alignment :hasName "LawfulNeutral".
  ?beast :wis ?wis.
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?darkCount ?cyclopsCount
WHERE {
  { 
    SELECT (COUNT(?beast) AS ?darkCount)
    WHERE {
      ?beast a :Beast ;
             :hasLanguages ?darkLang .
      ?darkLang a :Language ;
                :hasName "DarkL" .
    }
  }
  UNION
  { 
    SELECT (COUNT(?beast) AS ?cyclopsCount)
    WHERE {
      ?beast a :Beast ;
             :hasLanguages ?cyclopsLang .
      ?cyclopsLang a :Language ;
                   :hasName "CyclopsL" .
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?language WHERE {
  {
    ?lorellei a :Beast ;
              :hasName "Lorelei" .
    ?siren a :Beast ;
            :hasName "Siren" .
    ?lorellei :hasLanguages ?language .
    ?siren :hasLanguages ?language .
  }
  UNION
  {
    ?lorellei a :Beast ;
              :hasName "Lorelei" .
    ?seaweedSiren a :Beast ;
                   :hasName "Seaweed Siren" .
    ?lorellei :hasLanguages ?language .
    ?seaweedSiren :hasLanguages ?language .
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?dex) AS ?averageDex)
WHERE {
  {
    ?beast a :Beast ;
           :hasName "Phoenix" ;
           :dex ?dex .
  }
  UNION
  {
    ?beast a :Beast ;
           :hasName "Sleipnir" ;
           :dex ?dex .
  }
}

SELECT ?employee rdfs:label ?label
WHERE {
  ?employee a pv:Employee ;
            pv:areaOfExpertise <http://ld.company.org/prod-instances/prod-cat-Sensor> .
  ?employee rdfs:label ?label .
}
GROUP BY ?employee ?label
ORDER BY ?label

SELECT ?manager (pv:name(?manager) AS ?managerLabel)
WHERE {
  ?dept a pv:Department ;
        pv:name "Data Services" .
  ?manager a pv:Manager ;
           pv:memberOf ?dept .
}

SELECT ?employee ?name ?email ?phone
WHERE {
  ?employee a pv:Employee .
  NOT EXISTS {
    ?employee a pv:Manager .
    ?employee pv:hasDirectReport ?report .
  }
  ?employee pv:name ?name .
  ?employee pv:email ?email .
  ?employee pv:phone ?phone .
}
ORDER BY ?name

SELECT ?hardware (xsd:decimal(?width) AS ?width_mm) (xsd:decimal(?height) AS ?height_mm) (xsd:decimal(?depth) AS ?depth_mm)
WHERE {
  ?hardware a pv:Hardware ;
           pv:width_mm ?width ;
           pv:height_mm ?height ;
           pv:depth_mm ?depth .
  FILTER(?width > ?height && ?depth < 50)
}

SELECT COUNT(DISTINCT ?supplier) WHERE {
  <http://ld.company.org/prod-instances/hw-K367-1320550> pv:compatibleProduct ?product .
  ?product pv:hasSupplier ?supplier .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?date ?result
WHERE {
  ?battle a :battle ;
          :name ?name ;
          :date ?date ;
          :result ?result .
}

SELECT COUNT(?battle) WHERE {
  ?battle a :battle .
  NOT EXISTS {
    ?ship a :ship ;
          :tonnage "225" ;
          :ref-lost_in_battle ?battle .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?battle ?name ?result ?bulgarianCommander
WHERE {
  ?battle a :battle ;
          :name ?name ;
          :result ?result ;
          :bulgarian_commander ?bulgarianCommander .
  FILTER NOT EXISTS {
    ?ship a :ship ;
          :location "English Channel" ;
          :lost_in_battle ?battle .
  }
}

SELECT ?model WHERE {
  ?car :ref ?car_names .
  ?car_names :model ?model .
  ?car :weight ?weight .
  {
    SELECT (AVG(?weight2) AS ?avgWeight)
    WHERE {
      ?car2 :weight ?weight2 .
    }
  }
  FILTER(?weight < ?avgWeight)
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?model WHERE {
  {
    SELECT (AVG(?weight) AS ?avgWeight) WHERE {
      ?car a :cars_data ;
           :weight ?weight .
    }
  }
  ?car a :cars_data ;
       :weight ?weight .
  ?car :ref ?carName .
  ?carName a :car_names ;
           :model ?model .
  FILTER(?weight < ?avgWeight)
} GROUP BY ?model

SELECT ?make ?year
WHERE {
  {
    SELECT ?minYear
    WHERE {
      ?carData :year ?year .
      MIN(?year) AS ?minYear
    }
  }
  ?carData :year ?year .
  ?carData :ref ?carName .
  ?carName :make ?make .
  FILTER (?year = ?minYear)
}
GROUP BY ?make ?year

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?maker) AS ?count) WHERE {
  ?maker a :car_makers ;
         :country ?countryId .
  ?country a :countries ;
           :countryid ?countryId ;
           :countryname "France" .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?model) AS ?count)
WHERE {
  ?country a :countries ;
           :countryname "USA" .
  ?carMaker a :car_makers ;
            :ref-country ?country .
  ?modelList a :model_list ;
