  }
  UNION
  {
    ?car_data a :cars_data;
             :weight ?weight .
    FILTER (?weight > 3500)
    ?car_name :ref ?car_data.
    ?car_name :model ?model.
  }
}

SELECT (COUNT(?car) AS ?count)
WHERE {
  ?car a :cars_data ;
       :accelerate ?accelerate .
  VALUES ?maxHorsepower {
    SELECT (MAX(CAST(?horsepower AS xsd:decimal)) AS ?maxHorsepower)
    WHERE {
      ?car2 a :cars_data ;
             :horsepower ?horsepower .
    }
  }
  FILTER(?accelerate > ?maxHorsepower)
}

SELECT (COUNT(?car) AS ?count) WHERE {
  ?car a :cars_data ;
       :accelerate ?accelerate .
  FILTER(?accelerate > (SELECT MAX(CAST(?horsepower AS xsd:decimal)) WHERE {
    ?car2 a :cars_data ;
          :horsepower ?horsepower .
  }))
}

