  FILTER EXISTS {
    ?concert2 :year "2015" ;
              :ref-stadium ?stadium .
  }
}

SELECT (COUNT(?concert) AS ?numConcerts) {
  ?concert a :concert ;
           :ref-stadium ?stadium .
  ?stadium a :stadium ;
           :capacity ?capacity .
  {
    SELECT MAX(?capacity) AS ?maxCapacity
    WHERE {
      ?stadium2 a :stadium ;
                :capacity ?capacity .
    }
  }
  FILTER(?capacity = ?maxCapacity)
}
GROUP BY ?stadium ?capacity

SELECT (COUNT(?concert) AS ?numConcerts)
WHERE {
