    SELECT ?stadium
    WHERE {
      ?stadium a :stadium ;
               :capacity ?capacity .
      ORDER BY DESC(?capacity)
      LIMIT 1
    }
  }
  ?concert a :concert ;
           :ref-stadium ?stadium .
}

