  {
    ?owner :first_name ?firstName .
    FILTER NOT EXISTS { ?dog :name ?firstName }
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?firstName
WHERE {
  {
    ?professional a :professionals ;
                  :first_name ?firstName .
  }
  UNION
  {
    ?owner a :owners ;
           :first_name ?firstName .
  }
  FILTER NOT EXISTS {
    ?dog a :dogs ;
         :name ?firstName .
  }
}

SELECT ?dogName ?treatmentDate
WHERE {
  {
    SELECT ?breed
    WHERE {
      {
        SELECT ?breed (COUNT(?dog) AS ?count)
        WHERE {
          ?dog a :dogs;
               :ref-breed_code ?breed.
        }
        GROUP BY ?breed
        ORDER BY ?count
        LIMIT 1
      }
    }
  }
  ?dog a :dogs;
       :ref-breed_code ?breed;
       :name ?dogName.
  ?treatment :ref-dog ?dog;
             :date_of_treatment ?treatmentDate.
}
GROUP BY ?dogName ?treatmentDate

SELECT ?dog ?dogName ?treatmentDate
WHERE {
  {
    SELECT ?breedCode
    WHERE {
      SELECT ?breedCode (COUNT(?dog2) AS ?count)
      WHERE {
        ?dog2 :ref-breed_code ?breedCode .
        ?breedCode a :breeds .
      }
      GROUP BY ?breedCode
      ORDER BY ?count ASC
      LIMIT 1
    }
  }
  ?dog :ref-breed_code ?breedCode .
  ?dog :name ?dogName .
  ?treatment :ref-dog ?dog .
  ?treatment :date_of_treatment ?treatmentDate .
}

