        :number_products ?numProducts
}
ORDER BY DESC ?numProducts

SELECT ?shopName
WHERE {
  ?shop :number_products ?numProducts.
  ?shop rdfs:label ?shopName.
  {
    SELECT ((AVG(?numProducts)) AS ?avgProducts)
    WHERE {
      ?shop :number_products ?numProducts.
    }
  }
  FILTER (?numProducts > ?avgProducts)
}

