SELECT (COUNT(?flight) AS ?count) WHERE {
  ?airport a :airports ;
           :city "Aberdeen" .
  ?flight a :flights ;
          :sourceairport ?airport .
}

SELECT COUNT(?flight) AS ?count WHERE {
  ?flight :ref-sourceairport ?airport .
  ?airport :airportname ?name .
  FILTER(CONTAINS(LCASE(STR(?name)), "Aberdeen"))
}

SELECT COUNT(?flight) AS ?count
WHERE {
  ?flight :ref-destairport ?airport .
  ?airport :airportname "Aberdeen" .
}

SELECT COUNT(*) AS ?count WHERE {
  ?flight :ref-sourceairport ?sourceAirport .
  ?flight :ref-destairport ?destAirport .
  ?sourceAirport :city "Aberdeen" .
  ?destAirport :city "Ashley" .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?airportCode
WHERE {
  {
    SELECT ?airportCode (COUNT(*) AS ?totalFlights)
    WHERE {
      {
        ?flight :ref-sourceairport ?airport .
        ?airport :airportcode ?airportCode .
      }
      UNION
      {
        ?flight :ref-destairport ?airport .
        ?airport :airportcode ?airportCode .
      }
    }
    GROUP BY ?airportCode
    ORDER BY DESC(?totalFlights)
    LIMIT 1
  }
}

SELECT ?airport ?airportname
WHERE {
  ?airport a :airports .
  ?airport :airportname ?airportname .
  NOT EXISTS {
    ?flight :ref-sourceairport ?airport .
  }
  NOT EXISTS {
    ?flight :ref-destairport ?airport .
  }
}

