  ?visitor a :visitor .
  ?visitor :age ?age .
  FILTER(?age < 30)
}

SELECT AVG(?age) WHERE {
  ?visitor :age ?age .
  ?visitor :level_of_membership ?level .
  FILTER (?level <= 4)
}

SELECT (SUM(?totalSpent) AS totalTicketExpense)
WHERE {
  ?visit :ref-visitor ?visitor .
  ?visitor :level_of_membership 1 .
  ?visit :total_spent ?totalSpent .
}

