PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name (COUNT(?friend) AS ?friendCount)
WHERE {
  ?highschooler a :highschooler ;
                 :name ?name .
  {
    ?friend a :friend ;
            :ref-friend ?highschooler .
  }
  UNION
  {
    ?friend a :friend ;
            :ref-student ?highschooler .
  }
}
GROUP BY ?name

PREFIX : <http://valuenet/ontop/>
