SELECT ?friendName WHERE {
  ?kyle a :highschooler ;
        :name "Kyle" .
  {
    ?friend a :friend ;
            :ref-student ?kyle ;
            :ref-friend ?friendHighschooler .
    ?friendHighschooler a :highschooler ;
                         :name ?friendName .
  }
  UNION
  {
    ?friend a :friend ;
            :ref-friend ?kyle ;
            :ref-student ?friendHighschooler .
    ?friendHighschooler a :highschooler ;
                         :name ?friendName .
  }
}

