PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?name
WHERE {
  ?student a :highschooler ;
           :name ?name .
  FILTER NOT EXISTS {
    ?friend a :friend ;
            :ref-student ?student .
  }
}

SELECT ?id
WHERE {
  ?highschooler :id ?id .
  EXISTS {
    {
      ?friend :student_id ?id ;
              :ref-student ?highschooler .
    }
    UNION
    {
      ?friend :friend_id ?id ;
              :ref-friend ?highschooler .
    }
  }
  EXISTS {
    ?likes :liked_id ?id ;
           :ref-liked ?highschooler .
  }
}

SELECT ?name
WHERE {
  ?student a :highschooler ;
           :name ?name .
  EXISTS {
    {
      ?friend a :friend ;
              :ref-student ?student .
    }
    UNION
    {
      ?friend a :friend ;
              :ref-friend ?student .
    }
  }
  EXISTS {
    ?like a :likes ;
          :ref-liked ?student .
  }
}

