  ?like a :likes ;
        :student_id ?studentId .
}
GROUP BY ?name

SELECT ?name WHERE {
  ?highschooler a :highschooler ;
                :name ?name ;
                :grade ?grade .
  FILTER(?grade > 5)
  ?friend a :friend ;
          :ref-student ?highschooler .
  GROUP BY ?highschooler ?name
  HAVING (COUNT(?friend) >= 2)
}

SELECT COUNT(*) WHERE {
  ?like :ref-student <http://valuenet/ontop/highschooler/id-1934> .
}

SELECT (COUNT(*) AS ?likeCount) {
  ?kyle a :highschooler ;
        :name "Kyle" ;
        :id ?kyleId .
  ?like a :likes ;
        :student_id ?kyleId .
}
WHERE {
  ?kyle a :highschooler ;
        :name "Kyle" ;
        :id ?kyleId .
  ?like a :likes ;
        :student_id ?kyleId .
}

SELECT AVG(?grade) WHERE {
  ?student a :highschooler .
  ?student :grade ?grade .
  EXISTS {
    ?friend a :friend .
    ?friend :ref-student ?student .
  }
}

PREFIX : <http://valuenet/ontop/>
