            :ref-student ?highschooler .
  }
}

SELECT COUNT(*) WHERE { 
  ?pet a :pets . 
  ?pet :weight ?weight . 
  FILTER(xsd:decimal(?weight) > 10) 
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?weight
WHERE {
  {
    SELECT ?pet
    WHERE {
      ?pet a :pets ;
           :pettype ?pettype ;
           :pet_age ?age .
      FILTER(CONTAINS(LCASE(STR(?pettype)), "dog"))
    }
    ORDER BY ?age
    LIMIT 1
  }
  ?pet :weight ?weight .
}

SELECT (COUNT(?pet) AS ?totalPets) {
  ?student a :student ;
           :age ?age .
  FILTER(?age > 20)
  ?student :ref-stu ?hasPet .
  ?hasPet :ref-pet ?pet .
}

SELECT COUNT(?pet) WHERE {
  ?student a :student ;
           :age ?age .
  FILTER(?age > 20)
  ?has_pet :ref-stu ?student ;
           :ref-pet ?pet .
}

PREFIX : <http://valuenet/ontop/>
