SELECT ?fname
WHERE {
  ?student a :student;
           :fname ?fname.
  ?hasPetCat a :has_pet;
             :ref-stu ?student;
             :ref-pet ?petCat.
  ?petCat :pettype "cat".
  ?hasPetDog a :has_pet;
             :ref-stu ?student;
             :ref-pet ?petDog.
  ?petDog :pettype "dog".
}

PREFIX : <http://valuenet/ontop/>
