SELECT ?major ?age
WHERE {
  ?student a :student ;
           :major ?major ;
           :age ?age .
  FILTER NOT EXISTS {
    ?student :ref-pet ?pet .
    ?pet :pettype "cat" .
  }
}

SELECT ?stuid
WHERE {
  ?student rdf:type :student.
  ?student :stuid ?stuid.
  NOT EXISTS {
    ?has_pet :ref-stu ?student.
    ?has_pet :ref-pet ?pet.
    ?pet :pettype "cat".
  }
}

