  ?singer a :singer ;
          :birth_year ?birth_year ;
          :citizenship ?citizenship .
}

SELECT ?name
WHERE {
  ?singer a :singer ;
          :singer_id ?singerId ;
          :name ?name .
  {
    SELECT ?singerId
    WHERE {
      ?song a :song ;
            :singer_id ?singerId .
    }
    GROUP BY ?singerId
    HAVING (COUNT(?song) > 1)
  }
}
GROUP BY ?singerId ?name

