PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?section_name ?section_description
WHERE {
  ?section a :sections ;
           :section_name ?section_name ;
           :section_description ?section_description .
}

SELECT ?lastName
WHERE {
  ?student a :students .
  ?student :last_name ?lastName .
  ( 
    ?student :ref-current_address ?currentAddr .
    ?currentAddr :state_province_county "North Carolina"
  )
  UNION
  ( 
    ?student :ref-permanent_address ?permanentAddr .
    ?permanentAddr :state_province_county "North Carolina"
  )
  FILTER NOT EXISTS {
    ?enrolment :ref-student ?student .
    ?enrolment :ref-degree_program ?degreeProgram .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cell_mobile_number
WHERE {
  ?student :first_name "Timmothy" ;
           :last_name "Ward" ;
           :cell_mobile_number ?cell_mobile_number .
}

SELECT ?addressId ?line1 ?line2 ?city ?state ?zip
WHERE {
  {
    SELECT ?addressId (COUNT(?student) AS ?studentCount)
    WHERE {
      ?student :current_address_id ?addressId .
    }
    GROUP BY ?addressId
    ORDER BY DESC(?studentCount)
    LIMIT 1
  }
  ?address :address_id ?addressId .
  ?address :line_1 ?line1 .
  ?address :line_2 ?line2 .
  ?address :city ?city .
  ?address :state_province_county ?state .
  ?address :zip_postcode ?zip .
}
GROUP BY ?addressId ?line1 ?line2 ?city ?state ?zip

SELECT ?semester_id
WHERE {
  ?semester a :semesters .
  ?semester :semester_id ?semester_id .
  EXISTS {
    ?enrolment :ref-semester ?semester .
    ?enrolment :ref-degree_program ?degree .
    ?degree :degree_summary_name "Master" .
  } .
  EXISTS {
    ?enrolment2 :ref-semester ?semester .
    ?enrolment2 :ref-degree_program ?degree2 .
    ?degree2 :degree_summary_name "Bachelor" .
  }
}

