  {
    ?student a :students ;
             :ref-permanent_address ?permanent_address .
    ?permanent_address :country "Haiti" .
    ?student :first_name ?first_name .
  }
  UNION
  {
    ?student :cell_mobile_number "09700166582" .
    ?student :first_name ?first_name .
  }
}

