SELECT ?seriesName ?country
WHERE {
  {
    ?cartoon :directed_by "Ben Jones" ;
             :ref-channel ?tvChannel .
    ?tvChannel :series_name ?seriesName ;
               :country ?country .
  }
  UNION
  {
    ?cartoon :directed_by "Michael Chang" ;
             :ref-channel ?tvChannel .
    ?tvChannel :series_name ?seriesName ;
               :country ?country .
  }
}

SELECT ?tvChannelId WHERE {
  {
    SELECT ?tvChannel (COUNT(*) AS ?count) WHERE {
      ?tvSeries :ref-channel ?tvChannel .
      UNION
      ?cartoon :ref-channel ?tvChannel .
    } GROUP BY ?tvChannel HAVING (COUNT(*) > 2)
  }
  ?tvChannel :tv_channel-id ?tvChannelId .
}

