PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?areaCode
WHERE {
  {
    SELECT ?areaCode (COUNT(*) AS ?count)
    WHERE {
      ?vote :ref-area_code ?areaCodeState .
      ?areaCodeState :area_code ?areaCode .
    }
    GROUP BY ?areaCode
    ORDER BY DESC(?count)
    LIMIT 1
  }
}

