SELECT ?vote ?created ?state ?phone_number
WHERE {
  ?contestant a :contestants ;
              :contestant_name "Tabatha Gehling" .
  ?vote :ref-contestant_number ?contestant ;
        :created ?created ;
        :state ?state ;
        :phone_number ?phone_number .
}
ORDER BY ?created

SELECT COUNT(?country) AS ?count
WHERE {
  ?country a :country ;
           :governmentform ?form .
  FILTER(CONTAINS(LCASE(STR(?form)), "republic"))
}

SELECT COUNT(*) WHERE {
  ?country a :country .
  ?country :governmentform "republic" .
}

