SELECT SUM(?surfaceArea) AS ?totalSurfaceArea
WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :surfacearea ?surfaceArea .
  UNION
  ?country a :country ;
           :continent "Europe" ;
           :surfacearea ?surfaceArea .
}

SELECT (SUM(?surfaceArea) AS ?totalSurfaceArea) {
  {
    ?country a :country ;
             :region "Asia" ;
             :surfacearea ?surfaceArea .
  }
  UNION
  {
    ?country a :country ;
             :region "Europe" ;
             :surfacearea ?surfaceArea .
  }
}

