PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?govForm) AS ?count) 
WHERE {
  ?country a :country ;
           :continent "Africa" ;
           :governmentform ?govForm .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?govForm) AS ?count) WHERE {
  ?country a :country ;
           :continent "Africa" ;
           :governmentform ?govForm .
}

SELECT (COUNT(DISTINCT ?language) AS ?totalLanguages) {
  ?country a :country ;
           :name "Aruba" .
  ?countrylanguage :ref-countrycode ?country ;
                   :language ?language .
}

SELECT COUNT(*) WHERE {
  ?language a :countrylanguage ;
           :ref-countrycode <http://valuenet/ontop/country/code-ABW> .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(*) AS ?count) WHERE {
  ?country a :country ;
           :code "AFG" .
  ?language a :countrylanguage ;
            :ref-countrycode ?country ;
            :isofficial "T" .
}

SELECT COUNT(DISTINCT ?country) AS ?numNations
WHERE {
  ?country a :country .
  ?countrylanguage1 a :countrylanguage ;
                    :language "English" ;
                    :isofficial "T" ;
                    :ref-countrycode ?country .
  ?countrylanguage2 a :countrylanguage ;
                    :language "Dutch" ;
                    :isofficial "T" ;
                    :ref-countrycode ?country .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?country ?countryName
WHERE {
  ?countrylanguage1 a :countrylanguage ;
                     :language "English" ;
                     :countrycode ?countryCode .
  ?countrylanguage2 a :countrylanguage ;
                     :language "French" ;
                     :countrycode ?countryCode .
  ?country a :country ;
           :code ?countryCode .
  ?country :name ?countryName .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
