SELECT DISTINCT ?countryLabel
WHERE {
  {
    ?countrylanguage :language "English" ;
                     :isofficial "yes" ;
                     :ref-countrycode ?country .
    ?country :name ?countryLabel .
  }
  UNION
  {
    ?countrylanguage :language "Dutch" ;
                     :isofficial "yes" ;
                     :ref-countrycode ?country .
    ?country :name ?countryLabel .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?city ?population WHERE {
  ?lang_english a :countrylanguage ;
    :language "English" ;
    :ref-countrycode ?country .
  ?country :code ?countryCodeFull .
  ?city a :city ;
    :countrycode ?countryCode ;
    :population ?population .
  FILTER(STR(?countryCode) = ?countryCodeFull)
}
ORDER BY DESC(?population)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityName ?population WHERE {
  ?countrylanguage :language "English" ;
                   :countrycode ?countrycode .
  ?city :countrycode ?countrycode ;
        :name ?cityName ;
        :population ?population .
}
ORDER BY DESC(?population)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?population ?lifeexpectancy
WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :name ?name ;
           :population ?population ;
           :lifeexpectancy ?lifeexpectancy ;
           :surfacearea ?surfacearea .
}
ORDER BY DESC(?surfacearea)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?population ?lifeExpectancy
WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :surfacearea ?surfaceArea ;
           :population ?population ;
           :lifeexpectancy ?lifeExpectancy .
  ?country :name ?name .
}
ORDER BY DESC(?surfaceArea)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?lifeExpectancy) AS ?averageLifeExpectancy)
WHERE {
  ?country a :country ;
           :lifeexpectancy ?lifeExpectancy .
  FILTER NOT EXISTS {
    ?countrylanguage :language "English" ;
                     :isofficial "yes" ;
                     :ref-countrycode ?country .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?population) AS ?totalPopulation)
WHERE {
  ?country a :country ;
           :population ?population .
  FILTER NOT EXISTS {
    ?countryLanguage a :countrylanguage ;
                     :ref-countrycode ?country ;
                     :language "English" ;
                     :isofficial "yes" .
  }
}

SELECT (COUNT(DISTINCT ?language) AS ?totalLanguages) {
  ?country a :country ;
           :indepyear ?indepyear .
  FILTER(?indepyear < 1930)
  ?countrylanguage a :countrylanguage ;
                   :isofficial "T" ;
                   :ref-countrycode ?country .
  ?countrylanguage :language ?language .
}

SELECT ?country WHERE {
  ?country a :country .
  ?country :surfacearea ?surfaceArea .
  FILTER(?surfaceArea > (SELECT MAX(?europeSurfaceArea) WHERE {
    ?europeCountry a :country ;
                   :region "Europe" ;
                   :surfacearea ?europeSurfaceArea .
  }))
}

SELECT ?country ?name ?surfaceArea
WHERE {
  ?country a :country ;
           :surfacearea ?surfaceArea .
  ?country :name ?name .
  {
    SELECT MAX(?maxSurfaceArea) AS ?maxEuropeArea
    WHERE {
      ?europeCountry a :country ;
                     :continent "Europe" ;
                     :surfacearea ?maxSurfaceArea .
    }
  }
  FILTER(?surfaceArea > ?maxEuropeArea)
}
GROUP BY ?country ?name ?surfaceArea

SELECT ?africanCountry ?africanLabel
WHERE {
  ?africanCountry a :country ;
                  :continent "Africa" ;
                  :population ?popAfrican .
  ?africanCountry :name ?africanLabel .
  {
    SELECT MIN(?popAsian) AS ?minPopAsia
    WHERE {
      ?asianCountry a :country ;
                    :continent "Asia" ;
                    :population ?popAsian .
    }
  }
  FILTER(?popAfrican < ?minPopAsia)
}
GROUP BY ?africanCountry ?africanLabel
ORDER BY ?africanLabel

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?africanCountryLabel
WHERE {
  ?africanCountry a :country ;
                  :region "Africa" ;
                  :population ?popAfrican .
  ?africanCountry :name ?africanCountryLabel .
  {
    SELECT (MIN(?popAsia) AS ?minAsiaPop) WHERE {
      ?asiaCountry a :country ;
                   :region "Asia" ;
                   :population ?popAsia .
    }
  }
  FILTER (?popAfrican < ?minAsiaPop)
}
GROUP BY ?africanCountryLabel

SELECT ?countryName ?population
WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :population ?population .
  ?country :name ?countryName .
  FILTER(?population > (
    SELECT MAX(?afrPop)
    WHERE {
      ?afrCountry a :country ;
                  :continent "Africa" ;
                  :population ?afrPop .
    }
  ))
}

SELECT ?country ?population WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :population ?population .
  FILTER(?population > (
    SELECT (MAX(?africaPop) AS ?maxAfricaPop) WHERE {
      ?africaCountry a :country ;
                     :continent "Africa" ;
                     :population ?africaPop .
    }
  ))
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countryCode
WHERE {
  ?country a :country ;
           :code ?countryCode .
  FILTER NOT EXISTS {
    ?countrylanguage a :countrylanguage ;
                     :language "English" ;
                     :ref-countrycode ?country .
  }
  ?country :governmentform ?governmentform .
  FILTER (STR(?governmentform) != "Republic")
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityName
WHERE {
  ?country a :country ;
           :continent "Europe" .
  ?city a :city ;
        :countrycode ?countryCode .
  ?country :code ?countryCode .
  FILTER NOT EXISTS {
    ?countryLanguage a :countrylanguage ;
                     :ref-countrycode ?countryCode ;
                     :language "English" ;
                     :isofficial "yes" .
  }
  ?city :name ?cityName .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?cityName WHERE {
  ?countrylanguage :language "Chinese" ;
                   :isofficial "T" ;
                   :countrycode ?countrycode .
  ?country :code ?countrycode ;
           :continent "Asia" .
  ?city :countrycode ?countrycode ;
        :name ?cityName .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?cityName
WHERE {
  ?city a :city ;
        :countrycode ?countryCode .
  ?country a :country ;
          :code ?countryCode .
  ?country :continent "Asia" .
  ?language a :countrylanguage ;
            :countrycode ?countryCode ;
            :language "Chinese" ;
            :isofficial "T" .
  ?city :name ?cityName .
}
ORDER BY ?cityName

SELECT ?name ?indepyear ?surfacearea
WHERE {
  ?country a :country ;
           :population ?population ;
           :name ?name ;
           :indepyear ?indepyear ;
           :surfacearea ?surfacearea .
}
ORDER BY ?population ASC
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?population ?headofstate
WHERE {
  ?country a :country ;
           :surfacearea ?surfacearea ;
           :name ?name ;
           :population ?population ;
           :headofstate ?headofstate .
}
ORDER BY DESC(?surfacearea)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?district (COUNT(?city) AS ?count)
WHERE {
  ?city a :city ;
        :district ?district ;
        :population ?pop .
  { SELECT (AVG(?pop) AS ?avgPop) WHERE { ?city2 a :city ; :population ?pop2 } }
  FILTER (?pop > ?avgPop)
}
GROUP BY ?district

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?govForm (SUM(?pop) AS ?totalPopulation)
WHERE {
  ?country a :country;
           :governmentform ?govForm;
           :lifeexpectancy ?lifeExp;
           :population ?pop.
}
GROUP BY ?govForm
HAVING (AVG(?lifeExp) > 72)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?population) AS ?totalPopulation) (AVG(?surfacearea) AS ?avgSurfaceArea)
WHERE {
  ?country a :country ;
           :region "North America" ;
           :surfacearea ?surfacearea ;
           :population ?population .
  FILTER (?surfacearea > 3000)
}

SELECT COUNT(DISTINCT ?countryCode) AS ?totalCountries
WHERE {
  {
    SELECT (MAX(?percentage) AS ?maxPercentage)
    WHERE {
      ?countrylanguage :language "Spanish" ;
                       :percentage ?percentage .
    }
  }
  ?countrylanguage :language "Spanish" ;
                   :percentage ?maxPercentage ;
                   :ref-countrycode ?countryCode .
}

SELECT COUNT(DISTINCT ?country) WHERE {
  ?countrylanguage :language "Spanish" .
  ?countrylanguage :ref-countrycode ?countryCode .
  ?country :code ?countryCode .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countrycode
WHERE {
  ?countrylanguage a :countrylanguage ;
                   :language "Spanish" ;
                   :ref-countrycode ?countrycode ;
                   :percentage ?percentage .
}
ORDER BY DESC(?percentage)
LIMIT 1

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?count) WHERE {
  ?beast a :Beast ;
         :hasLanguages ?language .
  ?language :hasName "TreantL" .
  FILTER NOT EXISTS {
    ?beast :hasAlignment ?alignment .
    ?alignment :hasName "TrueNeutral" .
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast WHERE {
  ?beast a :Beast ;
         :hasAlignment ?alignment .
  ?alignment a :Alignment ;
             :hasName "NeutralGood" .
}

SELECT (
  ( (SELECT COUNT(DISTINCT ?dragon) WHERE {
    ?dragon a :Beast ;
            :beastCategoryName "dragon" .
    ?dragon :hasLanguages ?lang1 .
    ?lang1 :hasName "DraconicL" .
    ?dragon :hasLanguages ?lang2 .
    ?lang2 :hasName "CommonL" .
  }) * 100.0 ) / (SELECT COUNT(DISTINCT ?dragon) WHERE {
    ?dragon a :Beast ;
            :beastCategoryName "dragon" .
  })
) AS ?percentage

SELECT ?avgDragons ?avgDemons
WHERE {
  # Average languages for dragons
  {
    SELECT (AVG(?langCount) AS ?avgDragons)
    WHERE {
      ?dragon a :Beast ;
              :beastCategoryName "dragon" .
      ?dragon :hasLanguages ?language .
      BIND (COUNT(?language) AS ?langCount)
    }
  }
  OPTIONAL {
    # Average languages for demons
    {
      SELECT (AVG(?langCount) AS ?avgDemons)
      WHERE {
        ?demon a :Beast ;
               :beastCategoryName "demon" .
        ?demon :hasLanguages ?language .
        BIND (COUNT(?language) AS ?langCount)
      }
    }
  }
}

SELECT COUNT(?beast) WHERE {
  ?language a :Language ;
           :hasName "GiantL" .
  ?language :spokenBy ?beast .
  ?beast :hasAlignment ?alignment .
  ?alignment a :Alignment ;
             :hasName "LawfulNeutral" .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?ravenAlignment ?ghoulAlignment WHERE {
  ?raven a :Beast ;
         :hasName ?ravenName ;
         :hasAlignment ?ravenAlignment .
  FILTER(CONTAINS(LCASE(?ravenName), "raven"))

  ?ghoul a :Beast ;
         :hasName ?ghoulName ;
         :hasAlignment ?ghoulAlignment .
  FILTER(CONTAINS(LCASE(?ghoulName), "ghoul"))
}

SELECT (ROUND(?chaoticWolves * 100.0 / ?totalWolves) AS ?percentage)
WHERE {
  # Total wolves
  {
    SELECT (COUNT(?beast) AS ?totalWolves)
    WHERE {
      ?beast a :Beast ;
             :hasName ?name .
      FILTER(CONTAINS(LCASE(?name), "wolf"))
    }
  }
  # Chaotic wolves
  {
    SELECT (COUNT(?beast) AS ?chaoticWolves)
    WHERE {
      ?beast a :Beast ;
             :hasName ?name ;
             :hasAlignment ?alignment .
      FILTER(CONTAINS(LCASE(?name), "wolf"))
      ?alignment a :Alignment .
      FILTER(?alignment IN (:ChaoticEvil, :ChaoticGood, :ChaoticNeutral))
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ( ( ?angelsWithAquanL / ?totalAngels ) * 100 AS ?percentage )
WHERE {
  {
    SELECT ( COUNT(?angel) AS ?totalAngels )
    WHERE {
      ?angel a :Beast ;
             :beastCategoryName "angel" .
    }
  }
  {
    SELECT ( COUNT(?angel) AS ?angelsWithAquanL )
    WHERE {
      ?angel a :Beast ;
             :beastCategoryName "angel" ;
             :hasLanguages ?language .
      ?language a :Language ;
               :hasName "AquanL" .
    }
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?langCount) AS ?averageLanguages)
WHERE {
  SELECT ?beast (COUNT(?language) AS ?langCount)
  WHERE {
    ?beast a :Beast .
    OPTIONAL { ?beast :hasLanguages ?language }
  }
  GROUP BY ?beast
}

SELECT ?beast (COALESCE(?xpValue, "N/A") AS ?xpValue) 
WHERE {
  ?beast a :Beast ;
         :beastCategoryName "golem" ;
         :hasXPValue ?xpValue .
}
ORDER BY DESC(?xpValue)
LIMIT 3

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?entity ?label ?str ?dex ?con ?cha ?atk ?cmb ?cmd ?ac ?cr ?hp ?init ?fort ?ref ?will ?speed ?touch ?flatFooted ?xp WHERE {
  {
    BIND(<http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Abaia> AS ?entity)
    ?entity a :Beast ;
           :hasName ?label .
  }
  UNION
  {
    BIND(<http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Vampire> AS ?entity)
    ?entity a :Beast ;
           :hasName ?label .
  }
  OPTIONAL {
    ?entity :str ?str .
  }
  OPTIONAL {
    ?entity :dex ?dex .
  }
  OPTIONAL {
    ?entity :con ?con .
  }
  OPTIONAL {
    ?entity :cha ?cha .
  }
  OPTIONAL {
    ?entity :atk ?atk .
  }
  OPTIONAL {
    ?entity :cmb ?cmb .
  }
  OPTIONAL {
    ?entity :cmd ?cmd .
  }
  OPTIONAL {
    ?entity :hasACValue ?ac .
  }
  OPTIONAL {
    ?entity :hasCRValue ?cr .
  }
  OPTIONAL {
    ?entity :hasHPValue ?hp .
  }
  OPTIONAL {
    ?entity :hasInitValue ?init .
  }
  OPTIONAL {
    ?entity :hasFortValue ?fort .
  }
  OPTIONAL {
    ?entity :hasRefValue ?ref .
  }
  OPTIONAL {
    ?entity :hasWillValue ?will .
  }
  OPTIONAL {
    ?entity :hasSpeedValue ?speed .
  }
  OPTIONAL {
    ?entity :hasTouchValue ?touch .
  }
  OPTIONAL {
    ?entity :hasFlatFootedValue ?flatFooted .
  }
  OPTIONAL {
    ?entity :hasXPValue ?xp .
  }
} ORDER BY ?label LIMIT 2

SELECT ?creature (SUM(?defensive) / COUNT(?defensive) AS ?avgDefensive)
WHERE {
  ?creature a :Beast .
  ?creature :hasName ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "centaur") || CONTAINS(LCASE(STR(?label)), "medusa"))
  BIND(STR(?creature) AS ?uri)
  OPTIONAL { ?creature :hasACValue ?ac . BIND(?ac AS ?defensive) }
  OPTIONAL { ?creature :hasFortValue ?fort . BIND(?fort AS ?defensive) }
  OPTIONAL { ?creature :hasRefValue ?ref . BIND(?ref AS ?defensive) }
  OPTIONAL { ?creature :hasWillValue ?will . BIND(?will AS ?defensive) }
}
GROUP BY ?creature ?uri

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?acValue) AS ?averageAC)
WHERE {
  ?skeleton a :Beast ;
            :beastCategoryName "skeleton" ;
            :hasACValue ?acValue .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?acValue) AS ?minAC) WHERE {
  ?ogre a :Beast ;
        :beastCategoryName "ogre" ;
        :hasACValue ?acValue .
}

SELECT ?beastLabel ?atk
WHERE {
  ?beast :hasLanguages ?language.
  ?language :hasName "AkloL".
  ?beast :atk ?atk.
  ?beast rdfs:label ?beastLabel.
  {
    SELECT MAX(?atk2) AS ?maxAtk
    WHERE {
      ?beast2 :hasLanguages ?language2.
      ?language2 :hasName "AkloL".
      ?beast2 :atk ?atk2.
    }
  }
  FILTER(?atk = ?maxAtk)
}

SELECT COUNT(*) WHERE {
  ?beast :hasAlignment ?alignment .
  ?alignment :hasName "NeutralEvil" .
  ?beast :cmb ?cmb .
  FILTER(?cmb < 4)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?demon) AS ?count)
WHERE {
  ?demon a :Beast ;
         :beastCategoryName "demon" ;
         :cmd ?cmd .
  {
    SELECT (AVG(?cmdAll) AS ?avgCmd)
    WHERE {
      ?creature a :Beast ;
                :cmd ?cmdAll .
    }
  }
  FILTER (?cmd > ?avgCmd)
}

SELECT AVG(?acValue) AS ?avgACValue
WHERE {
  ?beast a :Beast ;
         beastCategoryName "angel" ;
         hasACValue ?acValue .
}

SELECT ?beast ?refValue WHERE {
  ?beast a :Beast ;
         hasAlignment ?alignment .
  ?alignment a :Alignment ;
             hasName "Chaotic Evil" .
  ?beast hasRefValue ?refValue .
  FILTER(?refValue = (SELECT MAX(?refValue2) WHERE {
    ?beast2 a :Beast ;
           hasAlignment ?alignment2 .
    ?alignment2 a :Alignment ;
                 hasName "Chaotic Evil" .
    ?beast2 hasRefValue ?refValue2 .
  }))
}
GROUP BY ?beast ?refValue

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast ?touchValue WHERE {
  ?beast a :Beast ;
         :beastCategoryName "spider" ;
         :hasTouchValue ?touchValue .
  FILTER (xsd:integer(?touchValue) = 11)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?con) AS ?maxCon) WHERE {
  ?beast a :Beast ;
         :beastCategoryName "elemental" ;
         :con ?con .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(*) AS ?count) WHERE {
  ?beast a :Beast ;
         :beastCategoryName "robot" ;
         :int ?int ;
         :hasSpeedValue ?speed .
  FILTER(?int < 7 && ?speed > 10)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast ?str ?cha WHERE {
  ?beast a :Beast ;
         :beastCategoryName "golem" ;
         :str ?str ;
         :cha ?cha .
  FILTER (?str < ?cha)
}

SELECT AVG(?wis) AS ?averageWisdom
WHERE {
  ?beast :hasAlignment ?alignment .
  ?alignment :hasName "LawfulNeutral" .
  ?beast :wis ?wis .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sumAndrosphinx ?sumBloodQueen
WHERE {
  BIND( (xsd:integer(?androsphinxInt) + xsd:integer(?androsphinxWis)) AS ?sumAndrosphinx )
  {
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Androsphinx> :int ?androsphinxInt ;
                                           :wis ?androsphinxWis .
  }
  BIND( (xsd:integer(?bloodQueenInt) + xsd:integer(?bloodQueenWis)) AS ?sumBloodQueen )
  {
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#BloodQueen> :int ?bloodQueenInt ;
                                                                          :wis ?bloodQueenWis .
  }
}

SELECT MAX(?con) AS ?maxCon
WHERE {
  ?beast a :Beast ;
         :hasName ?name .
  FILTER(CONTAINS(LCASE(?name), "kraken") || CONTAINS(LCASE(?name), "leviathan"))
  ?beast :con ?con .
}

SELECT ?manager (SAMPLE(?managerName) AS ?managerName)
WHERE {
  ?employee rdf:type pv:Employee ;
            pv:memberOf <http://ld.company.org/prod-instances/dept-41622> .
  ?employee pv:hasManager ?manager .
  ?manager pv:name ?managerName .
}
GROUP BY ?manager

SELECT ?product (pv:name(?product) AS ?label)
WHERE {
  <http://ld.company.org/prod-instances/hw-U990-5234138> pv:compatibleProduct ?product .
  ?product pv:name ?label .
}

SELECT ?product ?label ?density WHERE {
  ?product a pv:Product;
          rdfs:label ?label;
          pv:width_mm ?width;
          pv:depth_mm ?depth;
          pv:height_mm ?height;
          pv:weight_g ?weight.
  ?product hasCategory ?category.
  ?category rdfs:label "Coil".
}
ORDER BY DESC(xsd:decimal(?weight) / (xsd:decimal(?width) * xsd:decimal(?depth) * xsd:decimal(?height)))
LIMIT 1

PREFIX creativecommons: <http://creativecommons.org/ns#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX ecc: <https://ns.eccenca.com/>
PREFIX eccdi: <https://vocab.eccenca.com/di/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ns2: <http://purl.org/dc/terms/>
PREFIX ns3: <https://text2sparql.aksw.org/2025/corporate/queries/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX shui: <https://vocab.eccenca.com/shui/>
PREFIX vann: <http://purl.org/vocab/vann/>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX wgs1: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?email ?phone
WHERE {
  ?employee a pv:Employee ;
            pv:name ?name ;
            pv:email ?email ;
            pv:phone ?phone .
  {
    ?employee a pv:Manager .
    FILTER NOT EXISTS {
      ?employee pv:hasDirectReport ?report .
    }
  }
  UNION
  {
    ?employee a pv:Employee .
    FILTER NOT EXISTS {
      ?employee a pv:Manager .
    }
  }
}
ORDER BY ?name

SELECT ?service (rdfs:label(?service) AS ?serviceLabel)
WHERE {
  ?bom a pv:BillOfMaterial .
  ?bom pv:hasBomPart ?bomPart .
  ?bomPart pv:hasPart ?product .
  ?product pv:hasSupplier ?supplier .
  ?supplier pv:country ?country .
  ?country a dbo:Country .
  ?country rdfs:label "Russia" .
  ?service a pv:Service ;
           pv:hasPart ?bomPart .
  OPTIONAL { ?service rdfs:label ?serviceLabel }
}

SELECT AVG(?age) AS ?averageAge WHERE {
  ?treatment :ref-dog ?dog .
  ?dog :age ?age .
}

SELECT ?professional_id ?last_name ?cell_number WHERE {
  {
    ?professional a :professionals ;
                  :state "Indiana" ;
                  :professional_id ?professional_id ;
                  :last_name ?last_name ;
                  :cell_number ?cell_number .
  }
  UNION
  {
    SELECT ?professional_id ?last_name ?cell_number WHERE {
      ?treatment :ref-professional ?professional .
      ?professional a :professionals ;
                    :professional_id ?professional_id ;
                    :last_name ?last_name ;
                    :cell_number ?cell_number .
      GROUP BY ?professional ?professional_id ?last_name ?cell_number
      HAVING (COUNT(?treatment) > 2)
    }
  }
}

SELECT ?id ?last_name ?cell_number
WHERE {
  {
    ?professional professional_id ?id .
    ?professional last_name ?last_name .
    ?professional cell_number ?cell_number .
    ?professional state "Indiana" .
  }
  UNION
  {
    ?treatment ref-professional ?professional .
    ?professional professional_id ?id .
    ?professional last_name ?last_name .
    ?professional cell_number ?cell_number .
    GROUP BY ?professional ?id ?last_name ?cell_number
    HAVING (COUNT(?treatment) > 2)
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?firstName
WHERE {
  {
    ?prof :first_name ?firstName
  }
  UNION
  {
    ?owner :first_name ?firstName
  }
  FILTER NOT EXISTS {
    ?dog :name ?firstName
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?firstName
WHERE {
  {
    ?prof :first_name ?firstName .
    ?prof a :professionals .
  }
  UNION
  {
    ?owner :first_name ?firstName .
    ?owner a :owners .
  }
  FILTER NOT EXISTS {
    ?dog :name ?firstName .
    ?dog a :dogs .
  }
}

SELECT ?owner ?owner_id ?first_name ?last_name
WHERE {
  {
    SELECT ?owner (COUNT(?dog) AS ?dogCount)
    WHERE {
      ?dog :ref-owner ?owner .
    }
    GROUP BY ?owner
    ORDER BY DESC(?dogCount)
    LIMIT 1
  }
  ?owner :owner_id ?owner_id .
  ?owner :first_name ?first_name .
  ?owner :last_name ?last_name .
}
GROUP BY ?owner ?owner_id ?first_name ?last_name

SELECT ?breedName
WHERE {
  {
    SELECT ?breedCode
    WHERE {
      SELECT ?breedCode (COUNT(?dog) AS ?count)
      WHERE {
        ?dog a :dogs ;
             :breed_code ?breedCode .
      }
      GROUP BY ?breedCode
      ORDER BY DESC(?count)
      LIMIT 1
    }
  }
  ?breed a :breeds ;
         :breed_code ?breedCode .
  ?breed :breed_name ?breedName .
}
GROUP BY ?breedCode ?breedName

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?treatment ?cost ?description
WHERE {
  ?treatment a :treatments ;
             :cost_of_treatment ?cost ;
             :ref-treatment_type_code ?treatmentType .
  ?treatmentType a :treatment_types ;
                 :treatment_type_description ?description .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?dogName ?treatmentDate
WHERE {
  ?dog a :dogs ;
       :breed_code "HUS" ;
       :name ?dogName .
  ?treatment :ref-dog ?dog ;
             :date_of_treatment ?treatmentDate .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?ownerFirstName ?dogName
WHERE {
  ?owner a :owners ;
         :state ?state ;
         :first_name ?ownerFirstName .
  ?dog a :dogs ;
       :name ?dogName ;
       :ref-owner ?owner .
  FILTER(CONTAINS(LCASE(STR(?state)), "virginia"))
}

SELECT ?ownerLastname
WHERE {
  {
    SELECT ?minAge
    WHERE {
      ?dog :age ?age.
      MIN(?age) AS ?minAge
    }
  }
  ?dog :age ?minAge.
  ?dog :ref-owner ?owner.
  ?owner :last_name ?ownerLastname.
}
GROUP BY ?ownerLastname

