SELECT ?role_code ?street ?city ?state
WHERE {
  ?professional a :professionals ;
                :role_code ?role_code ;
                :street ?street ;
                :city ?city ;
                :state ?state .
  FILTER(CONTAINS(LCASE(STR(?city)), "west"))
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?dog) AS ?countBelowAvg) WHERE {
  ?dog :age ?age .
  {
    SELECT (AVG(?age2) AS ?avgAge) WHERE { ?dog2 :age ?age2 }
  }
  FILTER(?age < ?avgAge)
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?dog) AS ?count)
WHERE {
  {
    SELECT (AVG(?age) AS ?avgAge)
    WHERE {
      ?dog a :dogs ;
           :age ?age .
    }
  }
  ?dog a :dogs ;
       :age ?age .
  FILTER(?age < ?avgAge)
}

SELECT COUNT(*) WHERE {
  ?dog a :dogs .
  MINUS {
    ?treatment :ref-dog ?dog .
  }
}

SELECT COUNT(*) WHERE {
  ?dog a :dogs .
  NOT EXISTS {
    ?treatment :ref-dog ?dog .
  }
}

SELECT COUNT(*) AS ?count
WHERE {
  ?owner a :owners .
  FILTER NOT EXISTS {
    ?dog a :dogs ;
         :ref-owner ?owner .
  }
}

SELECT COUNT(*) AS total
WHERE {
  ?owner a :owners .
  NOT EXISTS {
    ?dog :ref-owner ?owner .
  }
}

SELECT COUNT(*) AS ?count WHERE {
  ?professional a :professionals .
  FILTER NOT EXISTS {
    ?treatment :ref-professional ?professional .
  }
}

SELECT COUNT(*) AS count
WHERE {
  VALUES ?professional { ?prof }
  FILTER ( EXISTS { ?prof a :professionals } )
  FILTER ( NOT EXISTS { ?treatment :ref-professional ?professional } )
}

