SELECT ?student ?firstName ?middleName ?lastName
WHERE {
  ?degreeProgram a :degree_programs ;
                 :degree_summary_name "Bachelor" .
  ?enrolment :ref-degree_program ?degreeProgram ;
             :ref-student ?student .
  ?student :first_name ?firstName ;
           :middle_name ?middleName ;
           :last_name ?lastName .
}

SELECT ?semesterName
WHERE {
  ?semester a :semesters .
  ?semester :semester_name ?semesterName .
  NOT EXISTS {
    ?studentEnrolment :ref-semester ?semester .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
