PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?lastName
WHERE {
  {
    ?student :ref-current_address ?currentAddr .
    ?currentAddr :state_province_county ?state .
    FILTER(CONTAINS(LCASE(STR(?state)), "north carolina"))
  }
  UNION
  {
    ?student :ref-permanent_address ?permanentAddr .
    ?permanentAddr :state_province_county ?state .
    FILTER(CONTAINS(LCASE(STR(?state)), "north carolina"))
  }
  FILTER NOT EXISTS {
    ?enrolment :ref-student ?student .
  }
  ?student :last_name ?lastName .
}

