PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?addressId ?line1 ?line2 ?state ?zip
WHERE {
  {
    SELECT ?address ?addressId ?line1 ?line2 ?state ?zip
           (COUNT(?student) AS ?count)
    WHERE {
      ?student a :students ;
               :ref-current_address ?address .
      ?address :address_id ?addressId ;
               :line_1 ?line1 ;
               :line_2 ?line2 ;
               :state_province_county ?state ;
               :zip_postcode ?zip .
    }
    GROUP BY ?address ?addressId ?line1 ?line2 ?state ?zip
    ORDER BY DESC(?count)
    LIMIT 1
  }
}

SELECT ?address_id ?line1 ?line2
WHERE {
  {
    SELECT ?address (COUNT(?student) AS ?studentCount)
    WHERE {
      {
        ?student :ref-current_address ?address .
      }
      UNION
      {
        ?student :ref-permanent_address ?address .
      }
    }
    GROUP BY ?address
    ORDER BY DESC(?studentCount)
    LIMIT 1
  }
  ?address :address_id ?address_id .
  ?address :line_1 ?line1 .
  ?address :line_2 ?line2 .
}

SELECT ?semesterName WHERE {
  ?semester :semester_name ?semesterName .
  ?enrolment :ref-semester ?semester .
  ?enrolment :ref-degree_program ?degree_program .
  ?degree_program :degree_summary_name ?name .
  FILTER(CONTAINS(LCASE(?name), "master")) .
  EXISTS {
    ?enrolment2 :ref-semester ?semester .
    ?enrolment2 :ref-degree_program ?degree_program2 .
    ?degree_program2 :degree_summary_name ?name2 .
    FILTER(CONTAINS(LCASE(?name2), "bachelor"))
  }
}

SELECT ?semester_id
WHERE {
  ?semester :semester_id ?semester_id.
  EXISTS {
    ?enrolment :ref-semester ?semester.
    ?enrolment :ref-degree_program ?degree_program.
    ?degree_program :degree_summary_name "Master".
  }
  EXISTS {
    ?enrolment :ref-semester ?semester.
    ?enrolment :ref-degree_program ?degree_program.
    ?degree_program :degree_summary_name "Bachelor".
  }
}

