SELECT ?section ?course_id ?section_id ?section_name ?section_description ?ref_course  
WHERE {  
  ?section a :sections ;  
           :section_name "h" ;  
           :course_id ?course_id ;  
           :section_id ?section_id ;  
           :section_name ?section_name ;  
           :section_description ?section_description ;  
           :ref-course ?ref_course .  
  ?ref_course a :courses ;  
             :course_id ?course_id .  
}  
ORDER BY ?section_id

