WHERE {
  ?country a :country ;
           :indepyear ?indepyear .
  FILTER(?indepyear < 1930)
  ?languageLang a :countrylanguage ;
                :ref-countrycode ?country ;
                :isofficial "T" ;
                :language ?language .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?language) AS ?total) WHERE {
  ?country a :country ;
           :indepyear ?indepYear .
  FILTER(?indepYear < 1930)
  ?countrylanguage a :countrylanguage ;
                   :ref-countrycode ?country ;
                   :isofficial "Yes" ;
                   :language ?language .
}

SELECT ?countryName
WHERE {
  ?country a :country ;
           :surfacearea ?surfaceArea .
  ?country :name ?countryName .
  FILTER(?surfaceArea > (SELECT MAX(?maxSurface) WHERE {
    ?country2 a :country ;
              :continent "Europe" ;
              :surfacearea ?maxSurface
  }))
}

SELECT ?country ?name
WHERE {
  ?country a :country ;
           :surfacearea ?surfaceArea .
  ?country :name ?name .
  FILTER(?surfaceArea > (
    SELECT MAX(?europeSurfaceArea)
    WHERE {
      ?europeCountry a :country ;
                     :continent "Europe" ;
                     :surfacearea ?europeSurfaceArea .
    }
  ))
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?africanCountryLabel WHERE {
  ?africanCountry a :country ;
                  :continent "Africa" ;
                  :population ?popAfrican .
  {
    SELECT (MIN(?popAsia) AS ?minAsiaPop) WHERE {
      ?asiaCountry a :country ;
                   :continent "Asia" ;
                   :population ?popAsia .
    }
  }
  FILTER (?popAfrican < ?minAsiaPop)
  ?africanCountry :name ?africanCountryLabel .
}
GROUP BY ?africanCountryLabel

SELECT ?africanCountry (xsd:integer(?popAfrican) AS ?population)
WHERE {
  ?africanCountry a :country ;
                  :region "Africa" ;
                  :population ?popAfrican .
  NOT EXISTS {
    ?asiaCountry a :country ;
                 :region "Asia" ;
                 :population ?popAsia .
    FILTER (?popAfrican >= ?popAsia)
  }
}

SELECT ?country ?name ?population
WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :population ?population ;
           :name ?name .
  {
    SELECT MAX(?afPop)
    WHERE {
      ?afCountry a :country ;
                 :continent "Africa" ;
                 :population ?afPop .
    }
  }
  FILTER(?population > ?maxAfPop)
}

SELECT ?country ?population
WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :population ?population .
  {
    SELECT (MAX(?africanPop) AS ?maxAfricanPop)
    WHERE {
      ?africanCountry a :country ;
                      :continent "Africa" ;
                      :population ?africanPop .
    }
  }
  BIND( ?maxAfricanPop AS ?maxAfricanPop )
  FILTER(?population > ?maxAfricanPop)
}

PREFIX : <http://valuenet/ontop/>
