SELECT ?continent (AVG(?lifeExpectancy) AS ?avgLifeExpectancy) (SUM(?population) AS ?totalPopulation)
WHERE {
  ?country a :country ;
           :continent ?continent ;
           :lifeexpectancy ?lifeExpectancy ;
           :population ?population .
}
GROUP BY ?continent
HAVING (AVG(?lifeExpectancy) < 72)

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?population) AS ?totalPopulation) (AVG(?surfacearea) AS ?averageArea)
WHERE {
  ?country a :country ;
           :continent "North America" ;
           :surfacearea ?surfacearea ;
           :population ?population .
  FILTER (?surfacearea > 3000)
}

SELECT (SUM(?population) AS totalPopulation) (AVG(?surfacearea) AS avgSurfaceArea)
WHERE {
  ?country a :country ;
           :region "North America" ;
           :surfacearea ?surfacearea ;
           :population ?population .
  FILTER(?surfacearea > 3000)
}

SELECT ?countryCode ?language ?percentage
WHERE {
  ?countrylanguage :ref-countrycode ?country .
  ?country :code ?countryCode .
  ?countrylanguage :language ?language .
  ?countrylanguage :percentage ?percentage .
  {
    SELECT ?countryCode (MAX(?percentage) AS maxPercentage)
    WHERE {
      ?countrylanguage :ref-countrycode ?country .
      ?country :code ?countryCode .
      ?countrylanguage :percentage ?percentage .
    }
    GROUP BY ?countryCode
  }
  FILTER(?percentage = maxPercentage)
}

SELECT COUNT(DISTINCT ?countrycode)
WHERE {
  ?countrylanguage :language "Spanish" ;
                   :ref-countrycode ?countrycode ;
                   :percentage ?percentage .

  {
    SELECT MAX(?p) AS ?maxPercentage
    WHERE {
      ?cl :language "Spanish" ;
          :percentage ?p .
    }
  }
  FILTER(?percentage = ?maxPercentage)
}

