SELECT ?countrycode
WHERE {
  ?cl a :countrylanguage ;
      :language "Spanish" ;
      :countrycode ?countrycode ;
      :percentage ?percentage .
}
ORDER BY DESC(?percentage)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countrycode
WHERE {
  ?countrylanguage :language "Spanish" ;
                   :isofficial "T" ;
                   :countrycode ?countrycode .
}

SELECT ?beast ( :hasName(?beast) AS ?label )
WHERE {
  ?beast rdf:type :Beast .
  ?beast :hasAlignment :ChaoticGood .
  ?beast :hasLanguages ?language .
  FILTER NOT EXISTS {
    ?beast :hasLanguages :DraconicL .
  }
  ?beast :hasName ?label .
}

SELECT COUNT(?beast)
WHERE {
  ?language a :Language ;
           :hasName "TreantL" .
  ?beast :hasLanguages ?language .
  ?beast :hasAlignment ?alignment .
  ?alignment :hasName ?alignmentName .
  FILTER (LCASE(?alignmentName) != "TrueNeutral")
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?count1 ?count2 WHERE {
  {
    SELECT (COUNT(DISTINCT ?beast) AS ?count1) {
      ?beast :hasLanguages ?lang1 .
      ?lang1 :hasName "AbyssalL" .
      ?beast :hasLanguages ?lang2 .
      ?lang2 :hasName "AkloL" .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?beast) AS ?count2) {
      ?beast :hasLanguages ?lang3 .
      ?lang3 :hasName "InfernalL" .
      ?beast :hasLanguages ?lang4 .
      ?lang4 :hasName "TerranL" .
    }
  }
}

SELECT (ROUND(?countBoth * 100.0 / ?total) AS ?percentage)
WHERE {
  {
    SELECT (COUNT(*) AS ?total)
    WHERE {
      ?dragon a :Beast ;
              :beastCategoryName "dragon" .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?dragon) AS ?countBoth)
    WHERE {
      ?dragon a :Beast ;
              :beastCategoryName "dragon" .
      ?dragon :hasLanguages ?langDraconic .
      ?langDraconic a :Language ;
                   :hasName "DraconicL" .
      ?dragon :hasLanguages ?langCommon .
      ?langCommon a :Language ;
                  :hasName "CommonL" .
    }
  }
}

SELECT ?avgDragonLanguages ?avgDemonLanguages
WHERE {
  # Calculate average languages for dragons
  SELECT (AVG(?numLanguages) AS ?avgDragonLanguages)
  WHERE {
    SELECT ?dragon (COUNT(?language) AS ?numLanguages)
    WHERE {
      ?dragon a :Beast ;
              :beastCategoryName "dragon" .
      ?dragon :hasLanguages ?language .
    }
    GROUP BY ?dragon
  }

  # Calculate average languages for demons
  SELECT (AVG(?numLanguages) AS ?avgDemonLanguages)
  WHERE {
    SELECT ?demon (COUNT(?language) AS ?numLanguages)
    WHERE {
      ?demon a :Beast ;
              :beastCategoryName "demon" .
      ?demon :hasLanguages ?language .
    }
    GROUP BY ?demon
  }
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?beast) AS ?count)
WHERE {
    ?lang a :Language ;
          :hasName "GiantL" .
    ?align a :Alignment ;
           :hasName "LawfulNeutral" .
    ?beast a :Beast ;
           :hasAlignment ?align ;
           :hasLanguages ?lang .
}

SELECT (
  ( ( ?angelsWithAquanL * 100.0 ) / ?totalAngels ) AS ?percentage
)
WHERE {
  { SELECT (COUNT(DISTINCT ?angel) AS ?totalAngels)
    WHERE {
      ?angel a :Beast ;
             beastCategoryName "angel" .
    }
  }
  { SELECT (COUNT(DISTINCT ?angel) AS ?angelsWithAquanL)
    WHERE {
      ?angel a :Beast ;
             beastCategoryName "angel" ;
             hasLanguages ?language .
      ?language a :Language ;
                hasName "AquanL" .
    }
  }
}

SELECT (COUNT(?language) DIV COUNT(?beast)) AS ?average
WHERE {
  ?beast a :Beast .
  ?beast :hasLanguages ?language .
}

SELECT ?sangudaemonSpeed ?erodaemonSpeed
WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Sangudaemon> :hasSpeedValue ?sangudaemonSpeed .
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Erodaemon> :hasSpeedValue ?erodaemonSpeed .
}
FILTER(?sangudaemonSpeed > ?erodaemonSpeed)

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?speedValue) AS ?meanSpeed)
WHERE {
  ?beast a :Beast ;
         :beastCategoryName "spider" ;
         :hasSpeedValue ?speedValue .
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?xp
WHERE {
  ?beast a :Beast ;
         :beastCategoryName "golem" ;
         :hasName ?name ;
         :hasXPValue ?xp .
}
ORDER BY DESC(?xp)
LIMIT 3

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?boggard ?selkie (COUNT(?boggard) AS ?boggardCount) (COUNT(?selkie) AS ?selkieCount)
WHERE {
  ?boggard a :Beast ;
           :hasName "Boggard" .
  ?selkie a :Beast ;
          :hasName "Selkie" .
  OPTIONAL { ?boggard :hasACValue ?acBoggard }
  OPTIONAL { ?boggard :hasFortValue ?fortBoggard }
  OPTIONAL { ?boggard :hasRefValue ?refBoggard }
  OPTIONAL { ?boggard :hasWillValue ?willBoggard }
  OPTIONAL { ?selkie :hasACValue ?acSelkie }
  OPTIONAL { ?selkie :hasFortValue ?fortSelkie }
  OPTIONAL { ?selkie :hasRefValue ?refSelkie }
  OPTIONAL { ?selkie :hasWillValue ?willSelkie }
}
GROUP BY ?boggard ?selkie
HAVING (COUNT(?boggard) > 0 && COUNT(?selkie) > 0)

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beast ?totalSum
WHERE {
  ?beast a :Beast .
  OPTIONAL { ?beast :atk ?atk }
  OPTIONAL { ?beast :cha ?cha }
  OPTIONAL { ?beast :cmb ?cmb }
  OPTIONAL { ?beast :cmd ?cmd }
  OPTIONAL { ?beast :con ?con }
  OPTIONAL { ?beast :dex ?dex }
  OPTIONAL { ?beast :hasACValue ?hasACValue }
  OPTIONAL { ?beast :hasCRValue ?hasCRValue }
  OPTIONAL { ?beast :hasFlatFootedValue ?hasFlatFootedValue }
  OPTIONAL { ?beast :hasFortValue ?hasFortValue }
  OPTIONAL { ?beast :hasHPValue ?hasHPValue }
  OPTIONAL { ?beast :hasInitValue ?hasInitValue }
  OPTIONAL { ?None ?hasLevel ?hasLevel }
  OPTIONAL { ?beast :hasRefValue ?hasRefValue }
  OPTIONAL { ?beast :hasSpeedValue ?hasSpeedValue }
  OPTIONAL { ?beast :hasTouchValue ?hasTouchValue }
  OPTIONAL { ?beast :hasWillValue ?hasWillValue }
  OPTIONAL { ?beast :hasXPValue ?hasXPValue }
  OPTIONAL { ?beast :int ?int }
  OPTIONAL { ?beast :str ?str }
  OPTIONAL { ?beast :wis ?wis }
  BIND( COALESCE(?atk, 0) + COALESCE(?cha, 0) + COALESCE(?cmb, 0) + COALESCE(?cmd, 0) + COALESCE(?con, 0) + COALESCE(?dex, 0) + COALESCE(?hasACValue, 0) + COALESCE(?hasCRValue, 0) + COALESCE(?hasFlatFootedValue, 0) + COALESCE(?hasFortValue, 0) + COALESCE(?hasHPValue, 0) + COALESCE(?hasInitValue, 0) + COALESCE(?hasLevel, 0) + COALESCE(?hasRefValue, 0) + COALESCE(?hasSpeedValue, 0) + COALESCE(?hasTouchValue, 0) + COALESCE(?hasWillValue, 0) + COALESCE(?hasXPValue, 0) + COALESCE(?int, 0) + COALESCE(?str, 0) + COALESCE(?wis, 0) AS ?totalSum )
  FILTER(?beast = <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Biclops> || ?beast = <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Mastodon>)
}

SELECT ?lowestStats
WHERE {
  ?beast a :Beast ;
         :hasName "wolf" ;
         :statistics ?stats .
  BIND( MIN(xsd:integer(?stats)) AS ?lowestStats )
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?acValue) AS ?averageAC)
WHERE {
  ?skeleton a :Beast ;
           :beastCategoryName "skeleton" ;
           :hasACValue ?acValue .
}

SELECT ?beast ?beastLabel
WHERE {
  ?beast :hasLanguages ?language.
  ?language :hasName "AkloL".
  ?beast :atk ?atkValue.
  {
    SELECT MAX(?atk) AS ?maxAtk
    WHERE {
      ?beast2 :hasLanguages ?language2.
      ?language2 :hasName "AkloL".
      ?beast2 :atk ?atk.
    }
  }
  FILTER(?atkValue = ?maxAtk)
  ?beast :hasName ?beastLabel.
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?atk) AS ?averageAttack)
WHERE {
  ?beast a :Beast ;
         :beastCategoryName "robot" ;
         :atk ?atk .
}

SELECT (COUNT(?demon) AS ?count) {
  {
    SELECT (AVG(?cmd2) AS ?avgCmd) {
      ?beast2 a :Beast ;
             :cmd ?cmd2 .
    }
  }
  ?demon a :Beast ;
         :beastCategoryName "demon" ;
         :cmd ?cmd .
  FILTER(?cmd > ?avgCmd)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(?hpValue) AS ?minHP) WHERE {
  ?beast a :Beast ;
         :str ?str ;
         :hasHPValue ?hpValue .
  FILTER(?str > 10)
}

SELECT COUNT(*) WHERE {
  ?lang a :Language ;
        :hasName "HalflingL" .
  ?beast :hasLanguages ?lang .
  ?beast :hasRefValue ?refVal .
  ?beast :atk ?atkVal .
  FILTER(?refVal > 10 && ?atkVal < 15)
}

SELECT ?beast
WHERE {
  ?beast a :Beast ;
         :hasAlignment :ChaoticEvil .
  ?beast :hasRefValue ?refValue .
  {
    SELECT MAX(?refValue) AS ?maxRef
    WHERE {
      ?beast2 a :Beast ;
              :hasAlignment :ChaoticEvil .
      ?beast2 :hasRefValue ?refValue2 .
    }
  }
  FILTER(?refValue = ?maxRef)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?beastName WHERE {
  ?beast a :Beast ;
         :beastCategoryName "spider" ;
         :hasTouchValue "11"^^xsd:nonNegativeInteger .
  ?beast :hasName ?beastName .
}

SELECT COUNT(?beast) WHERE {
  ?lang a :Language ;
        :hasName "ProteanL" .
  ?beast :hasLanguages ?lang .
  ?beast :con ?con .
  FILTER(?con > 10)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MAX(?con) AS ?maxCon) WHERE {
  ?beast a :Beast ;
         :beastCategoryName "elemental" ;
         :con ?con .
}

SELECT ?beast
WHERE {
  ?beast a :Beast ;
         :hasLanguages :AbolethL .
  ?beast :dex ?dex .
  { SELECT (AVG(?dex2) AS ?avgDex)
    WHERE {
      ?beast2 a :Beast .
      ?beast2 :dex ?dex2 .
    }
  }
  FILTER(?dex > ?avgDex)
}

SELECT ?creature ?totalStat WHERE {
  {
    ?creature = <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Baalzebul> .
    OPTIONAL { ?creature :cha ?cha . BIND(?cha AS ?statValue) }
    OPTIONAL { ?creature :con ?con . BIND(?con AS ?statValue) }
    OPTIONAL { ?creature :dex ?dex . BIND(?dex AS ?statValue) }
    OPTIONAL { ?creature :str ?str . BIND(?str AS ?statValue) }
    OPTIONAL { ?creature :wis ?wis . BIND(?wis AS ?statValue) }
    OPTIONAL { ?creature :int ?int . BIND(?int AS ?statValue) }
    OPTIONAL { ?creature :atk ?atk . BIND(?atk AS ?statValue) }
    OPTIONAL { ?creature :hasACValue ?hasACValue . BIND(?hasACValue AS ?statValue) }
    OPTIONAL { ?creature :hasCRValue ?hasCRValue . BIND(?hasCRValue AS ?statValue) }
    OPTIONAL { ?creature :hasFlatFootedValue ?hasFlatFootedValue . BIND(?hasFlatFootedValue AS ?statValue) }
    OPTIONAL { ?creature :hasFortValue ?hasFortValue . BIND(?hasFortValue AS ?statValue) }
    OPTIONAL { ?creature :hasHPValue ?hasHPValue . BIND(?hasHPValue AS ?statValue) }
    OPTIONAL { ?creature :hasInitValue ?hasInitValue . BIND(?hasInitValue AS ?statValue) }
    OPTIONAL { ?creature :hasLevel ?hasLevel . BIND(?hasLevel AS ?statValue) }
    OPTIONAL { ?creature :hasRefValue ?hasRefValue . BIND(?hasRefValue AS ?statValue) }
    OPTIONAL { ?creature :hasSpeedValue ?hasSpeedValue . BIND(?hasSpeedValue AS ?statValue) }
    OPTIONAL { ?creature :hasTouchValue ?hasTouchValue . BIND(?hasTouchValue AS ?statValue) }
    OPTIONAL { ?creature :hasWillValue ?hasWillValue . BIND(?hasWillValue AS ?statValue) }
    OPTIONAL { ?creature :hasXPValue ?hasXPValue . BIND(?hasXPValue AS ?statValue) }
    BIND( SUM(?statValue) AS ?totalStat )
  }
  UNION
  {
    ?creature = <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Dagon> .
    OPTIONAL { ?creature :cha ?cha . BIND(?cha AS ?statValue) }
    OPTIONAL { ?creature :con ?con . BIND(?con AS ?statValue) }
    OPTIONAL { ?creature :dex ?dex . BIND(?dex AS ?statValue) }
    OPTIONAL { ?creature :str ?str . BIND(?str AS ?statValue) }
    OPTIONAL { ?creature :wis ?wis . BIND(?wis AS ?statValue) }
    OPTIONAL { ?creature :int ?int . BIND(?int AS ?statValue) }
    OPTIONAL { ?creature :atk ?atk . BIND(?atk AS ?statValue) }
    OPTIONAL { ?creature :hasACValue ?hasACValue . BIND(?hasACValue AS ?statValue) }
    OPTIONAL { ?creature :hasCRValue ?hasCRValue . BIND(?hasCRValue AS ?statValue) }
    OPTIONAL { ?creature :hasFlatFootedValue ?hasFlatFootedValue . BIND(?hasFlatFootedValue AS ?statValue) }
    OPTIONAL { ?creature :hasFortValue ?hasFortValue . BIND(?hasFortValue AS ?statValue) }
    OPTIONAL { ?creature :hasHPValue ?hasHPValue . BIND(?hasHPValue AS ?statValue) }
    OPTIONAL { ?creature :hasInitValue ?hasInitValue . BIND(?hasInitValue AS ?statValue) }
    OPTIONAL { ?creature :hasLevel ?hasLevel . BIND(?hasLevel AS ?statValue) }
    OPTIONAL { ?creature :hasRefValue ?hasRefValue . BIND(?hasRefValue AS ?statValue) }
    OPTIONAL { ?creature :hasSpeedValue ?hasSpeedValue . BIND(?hasSpeedValue AS ?statValue) }
    OPTIONAL { ?creature :hasTouchValue ?hasTouchValue . BIND(?hasTouchValue AS ?statValue) }
    OPTIONAL { ?creature :hasWillValue ?hasWillValue . BIND(?hasWillValue AS ?statValue) }
    OPTIONAL { ?creature :hasXPValue ?hasXPValue . BIND(?hasXPValue AS ?statValue) }
    BIND( SUM(?statValue) AS ?totalStat )
  }
} ORDER BY DESC(?totalStat)

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?countPolyglot ?countSkald WHERE {
  { SELECT (COUNT(?beast) AS ?countPolyglot) WHERE { ?beast :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#PolyglotL> } }
  { SELECT (COUNT(?beast) AS ?countSkald) WHERE { ?beast :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#SkaldL> } }
}

SELECT ?department (pv:name as ?deptName) WHERE {
  ?employee rdf:type pv:Employee ;
            pv:name ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "Ms. Brant"))
  ?employee pv:memberOf ?department .
  ?department pv:name ?deptName .
}

SELECT ?expert (rdfs:label(?expert) AS ?expertLabel)
WHERE {
  ?expert a pv:Employee ;
          pv:areaOfExpertise prodi:prod-cat-Sensor .
  ?expert rdfs:label ?expertLabel .
}

SELECT ?manager (SAMPLE(?name) AS ?name)
WHERE {
  ?dept a pv:Department ;
        rdfs:label "Data Services" .
  ?manager a pv:Manager ;
           pv:memberOf ?dept .
  ?manager pv:name ?name .
}
GROUP BY ?manager

SELECT ?name WHERE {
  ?person a pv:Employee ;
          memberOf <http://ld.company.org/prod-instances/dept-85880> ;
          areaOfExpertise <http://ld.company.org/prod-instances/prod-cat-Network> .
  ?person rdfs:label ?name .
}

SELECT ?supplier (rdfs:label(?supplier) AS ?supplierLabel)
WHERE {
  ?supplier a pv:Supplier ;
            pv:country ?country .
  ?country rdfs:label ?countryLabel .
  FILTER(CONTAINS(LCASE(?countryLabel), "toulouse"))
}

SELECT ?product (rdfs:label(?product) AS ?label) WHERE {
  <http://ld.company.org/prod-instances/hw-U990-5234138> pv:compatibleProduct ?product .
}

SELECT ?city
WHERE {
  ?hardware a pv:Hardware ;
            hasCategory ?category .
  ?category rdfs:label "LCD" .
  ?hardware pv:hasSupplier ?supplier .
  ?supplier pv:country ?country .
  ?country pv:name ?countryName .
  FILTER(CONTAINS(LCASE(?countryName), "United States"))
}

SELECT ?employee ?name ?email ?phone
WHERE {
  {
    ?employee a pv:Employee .
    NOT EXISTS { ?employee a pv:Manager }
  }
  UNION
  {
    ?employee a pv:Manager .
    NOT EXISTS { ?employee pv:hasDirectReport ?directReport }
  }
  OPTIONAL { ?employee pv:name ?name }
  OPTIONAL { ?employee pv:email ?email }
  OPTIONAL { ?employee pv:phone ?phone }
}
ORDER BY ?name

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professional_id ?last_name ?cell_number
WHERE {
  ?professional a :professionals ;
                :professional_id ?professional_id ;
                :last_name ?last_name ;
                :cell_number ?cell_number ;
                :state ?state .
  OPTIONAL {
    ?treatment :ref-professional ?professional .
  }
}
GROUP BY ?professional_id ?last_name ?cell_number ?state
HAVING ( LCASE(?state) = "indiana" || (COUNT(?treatment) > 2) )

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?firstName
WHERE {
  {
    ?professional a :professionals ;
                  :first_name ?firstName .
  }
  UNION
  {
    ?owner a :owners ;
           :first_name ?firstName .
  }
  FILTER NOT EXISTS {
    ?dog a :dogs ;
         :name ?firstName .
  }
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?firstName
WHERE {
  {
    ?prof rdf:type :professionals ;
          :first_name ?firstName .
  }
  UNION
  {
    ?own rdf:type :owners ;
         :first_name ?firstName .
  }
  FILTER NOT EXISTS {
    ?dog rdf:type :dogs ;
         :name ?firstName .
  }
}

SELECT ?owner ?owner_id ?zip_code WHERE {
  ?owner a :owners .
  ?owner owner_id ?owner_id .
  ?owner zip_code ?zip_code .
  {
    SELECT ?owner (SUM(?cost) AS ?totalCost) WHERE {
      ?treatment :ref-dog ?dog .
      ?dog :ref-owner ?owner .
      ?treatment :cost_of_treatment ?cost .
    } GROUP BY ?owner ORDER BY DESC(?totalCost) LIMIT 1
  }
} GROUP BY ?owner ?owner_id ?zip_code

SELECT ?firstName ?lastName
WHERE {
  # Calculate the average cost
  {
    SELECT (AVG(?cost) AS ?avgCost)
    WHERE {
      ?treatment :cost_of_treatment ?cost.
    }
  }
  # Find treatments below average
  ?treatment :ref-professional ?professional .
  ?treatment :cost_of_treatment ?cost .
  FILTER(?cost < ?avgCost)
  # Get the professional's name
  ?professional :first_name ?firstName .
  ?professional :last_name ?lastName .
}

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?treatment ?cost ?description
WHERE {
  ?treatment a :treatments ;
             :cost_of_treatment ?cost ;
             :ref-treatment_type_code ?treatmentType .
  ?treatmentType a :treatment_types ;
                 :treatment_type_description ?description .
}

SELECT ?dogName ?treatmentDate
WHERE {
  {
    SELECT ?breedCode
    WHERE {
      ?dog :breed_code ?breedCode.
    }
    GROUP BY ?breedCode
    ORDER BY COUNT(*) ASC
    LIMIT 1
  }
  ?dog :breed_code ?breedCode.
  ?dog :name ?dogName.
  ?treatment :ref-dog ?dog.
  ?treatment :date_of_treatment ?treatmentDate.
}

SELECT ?dog ?name ?treatmentDate
WHERE {
  ?dog a :dogs;
       :ref-breed_code ?breedCode;
       :name ?name.
  ?treatment :ref-dog ?dog;
             :date_of_treatment ?treatmentDate.
  ?breedCode a :breeds.
  {
    SELECT ?breedCode
    WHERE {
      ?dog a :dogs;
           :ref-breed_code ?breedCode.
    }
    GROUP BY ?breedCode
    ORDER BY COUNT(?dog)
    LIMIT 1
  }
}
GROUP BY ?dog ?name ?treatmentDate

SELECT ?ownerLastname
WHERE {
  {
    SELECT ?minAge
    WHERE {
      ?dog :age ?age .
      MIN(?age) AS ?minAge
    }
  }
  ?dog :age ?minAge .
  ?dog :ref-owner ?owner .
  ?owner :last_name ?ownerLastname .
}
GROUP BY ?ownerLastname

