SELECT (COUNT(?dog) AS ?count) WHERE {
  ?dog a :dogs .
  ?dog :age ?age .
  FILTER(?age < (SELECT (AVG(?age2) AS ?avgAge) WHERE { ?dog2 a :dogs. ?dog2 :age ?age2. }))
}

SELECT COUNT(?dog)
WHERE {
  ?dog :age ?age .
  { SELECT (AVG(?age) AS ?avgAge) WHERE { ?dog2 :age ?age2 } }
  FILTER(?age < ?avgAge)
}

SELECT ?cost WHERE {
  ?treatment :date_of_treatment ?date .
  ?treatment :cost_of_treatment ?cost .
  ORDER BY DESC(?date)
  LIMIT 1
}

