  ?dog a :dogs .
  ?dog :dog_id ?dog_id .
  FILTER NOT EXISTS {
    ?treatment :dog_id ?dog_id .
  }
}

SELECT COUNT(?owner) AS ?count WHERE { 
  ?owner a :owners . 
