SELECT ?degree_program_id ?degree_summary_name
WHERE {
  {
    SELECT ?degree_program
    WHERE {
      ?enrolment a :student_enrolment .
      ?enrolment :ref-degree_program ?degree_program .
    }
    GROUP BY ?degree_program
    ORDER BY DESC(COUNT(?enrolment))
    LIMIT 1
  }
  ?degree_program a :degree_programs .
  ?degree_program :degree_program_id ?degree_program_id .
  ?degree_program :degree_summary_name ?degree_summary_name .
}

SELECT ?lastName
WHERE {
  ?student a :students .
  ?student :current_address_id ?currentAddressId .
  ?address :address_id ?currentAddressId .
  ?address :state_province_county "North Carolina" .
  ?student :last_name ?lastName .
  NOT EXISTS {
    ?student_enrolment :ref-student ?student .
  }
}

SELECT DISTINCT ?lastName
WHERE {
  ?student a :students ;
           :ref-current_address ?currentAddr ;
           :ref-permanent_address ?permanentAddr .

  {
    ?student :ref-current_address ?currentAddr .
    ?currentAddr :state_province_county ?state .
    FILTER(CONTAINS(LCASE(?state), "north carolina"))
  }
  UNION
  {
    ?student :ref-permanent_address ?permanentAddr .
    ?permanentAddr :state_province_county ?state .
    FILTER(CONTAINS(LCASE(?state), "north carolina"))
  }

  NOT EXISTS {
    ?student_enrolment :ref-student ?student .
  }

  ?student :last_name ?lastName .
}

