PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?first_name ?middle_name ?last_name
WHERE {
  ?student a :students ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name ;
           :date_first_registered ?date .
}
ORDER BY ?date
LIMIT 1

PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?first_name ?middle_name ?last_name
WHERE {
  ?student a :students ;
           :date_left ?date_left ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name .
}
ORDER BY ?date_left
LIMIT 1

SELECT ?addressId ?line1 ?line2
WHERE {
  {
    SELECT ?addressId (COUNT(?student) AS ?numStudents)
    WHERE {
      ?student a :students ;
               :ref-current_address ?address .
      ?address :address_id ?addressId .
    }
    GROUP BY ?addressId
    ORDER BY DESC(?numStudents)
    LIMIT 1
  }
  ?address :address_id ?addressId .
  ?address :line_1 ?line1 .
  ?address :line_2 ?line2 .
}
GROUP BY ?addressId ?line1 ?line2

SELECT ?address_id ?line_1 ?line_2
WHERE {
  ?address :address_id ?address_id ;
           :line_1 ?line_1 ;
           :line_2 ?line_2 .
  {
    SELECT ?address
    WHERE {
      {
        ?student :ref-current_address ?address .
      }
      UNION
      {
        ?student :ref-permanent_address ?address .
      }
    }
    GROUP BY ?address
    ORDER BY DESC(COUNT(?student))
    LIMIT 1
  }
}

SELECT ?semester ?semesterName
WHERE {
  ?semester :semester_name ?semesterName .
  EXISTS {
    ?student_enrolment :ref-semester ?semester .
    ?student_enrolment :ref-student ?student .
    ?student :degree_program_id ?degree_program_id .
    ?degree_program :degree_program_id ?degree_program_id .
    ?degree_program :degree_summary_name ?degree_name .
    FILTER(CONTAINS(LCASE(?degree_name), "bachelor"))
  }
  EXISTS {
    ?student_enrolment2 :ref-semester ?semester .
    ?student_enrolment2 :ref-student ?student2 .
    ?student2 :degree_program_id ?degree_program_id2 .
    ?degree_program2 :degree_program_id ?degree_program_id2 .
    ?degree_program2 :degree_summary_name ?degree_name2 .
    FILTER(CONTAINS(LCASE(?degree_name2), "master"))
  }
}

