  ?country a :country ;
           :continent "Asia" ;
           :name ?name ;
           :population ?population ;
           :lifeexpectancy ?lifeExpectancy ;
           :surfacearea ?surfaceArea .
  {
    SELECT ?maxSurfaceArea
    WHERE {
      ?country2 a :country ;
                :continent "Asia" ;
                :surfacearea ?surfaceArea2 .
      ORDER BY DESC(?surfaceArea2)
      LIMIT 1
    }
  }
  FILTER (?surfaceArea = ?maxSurfaceArea)
}

SELECT AVG(?lifeExpectancy) AS ?averageLifeExpectancy
WHERE {
  ?country a :country .
  ?country :lifeexpectancy ?lifeExpectancy .
  FILTER NOT EXISTS {
    ?countrylanguage :ref-countrycode ?country .
    ?countrylanguage :language "English" .
    ?countrylanguage :isofficial "yes" .
  }
}

