SELECT (COUNT(DISTINCT ?language) AS ?totalLanguages) WHERE {
  ?country a :country ;
           :indepyear ?indepYear .
  FILTER(?indepYear < 1930)
  ?countrylanguage a :countrylanguage ;
                   :ref-countrycode ?country ;
                   :isofficial "T" ;
                   :language ?language .
}

SELECT ?countryLabel
WHERE {
  ?country a :country ;
           :surfacearea ?surfaceArea .
  ?country :name ?countryLabel .
  {
    SELECT MAX(?ea) WHERE {
      ?eCountry a :country ;
                :continent "Europe" ;
                :surfacearea ?ea .
    }
  } AS ?maxEA
  FILTER( ?surfaceArea > ?maxEA )
}

SELECT ?countryName ?area WHERE {
  ?country a :country ;
           :surfacearea ?area ;
           :name ?countryName .
  FILTER(?area > (SELECT MAX(?eArea) WHERE {
    ?eCountry a :country ;
              :region "Europe" ;
              :surfacearea ?eArea .
  }))
}

PREFIX : <http://valuenet/ontop/>
