PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?africanCountry ?africanName ?africanPop
WHERE {
  ?africanCountry a :country ;
                  :continent "Africa" ;
                  :population ?africanPop .
  ?africanCountry :name ?africanName .
  {
    SELECT (MIN(?population) AS ?minAsiaPop)
    WHERE {
      ?country a :country ;
               :continent "Asia" ;
               :population ?population .
    }
  }
  FILTER(?africanPop < ?minAsiaPop)
}
GROUP BY ?africanCountry ?africanName ?africanPop

