SELECT ?africanCountryLabel
WHERE {
  ?africanCountry a :country ;
                  :region "Africa" ;
                  :population ?afrPop .
  ?africanCountry :name ?africanCountryLabel .
  {
    SELECT (MIN(?asianPop) AS ?minAsianPop)
    WHERE {
      ?asianCountry a :country ;
                     :region "Asia" ;
                     :population ?asianPop .
    }
  }
  FILTER(?afrPop < ?minAsianPop)
}
GROUP BY ?africanCountryLabel

