    SELECT (MAX(?p) AS ?maxAfricaPop)
    WHERE {
      ?countryAfrica a :country ;
                     :continent "Africa" ;
                     :population ?p .
    }
  }
  FILTER(?population > ?maxAfricaPop)
}
GROUP BY ?country ?population

SELECT ?country ?population
WHERE {
  ?country a :country ;
           :continent "Asia" ;
           :population ?population .
  {
    SELECT MAX(?pop) AS ?maxAfricaPop
    WHERE {
      ?country2 a :country ;
