PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (SAMPLE(?name) AS ?beastName)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment :ChaoticGood ;
         :hasLanguages ?language ;
         :hasName ?name .
  FILTER NOT EXISTS { ?beast :hasLanguages :DraconicL . }
}
GROUP BY ?beast

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
ASK {
  {
    SELECT (COUNT(DISTINCT ?abil1) AS ?caypupCount) WHERE {
      ?beast1 rdf:type :Beast ;
              :hasName ?name1 ;
              :hasSpecAbils ?abil1 .
      FILTER(LCASE(STR(?name1)) = "caypup")
    }
  }
  {
    SELECT (COUNT(DISTINCT ?abil2) AS ?aasimarCount) WHERE {
      ?beast2 rdf:type :Beast ;
              :hasName ?name2 ;
              :hasSpecAbils ?abil2 .
      FILTER(LCASE(STR(?name2)) = "aasimar")
    }
  }
  FILTER(?caypupCount > ?aasimarCount)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?beast) AS ?count)
WHERE {
  { ?beast :hasLanguages ?language . }
  UNION
  { ?language :spokenBy ?beast . }
  ?beast :hasAlignment ?alignment .
  OPTIONAL { ?language :hasName ?languageName . }
  OPTIONAL { ?alignment :hasName ?alignmentName . }
  BIND(REPLACE(LCASE(STR(COALESCE(?languageName, ?language))), "[ _-]", "") AS ?langStr)
  BIND(REPLACE(LCASE(STR(COALESCE(?alignmentName, ?alignment))), "[ _-]", "") AS ?alignStr)
  FILTER(CONTAINS(?langStr, "treant"))
  FILTER(!CONTAINS(?alignStr, "trueneutral"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?spellName
WHERE {
  ?b1 rdf:type :Beast ;
      :hasName ?n1 ;
      :canSpell ?spell .
  FILTER(LCASE(STR(?n1)) = "aasimar")
  ?b2 rdf:type :Beast ;
      :hasName ?n2 ;
      :canSpell ?spell .
  FILTER(LCASE(STR(?n2)) = "caypup")
  OPTIONAL { ?spell :hasName ?sName . }
  BIND(COALESCE(STR(?sName), REPLACE(STR(?spell), "^.*#", "")) AS ?spellName)
}

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  {
    SELECT (COUNT(DISTINCT ?beast1) AS ?count1) WHERE {
      ?beast1 rdf:type :Beast ;
              :hasLanguages ?langA , ?langB .
      ?langA :hasName ?nameA .
      ?langB :hasName ?nameB .
      FILTER(CONTAINS(LCASE(STR(?nameA)), "abyssal"))
      FILTER(CONTAINS(LCASE(STR(?nameB)), "aklo"))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?beast2) AS ?count2) WHERE {
      ?beast2 rdf:type :Beast ;
              :hasLanguages ?langC , ?langD .
      ?langC :hasName ?nameC .
      ?langD :hasName ?nameD .
      FILTER(CONTAINS(LCASE(STR(?nameC)), "infernal"))
      FILTER(CONTAINS(LCASE(STR(?nameD)), "terran"))
    }
  }
  FILTER(?count1 > ?count2)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?goodCount ?evilCount (?goodCount > ?evilCount AS ?goodMoreCommon)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?goodBeast) AS ?goodCount)
    WHERE {
      ?goodBeast :hasAlignment ?goodAlignment .
      ?goodAlignment :hasName ?goodName .
      FILTER(CONTAINS(LCASE(STR(?goodName)), "good"))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?evilBeast) AS ?evilCount)
    WHERE {
      ?evilBeast :hasAlignment ?evilAlignment .
      ?evilAlignment :hasName ?evilName .
      FILTER(CONTAINS(LCASE(STR(?evilName)), "evil"))
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?beastName
WHERE {
  ?beast rdf:type :Beast ;
         :hasResists <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#cold> ;
         :hasName ?beastName .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ((SUM(?flag) * 100.0 / COUNT(?dragon)) AS ?percentage)
WHERE {
  ?dragon rdf:type :Beast .
  FILTER EXISTS {
    ?dragon :beastCategoryName ?cat .
    FILTER(LCASE(STR(?cat)) = "dragon")
  }
  BIND(IF(EXISTS {
    ?dragon :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#DraconicL> .
    ?dragon :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#CommonL> .
  }, 1, 0) AS ?flag)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?dragonAvg ?demonAvg ?dragonsSpeakMore
WHERE {
  {
    SELECT (AVG(?dragonLangCount) AS ?dragonAvg)
    WHERE {
      {
        SELECT ?dragon (COUNT(DISTINCT ?dragonLang) AS ?dragonLangCount)
        WHERE {
          ?dragon rdf:type :Beast ;
                  :beastCategoryName ?dragonCat ;
                  :hasLanguages ?dragonLang .
          FILTER(CONTAINS(LCASE(STR(?dragonCat)), "dragon"))
        }
        GROUP BY ?dragon
      }
    }
  }
  {
    SELECT (AVG(?demonLangCount) AS ?demonAvg)
    WHERE {
      {
        SELECT ?demon (COUNT(DISTINCT ?demonLang) AS ?demonLangCount)
        WHERE {
          ?demon rdf:type :Beast ;
                 :beastCategoryName ?demonCat ;
                 :hasLanguages ?demonLang .
          FILTER(CONTAINS(LCASE(STR(?demonCat)), "demon"))
        }
        GROUP BY ?demon
      }
    }
  }
  BIND((?dragonAvg > ?demonAvg) AS ?dragonsSpeakMore)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?beastName
WHERE {
  ?beast rdf:type :Beast .
  OPTIONAL { ?beast :hasName ?bn . }
  BIND(COALESCE(STR(?bn), REPLACE(STR(?beast), "^.*[#/]", "")) AS ?beastName)

  { ?beast :hasLanguages ?lang1 . } UNION { ?lang1 :spokenBy ?beast . }
  OPTIONAL { ?lang1 :hasName ?l1n . }
  BIND(LCASE(COALESCE(STR(?l1n), REPLACE(STR(?lang1), "^.*[#/]", ""))) AS ?lang1Name)
  FILTER(?lang1Name IN ("commonl", "common") || STRENDS(LCASE(STR(?lang1)), "#commonl"))

  { ?beast :hasLanguages ?lang2 . } UNION { ?lang2 :spokenBy ?beast . }
  OPTIONAL { ?lang2 :hasName ?l2n . }
  BIND(LCASE(COALESCE(STR(?l2n), REPLACE(STR(?lang2), "^.*[#/]", ""))) AS ?lang2Name)
  FILTER(?lang2Name IN ("undercommonl", "undercommon") || STRENDS(LCASE(STR(?lang2)), "#undercommonl"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?beast) AS ?count)
WHERE {
  ?beast rdf:type :Beast ;
         :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#AbyssalL> ;
         :hasLanguages ?sylvan ;
         :hasLanguages ?elven .
  ?sylvan rdf:type :Language ;
          :hasName ?sylvanName .
  ?elven rdf:type :Language ;
         :hasName ?elvenName .
  FILTER(CONTAINS(LCASE(STR(?sylvanName)), "sylvan"))
  FILTER(CONTAINS(LCASE(STR(?elvenName)), "elven"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
ASK {
  {
    SELECT (COUNT(DISTINCT ?troxLang) AS ?troxCount)
    WHERE {
      :Trox :hasLanguages ?troxLang .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?sunlordLang) AS ?sunlordCount)
    WHERE {
      :Sunlord :hasLanguages ?sunlordLang .
    }
  }
  FILTER(?troxCount > ?sunlordCount)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(DISTINCT ?beast) AS ?count)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment ?alignment .
  { ?beast :hasLanguages ?language . }
  UNION
  { ?language :spokenBy ?beast . }
  OPTIONAL { ?alignment :hasName ?alignmentName . }
  OPTIONAL { ?alignment rdfs:label ?alignmentLabel . }
  OPTIONAL { ?language :hasName ?languageName . }
  OPTIONAL { ?language rdfs:label ?languageLabel . }
  BIND(REPLACE(LCASE(CONCAT(STR(?alignment), " ", COALESCE(STR(?alignmentName), ""), " ", COALESCE(STR(?alignmentLabel), ""))), "[^a-z]", "") AS ?alignText)
  BIND(REPLACE(LCASE(CONCAT(STR(?language), " ", COALESCE(STR(?languageName), ""), " ", COALESCE(STR(?languageLabel), ""))), "[^a-z]", "") AS ?langText)
  FILTER(CONTAINS(?alignText, "lawfulneutral"))
  FILTER(CONTAINS(?langText, "giant"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?beastName
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?category ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#LawfulEvil> ;
         :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#CommonL> ;
         :hasName ?beastName .
  FILTER(CONTAINS(LCASE(STR(?category)), "ogre"))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ((IF(COUNT(DISTINCT ?beast) = 0, 0, COUNT(DISTINCT ?speaker) * 100.0 / COUNT(DISTINCT ?beast))) AS ?percentage)
WHERE {
  {
    ?beast :beastCategoryName ?cat .
    FILTER(CONTAINS(LCASE(STR(?cat)), "angel"))
  }
  UNION
  {
    ?beast :hasName ?bname .
    FILTER(CONTAINS(LCASE(STR(?bname)), "angel"))
  }
  OPTIONAL {
    ?beast :hasLanguages ?lang .
    OPTIONAL { ?lang :hasName ?langName . }
    FILTER(CONTAINS(LCASE(STR(?lang)), "aquan") || CONTAINS(LCASE(STR(COALESCE(?langName, ""))), "aquan"))
    BIND(?beast AS ?speaker)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (AVG(?langCount) AS ?averageLanguages)
WHERE {
  {
    SELECT ?beast (COUNT(DISTINCT ?language) AS ?langCount)
    WHERE {
      ?beast rdf:type :Beast .
      OPTIONAL { ?beast :hasLanguages ?language . }
    }
    GROUP BY ?beast
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (MAX(?hp) AS ?maxHP)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ChaoticGood> ;
         :hasHPValue ?hp .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?dhampirMean ?gorgonMean ?dhampirIsSuperior
WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Dhampir> :str ?dStr ;
      :dex ?dDex ;
      :con ?dCon ;
      :int ?dInt ;
      :wis ?dWis ;
      :cha ?dCha .
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Gorgon> :str ?gStr ;
      :dex ?gDex ;
      :con ?gCon ;
      :int ?gInt ;
      :wis ?gWis ;
      :cha ?gCha .
  BIND((xsd:decimal(?dStr) + xsd:decimal(?dDex) + xsd:decimal(?dCon) + xsd:decimal(?dInt) + xsd:decimal(?dWis) + xsd:decimal(?dCha)) / 6 AS ?dhampirMean)
  BIND((xsd:decimal(?gStr) + xsd:decimal(?gDex) + xsd:decimal(?gCon) + xsd:decimal(?gInt) + xsd:decimal(?gWis) + xsd:decimal(?gCha)) / 6 AS ?gorgonMean)
  BIND(?dhampirMean > ?gorgonMean AS ?dhampirIsSuperior)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?bAC ?sAC ?bTouch ?sTouch ?bFlat ?sFlat ?bFort ?sFort ?bRef ?sRef ?bWill ?sWill ?bHP ?sHP ?isBoggardSuperior
WHERE {
  :Boggard :hasACValue ?bAC ;
           :hasTouchValue ?bTouch ;
           :hasFlatFootedValue ?bFlat ;
           :hasFortValue ?bFort ;
           :hasRefValue ?bRef ;
           :hasWillValue ?bWill ;
           :hasHPValue ?bHP .
  ?selkie rdf:type :Beast ;
          :hasName ?selkieName ;
          :hasACValue ?sAC ;
          :hasTouchValue ?sTouch ;
          :hasFlatFootedValue ?sFlat ;
          :hasFortValue ?sFort ;
          :hasRefValue ?sRef ;
          :hasWillValue ?sWill ;
          :hasHPValue ?sHP .
  FILTER(CONTAINS(LCASE(STR(?selkieName)), "selkie"))
  BIND(((xsd:integer(?bAC) + xsd:integer(?bTouch) + xsd:integer(?bFlat) + ?bFort + ?bRef + ?bWill + ?bHP) >
        (xsd:integer(?sAC) + xsd:integer(?sTouch) + xsd:integer(?sFlat) + ?sFort + ?sRef + ?sWill + ?sHP)) AS ?isBoggardSuperior)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?centaurMeanDefense ?medusaMeanDefense ?centaurIsSuperior
WHERE {
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Centaur> :hasACValue ?cAC . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Centaur> :hasTouchValue ?cTouch . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Centaur> :hasFlatFootedValue ?cFF . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Centaur> :hasFortValue ?cFort . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Centaur> :hasRefValue ?cRef . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Centaur> :hasWillValue ?cWill . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Centaur> :cmd ?cCmd . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Medusa> :hasACValue ?mAC . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Medusa> :hasTouchValue ?mTouch . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Medusa> :hasFlatFootedValue ?mFF . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Medusa> :hasFortValue ?mFort . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Medusa> :hasRefValue ?mRef . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Medusa> :hasWillValue ?mWill . }
  OPTIONAL { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Medusa> :cmd ?mCmd . }
  BIND((COALESCE(xsd:decimal(?cAC), 0) + COALESCE(xsd:decimal(?cTouch), 0) + COALESCE(xsd:decimal(?cFF), 0) + COALESCE(xsd:decimal(?cFort), 0) + COALESCE(xsd:decimal(?cRef), 0) + COALESCE(xsd:decimal(?cWill), 0) + COALESCE(xsd:decimal(?cCmd), 0)) AS ?cSum)
  BIND((IF(BOUND(?cAC), 1, 0) + IF(BOUND(?cTouch), 1, 0) + IF(BOUND(?cFF), 1, 0) + IF(BOUND(?cFort), 1, 0) + IF(BOUND(?cRef), 1, 0) + IF(BOUND(?cWill), 1, 0) + IF(BOUND(?cCmd), 1, 0)) AS ?cCount)
  BIND((COALESCE(xsd:decimal(?mAC), 0) + COALESCE(xsd:decimal(?mTouch), 0) + COALESCE(xsd:decimal(?mFF), 0) + COALESCE(xsd:decimal(?mFort), 0) + COALESCE(xsd:decimal(?mRef), 0) + COALESCE(xsd:decimal(?mWill), 0) + COALESCE(xsd:decimal(?mCmd), 0)) AS ?mSum)
  BIND((IF(BOUND(?mAC), 1, 0) + IF(BOUND(?mTouch), 1, 0) + IF(BOUND(?mFF), 1, 0) + IF(BOUND(?mFort), 1, 0) + IF(BOUND(?mRef), 1, 0) + IF(BOUND(?mWill), 1, 0) + IF(BOUND(?mCmd), 1, 0)) AS ?mCount)
  BIND(IF(?cCount > 0, ?cSum / ?cCount, 0) AS ?centaurMeanDefense)
  BIND(IF(?mCount > 0, ?mSum / ?mCount, 0) AS ?medusaMeanDefense)
  BIND((?centaurMeanDefense > ?medusaMeanDefense) AS ?centaurIsSuperior)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT ?biclopsSum ?mastodonSum ?isSuperior
WHERE {
  :Biclops :str ?s1 ;
           :dex ?d1 ;
           :con ?c1 ;
           :int ?i1 ;
           :wis ?w1 ;
           :cha ?ch1 .
  :Mastodon :str ?s2 ;
            :dex ?d2 ;
            :con ?c2 ;
            :int ?i2 ;
            :wis ?w2 ;
            :cha ?ch2 .
  BIND((?s1 + ?d1 + ?c1 + ?i1 + ?w1 + ?ch1) AS ?biclopsSum)
  BIND((?s2 + ?d2 + ?c2 + ?i2 + ?w2 + ?ch2) AS ?mastodonSum)
  BIND((?biclopsSum > ?mastodonSum) AS ?isSuperior)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {
  :Satyr :str ?sStr ;
         :dex ?sDex ;
         :con ?sCon ;
         :int ?sInt ;
         :wis ?sWis ;
         :cha ?sCha .
  :Cacodaemon :str ?cStr ;
              :dex ?cDex ;
              :con ?cCon ;
              :int ?cInt ;
              :wis ?cWis ;
              :cha ?cCha .
  FILTER( ((?sStr + ?sDex + ?sCon + ?sInt + ?sWis + ?sCha) / 6.0) >
          ((?cStr + ?cDex + ?cCon + ?cInt + ?cWis + ?cCha) / 6.0) )
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?stat (AVG(?val) AS ?avgValue)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?cat .
  FILTER(CONTAINS(LCASE(STR(?cat)), "golem"))
  {
    ?beast :str ?val . BIND("str" AS ?stat)
  } UNION {
    ?beast :dex ?val . BIND("dex" AS ?stat)
  } UNION {
    ?beast :con ?val . BIND("con" AS ?stat)
  } UNION {
    ?beast :int ?val . BIND("int" AS ?stat)
  } UNION {
    ?beast :wis ?val . BIND("wis" AS ?stat)
  } UNION {
    ?beast :cha ?val . BIND("cha" AS ?stat)
  }
}
GROUP BY ?stat
ORDER BY DESC(AVG(?val))
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?statName ?avgValue
WHERE {
  {
    SELECT ?statName (AVG(xsd:decimal(?value)) AS ?avgRaw)
    WHERE {
      VALUES (?stat ?statName) {
        (:str "str")
        (:dex "dex")
        (:con "con")
        (:int "int")
        (:wis "wis")
        (:cha "cha")
      }
      ?beast rdf:type :Beast ;
             :hasName ?name ;
             ?stat ?value .
      FILTER(CONTAINS(LCASE(STR(?name)), "wolf"))
    }
    GROUP BY ?statName
  }
  BIND(?avgRaw AS ?avgValue)
}
ORDER BY ASC(?avgValue)
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?attribute (AVG(?value) AS ?avgValue)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?category .
  FILTER(LCASE(STR(?category)) = "skeleton")
  {
    ?beast :hasACValue ?value .
    BIND("AC" AS ?attribute)
  }
  UNION
  {
    ?beast :hasTouchValue ?value .
    BIND("Touch AC" AS ?attribute)
  }
  UNION
  {
    ?beast :hasFlatFootedValue ?value .
    BIND("Flat-Footed AC" AS ?attribute)
  }
  UNION
  {
    ?beast :hasHPValue ?value .
    BIND("HP" AS ?attribute)
  }
  UNION
  {
    ?beast :hasFortValue ?value .
    BIND("Fortitude" AS ?attribute)
  }
  UNION
  {
    ?beast :hasRefValue ?value .
    BIND("Reflex" AS ?attribute)
  }
  UNION
  {
    ?beast :hasWillValue ?value .
    BIND("Will" AS ?attribute)
  }
}
GROUP BY ?attribute
ORDER BY DESC(?avgValue)
LIMIT 1

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?beastName ?atk WHERE {
  ?beast rdf:type :Beast ;
         :hasName ?beastName ;
         :hasLanguages ?lang ;
         :atk ?atk .
  ?lang rdf:type :Language ;
        :hasName ?langName .
  FILTER(CONTAINS(LCASE(STR(?langName)), "aklo"))
  FILTER NOT EXISTS {
    ?other rdf:type :Beast ;
           :hasLanguages ?otherLang ;
           :atk ?otherAtk .
    ?otherLang rdf:type :Language ;
               :hasName ?otherLangName .
    FILTER(CONTAINS(LCASE(STR(?otherLangName)), "aklo"))
    FILTER(?otherAtk > ?atk)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (AVG(?atk) AS ?averageAttack)
WHERE {
  {
    SELECT DISTINCT ?beast ?atk
    WHERE {
      ?beast rdf:type :Beast ;
             :beastCategoryName ?category ;
             :atk ?atk .
      FILTER(LCASE(STR(?category)) = "robot")
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(DISTINCT ?beast) AS ?demonCount)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?category ;
         :cmd ?cmd .
  FILTER(LCASE(STR(?category)) = "demon")
  {
    SELECT (AVG(xsd:decimal(?allCmd)) AS ?avgCmd)
    WHERE {
      ?anyBeast rdf:type :Beast ;
                :cmd ?allCmd .
    }
  }
  FILTER(xsd:decimal(?cmd) > ?avgCmd)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (MAX(?cmd) AS ?maxCMD)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#NeutralGood> ;
         :cmd ?cmd .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?beastName ?ac
WHERE {
  ?beast :hasName ?beastName ;
         :hasACValue ?ac .
  { ?beast :hasLanguages ?language . }
  UNION
  { ?language :spokenBy ?beast . }
  OPTIONAL { ?language :hasName ?languageName . }
  FILTER(CONTAINS(LCASE(STR(?language)), "dwarven") || CONTAINS(LCASE(STR(COALESCE(?languageName, ""))), "dwarven"))
  FILTER(xsd:integer(STR(?ac)) > 12)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (MAX(?fort) AS ?maxFortValue)
WHERE {
  ?beast rdf:type :Beast ;
         :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#GoblinL> ;
         :hasFortValue ?fort .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (AVG(?hp) AS ?averageHP)
WHERE {
  { ?beast :hasLanguages ?language . }
  UNION
  { ?language :spokenBy ?beast . }
  ?beast :hasHPValue ?hp .
  OPTIONAL { ?language :hasName ?languageName . }
  FILTER(
    CONTAINS(LCASE(STR(?language)), "gnome") ||
    CONTAINS(LCASE(STR(COALESCE(?languageName, ""))), "gnome")
  )
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (MIN(?hp) AS ?minHP)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?category ;
         :str ?str ;
         :hasHPValue ?hp .
  FILTER(LCASE(STR(?category)) = "dragon")
  FILTER(?str > 10)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?beastName ?refValue
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment :ChaoticEvil ;
         :hasRefValue ?refValue ;
         :hasName ?beastName .
  FILTER NOT EXISTS {
    ?other rdf:type :Beast ;
           :hasAlignment :ChaoticEvil ;
           :hasRefValue ?otherRef .
    FILTER(?otherRef > ?refValue)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (MIN(?touch) AS ?minTouch)
WHERE {
  { ?beast :hasLanguages ?lang . }
  UNION
  { ?lang :spokenBy ?beast . }
  ?beast :hasTouchValue ?touch ;
         :hasInitValue ?init .
  OPTIONAL { ?lang :hasName ?langName . }
  BIND(COALESCE(STR(?langName), STR(?lang)) AS ?langText)
  FILTER(CONTAINS(LCASE(?langText), "druidic"))
  FILTER(?init < 2)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
SELECT (AVG(?will) AS ?averageWillValue)
WHERE {
  {
    SELECT DISTINCT ?beast ?will
    WHERE {
      { ?beast :hasLanguages ?language . }
      UNION
      { ?language :spokenBy ?beast . }
      ?beast :hasWillValue ?will .
      OPTIONAL { ?language :hasName ?languageName . }
      FILTER(
        CONTAINS(LCASE(STR(COALESCE(?languageName, ""))), "orc") ||
        CONTAINS(LCASE(STR(?language)), "orc")
      )
    }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?name
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?category ;
         :hasName ?name ;
         :cha ?cha .
  FILTER(CONTAINS(LCASE(STR(?category)), "zombie"))
  FILTER(?cha >= 3 && ?cha <= 7)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#LawfulEvil> ;
         :cha ?cha ;
         :str ?str ;
         :int ?int .
  FILTER(xsd:integer(?cha) > (xsd:integer(?str) + xsd:integer(?int)))
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?beastName ?dex
WHERE {
  ?beast rdf:type :Beast ;
         :hasLanguages :AbolethL ;
         :dex ?dex ;
         :hasName ?beastName .
  ?b rdf:type :Beast ;
     :dex ?d .
}
GROUP BY ?beast ?beastName ?dex
HAVING (xsd:decimal(?dex) > AVG(xsd:decimal(?d)))

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?beast) AS ?count)
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?category ;
         :int ?int ;
         :hasSpeedValue ?speed .
  FILTER(LCASE(STR(?category)) = "robot")
  FILTER(?int < 7 && ?speed > 10)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (MIN(?int) AS ?minIntelligence)
WHERE {
  ?beast rdf:type :Beast ;
         :hasAlignment :ChaoticNeutral ;
         :int ?int .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
ASK
WHERE {
  ?beast rdf:type :Beast ;
         :beastCategoryName ?category ;
         :str ?str ;
         :cha ?cha .
  FILTER(CONTAINS(LCASE(STR(?category)), "golem"))
  FILTER(?str < ?cha)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?beastName
WHERE {
  ?beast rdf:type :Beast ;
         :hasName ?beastName ;
         :wis ?wis ;
         :hasLanguages ?lang1 ;
         :hasLanguages ?lang2 .
  ?lang1 :hasName ?lang1Name .
  ?lang2 :hasName ?lang2Name .
  FILTER(CONTAINS(LCASE(STR(?lang1Name)), "necril"))
  FILTER(CONTAINS(LCASE(STR(?lang2Name)), "abyssal"))
  FILTER(?wis > 4)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SAMPLE(?name) AS ?beastName) (SAMPLE(?total) AS ?statSum)
WHERE {
  ?beast rdf:type :Beast ;
         :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#GnollL> ;
         :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#ElvenL> ;
         :hasName ?name ;
         :str ?str ;
         :dex ?dex ;
         :con ?con ;
         :int ?int ;
         :wis ?wis ;
         :cha ?cha .
  BIND((?str + ?dex + ?con + ?int + ?wis + ?cha) AS ?total)
}
GROUP BY ?beast

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
ASK WHERE {
  :Baalzebul :str ?str1 ;
             :dex ?dex1 ;
             :con ?con1 ;
             :int ?int1 ;
             :wis ?wis1 ;
             :cha ?cha1 .
  :Dagon :str ?str2 ;
         :dex ?dex2 ;
         :con ?con2 ;
         :int ?int2 ;
         :wis ?wis2 ;
         :cha ?cha2 .
  FILTER( ((xsd:decimal(?str1) + xsd:decimal(?dex1) + xsd:decimal(?con1) + xsd:decimal(?int1) + xsd:decimal(?wis1) + xsd:decimal(?cha1)) / 6) >
          ((xsd:decimal(?str2) + xsd:decimal(?dex2) + xsd:decimal(?con2) + xsd:decimal(?int2) + xsd:decimal(?wis2) + xsd:decimal(?cha2)) / 6) )
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?beastName ?con
WHERE {
  ?beast rdf:type :Beast ;
         :hasName ?beastName ;
         :hasLanguages ?lang ;
         :con ?con .
  ?lang :hasName ?langName .
  FILTER(CONTAINS(LCASE(STR(?langName)), "ghoul"))
  FILTER NOT EXISTS {
    ?b rdf:type :Beast ;
       :hasLanguages ?l ;
       :con ?c .
    ?l :hasName ?ln .
    FILTER(CONTAINS(LCASE(STR(?ln)), "ghoul"))
    FILTER(?c > ?con)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
ASK {
  {
    SELECT (COUNT(DISTINCT ?beast1) AS ?darkCount)
    WHERE {
      ?beast1 rdf:type :Beast ;
              :hasLanguages ?lang1 .
      ?lang1 :hasName ?langName1 .
      FILTER(CONTAINS(LCASE(STR(?langName1)), "dark"))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?beast2) AS ?cyclopsCount)
    WHERE {
      ?beast2 rdf:type :Beast ;
              :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#CyclopsL> .
    }
  }
  FILTER(?darkCount > ?cyclopsCount)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
ASK {
  {
    SELECT (COUNT(DISTINCT ?b1) AS ?polyglotCount) WHERE {
      ?b1 rdf:type :Beast ;
          :hasLanguages <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#PolyglotL> .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?b2) AS ?skaldCount) WHERE {
      ?b2 rdf:type :Beast ;
          :hasLanguages ?lang2 .
      ?lang2 rdf:type :Language ;
             :hasName ?langName2 .
      FILTER(CONTAINS(LCASE(STR(?langName2)), "skald"))
    }
  }
  FILTER(?polyglotCount > ?skaldCount)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
ASK {
  {
    SELECT (AVG(?xpA) AS ?avgAngel)
    WHERE {
      ?a rdf:type :Beast ;
         :beastCategoryName ?catA ;
         :hasXPValue ?xpA .
      FILTER(LCASE(STR(?catA)) = "angel")
    }
  }
  {
    SELECT (AVG(?xpD) AS ?avgDemon)
    WHERE {
      ?d rdf:type :Beast ;
         :beastCategoryName ?catD ;
         :hasXPValue ?xpD .
      FILTER(LCASE(STR(?catD)) = "demon")
    }
  }
  FILTER(?avgAngel > ?avgDemon)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
ASK WHERE {
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Lorelei> :hasLanguages ?anyLang1 .
  <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Siren> :hasLanguages ?anyLang2 .
  FILTER NOT EXISTS {
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Lorelei> :hasLanguages ?l1 .
    FILTER NOT EXISTS { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Siren> :hasLanguages ?l1 . }
  }
  FILTER NOT EXISTS {
    <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Siren> :hasLanguages ?l2 .
    FILTER NOT EXISTS { <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#Lorelei> :hasLanguages ?l2 . }
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://www.semanticweb.org/annab/ontologies/2022/3/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (MIN(?wis) AS ?minWisdom)
WHERE {
  VALUES ?beast { :Gorynych :Vodyanoi }
  ?beast rdf:type :Beast ;
         :wis ?wis .
}

PREFIX creativecommons: <http://creativecommons.org/ns#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX ecc: <https://ns.eccenca.com/>
PREFIX eccdi: <https://vocab.eccenca.com/di/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ns2: <http://purl.org/dc/terms/>
PREFIX ns3: <https://text2sparql.aksw.org/2025/corporate/queries/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX shui: <https://vocab.eccenca.com/shui/>
PREFIX vann: <http://purl.org/vocab/vann/>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX wgs1: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?categoryLabel ?lightestName ?minWeight ?heaviestName ?maxWeight
WHERE {
  {
    SELECT ?category (MIN(?w) AS ?minWeight) (MAX(?w) AS ?maxWeight)
    WHERE {
      ?h rdf:type pv:Hardware ;
         pv:hasCategory ?category ;
         pv:weight_g ?w .
    }
    GROUP BY ?category
  }
  ?category rdfs:label ?categoryLabel .
  ?light rdf:type pv:Hardware ;
         pv:hasCategory ?category ;
         pv:weight_g ?minWeight ;
         pv:name ?lightestName .
  ?heavy rdf:type pv:Hardware ;
         pv:hasCategory ?category ;
         pv:weight_g ?maxWeight ;
         pv:name ?heaviestName .
}
ORDER BY ?categoryLabel

PREFIX creativecommons: <http://creativecommons.org/ns#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX ecc: <https://ns.eccenca.com/>
PREFIX eccdi: <https://vocab.eccenca.com/di/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX ns2: <http://purl.org/dc/terms/>
PREFIX ns3: <https://text2sparql.aksw.org/2025/corporate/queries/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX shui: <https://vocab.eccenca.com/shui/>
PREFIX vann: <http://purl.org/vocab/vann/>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX wgs1: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?id ?name ?width
WHERE {
  ?h rdf:type pv:Hardware ;
     pv:id ?id ;
     pv:name ?name ;
     pv:width_mm ?width .
  {
    SELECT (COUNT(?h2) AS ?total)
    WHERE {
      ?h2 rdf:type pv:Hardware ;
          pv:width_mm ?w2 .
    }
  }
  OPTIONAL {
    ?h3 rdf:type pv:Hardware ;
        pv:width_mm ?w3 .
    FILTER(?w3 > ?width)
  }
}
GROUP BY ?h ?id ?name ?width ?total
HAVING (COUNT(?h3) < (?total * 0.1))
ORDER BY DESC(?width)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
