PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?name ?date ?result
WHERE {
  ?battle rdf:type :battle ;
          :name ?name ;
          :date ?date ;
          :result ?result .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?killed ?injured
WHERE {
  ?death rdf:type :death ;
         :ref-caused_by_ship ?ship ;
         :killed ?killed ;
         :injured ?injured .
  ?ship rdf:type :ship ;
        :tonnage ?tonnage .
  FILTER(STR(?tonnage) = "t")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?name ?result
WHERE {
  ?battle rdf:type :battle ;
          :name ?name ;
          :result ?result ;
          :bulgarian_commander ?commander .
  FILTER(?commander != "Boril")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?id ?name
WHERE {
  ?ship rdf:type :ship ;
        :ship_type ?type ;
        :ref-lost_in_battle ?battle .
  ?battle rdf:type :battle ;
          :id ?id ;
          :name ?name .
  FILTER(?type = "Brig")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?id ?name
WHERE {
  ?battle rdf:type :battle ;
          :id ?id ;
          :name ?name .
  ?ship rdf:type :ship ;
        :ref-lost_in_battle ?battle .
  ?death rdf:type :death ;
         :ref-caused_by_ship ?ship ;
         :killed ?killed .
}
GROUP BY ?battle ?id ?name
HAVING (SUM(?killed) > 10)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?shipId ?shipName
WHERE {
  ?death rdf:type :death ;
         :ref-caused_by_ship ?ship ;
         :injured ?injured .
  ?ship rdf:type :ship ;
        :id ?shipId ;
        :name ?shipName .
}
GROUP BY ?ship ?shipId ?shipName
ORDER BY DESC(SUM(?injured))
LIMIT 1

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?name
WHERE {
  ?battle rdf:type :battle ;
          :name ?name ;
          :bulgarian_commander ?bc ;
          :latin_commander ?lc .
  FILTER(?bc = "Kaloyan" && ?lc = "Baldwin I")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?battle) AS ?count)
WHERE {
  ?battle rdf:type :battle .
  FILTER NOT EXISTS {
    ?ship rdf:type :ship ;
          :ref-lost_in_battle ?battle ;
          :tonnage ?tonnage .
    FILTER(STR(?tonnage) = "225")
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?name ?date
WHERE {
  ?battle rdf:type :battle ;
          :name ?name ;
          :date ?date .
  ?ship1 rdf:type :ship ;
         :name "Lettice" ;
         :ref-lost_in_battle ?battle .
  ?ship2 rdf:type :ship ;
         :name "HMS Atalanta" ;
         :ref-lost_in_battle ?battle .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?name ?result ?bulgarian_commander
WHERE {
  ?battle rdf:type :battle ;
          :name ?name ;
          :result ?result ;
          :bulgarian_commander ?bulgarian_commander .
  FILTER NOT EXISTS {
    ?ship rdf:type :ship ;
          :ref-lost_in_battle ?battle ;
          :location ?location .
