PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(?car) AS ?count)
WHERE {
  ?car rdf:type :cars_data ;
       :accelerate ?acc .
  {
    SELECT ?maxAcc
    WHERE {
      ?topCar rdf:type :cars_data ;
              :horsepower ?hp ;
              :accelerate ?maxAcc .
    }
    ORDER BY DESC(?hp)
    LIMIT 1
  }
  FILTER(?acc > ?maxAcc)
}

