SELECT (COUNT(?country) AS ?count)
WHERE {
  {
    SELECT ?country
    WHERE {
      ?maker rdf:type :car_makers ;
             :ref-country ?country .
      ?country rdf:type :countries .
    }
    GROUP BY ?country
    HAVING (COUNT(?maker) > 2)
  }
}

