PREFIX : <http://valuenet/ontop/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?countryid ?countryname
WHERE {
  {
    SELECT ?country ?countryid ?countryname
    WHERE {
      ?country rdf:type :countries ;
               :countryid ?countryid ;
               :countryname ?countryname .
      ?maker rdf:type :car_makers ;
             :ref-country ?country .
    }
    GROUP BY ?country ?countryid ?countryname
    HAVING (COUNT(DISTINCT ?maker) > 3)
  }
  UNION
  {
    ?country rdf:type :countries ;
             :countryid ?countryid ;
             :countryname ?countryname .
    ?maker rdf:type :car_makers ;
           :ref-country ?country .
    ?modelEntry rdf:type :model_list ;
                :ref-maker ?maker ;
                :model ?model .
    FILTER(LCASE(STR(?model)) = "fiat")
  }
}

