SELECT ?concertName ?theme (COUNT(?sic) AS ?numSingers)
WHERE {
  ?concert rdf:type :concert ;
           :concert_name ?concertName ;
           :theme ?theme .
  ?sic rdf:type :singer_in_concert ;
       :ref-concert ?concert .
}
GROUP BY ?concert ?concertName ?theme

