SELECT ?singerName (COUNT(DISTINCT ?concert) AS ?numConcerts)
WHERE {
  ?sic rdf:type :singer_in_concert ;
       :ref-singer ?singer ;
       :ref-concert ?concert .
  ?singer rdf:type :singer ;
          :name ?singerName .
}
