PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?singerName
WHERE {
  ?sic rdf:type :singer_in_concert ;
       :ref-concert ?concert ;
       :ref-singer ?singer .
  ?concert rdf:type :concert ;
           :year ?year .
  ?singer rdf:type :singer ;
          :name ?singerName .
  FILTER(STR(?year) = "2014")
}

