PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(?concert) AS ?count)
WHERE {
  ?stadium rdf:type :stadium ;
           :capacity ?cap .
  FILTER NOT EXISTS {
    ?otherStadium rdf:type :stadium ;
                  :capacity ?otherCap .
    FILTER(?otherCap > ?cap)
  }
  OPTIONAL {
    ?concert rdf:type :concert ;
             :ref-stadium ?stadium .
  }
}
GROUP BY ?stadium

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?concert) AS ?numConcerts)
WHERE {
  {
    SELECT ?stadium
    WHERE {
      ?stadium rdf:type :stadium ;
               :capacity ?cap .
    }
    ORDER BY DESC(?cap)
    LIMIT 1
  }
  OPTIONAL {
    ?concert rdf:type :concert ;
             :ref-stadium ?stadium .
  }
}
GROUP BY ?stadium

