SELECT ?document_name
WHERE {
  ?doc rdf:type :documents ;
       :document_name ?document_name ;
       :ref-template ?template .
  ?template rdf:type :templates ;
            :template_type_code ?code .
  FILTER(STR(?code) = "BK")
}

