PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?professional_id ?last_name ?cell_number
WHERE {
  ?p rdf:type :professionals ;
     :professional_id ?professional_id ;
     :last_name ?last_name ;
     :cell_number ?cell_number ;
     :state ?state .
  OPTIONAL {
    ?t rdf:type :treatments ;
       :ref-professional ?p .
  }
}
GROUP BY ?p ?professional_id ?last_name ?cell_number ?state
HAVING (?state = "Indiana" || COUNT(?t) > 2)

