SELECT DISTINCT ?firstName
WHERE {
  {
    ?p rdf:type :professionals ;
       :first_name ?firstName .
  }
  UNION
  {
    ?o rdf:type :owners ;
       :first_name ?firstName .
  }
  FILTER NOT EXISTS {
    ?d rdf:type :dogs ;
       :name ?dogName .
    FILTER(STR(?dogName) = STR(?firstName))
  }
}

