PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?professional_id ?cell_number
WHERE {
  ?p rdf:type :professionals ;
     :professional_id ?professional_id ;
     :cell_number ?cell_number .
  ?t rdf:type :treatments ;
     :ref-professional ?p ;
     :treatment_type_code ?type .
}
GROUP BY ?p ?professional_id ?cell_number
HAVING (COUNT(?t) >= 2)

