SELECT ?first_name ?last_name
WHERE {
  ?treatment rdf:type :treatments ;
             :ref-professional ?professional ;
             :cost_of_treatment ?cost .
  ?professional rdf:type :professionals ;
                :first_name ?first_name ;
                :last_name ?last_name .
  {
    SELECT (AVG(?c) AS ?avgCost)
    WHERE {
      ?t rdf:type :treatments ;
         :cost_of_treatment ?c .
    }
  }
  FILTER(?cost < ?avgCost)
}
GROUP BY ?first_name ?last_name

