PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?name ?date_of_treatment
WHERE {
  ?dog rdf:type :dogs ;
       :breed_code ?breed_code ;
       :name ?name .
  ?treatment rdf:type :treatments ;
             :ref-dog ?dog ;
             :date_of_treatment ?date_of_treatment .
  {
    SELECT ?breed_code
    WHERE {
      {
        SELECT ?breed_code (COUNT(?d) AS ?cnt)
        WHERE {
          ?d rdf:type :dogs ;
             :breed_code ?breed_code .
        }
        GROUP BY ?breed_code
      }
    }
    ORDER BY ASC(?cnt)
    LIMIT 1
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (SAMPLE(?dogName) AS ?name) (SAMPLE(?treatmentDate) AS ?date_of_treatment)
WHERE {
  {
    SELECT ?breed_code (COUNT(?d) AS ?breedCount)
    WHERE {
      ?d rdf:type :dogs ;
         :breed_code ?breed_code .
    }
    GROUP BY ?breed_code
    ORDER BY ASC(?breedCount)
    LIMIT 1
  }
  ?dog rdf:type :dogs ;
       :breed_code ?breed_code ;
       :name ?dogName .
  ?treatment rdf:type :treatments ;
             :ref-dog ?dog ;
             :date_of_treatment ?treatmentDate .
}
GROUP BY ?treatment

