PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
SELECT DISTINCT ?airportname
WHERE {
  ?airport :airportname ?airportname ;
           :airportcode ?code .
  BIND(UCASE(REPLACE(STR(?code), "\\s", "")) AS ?normCode)
  MINUS {
    ?airport :airportcode ?code2 .
    ?f1 :sourceairport ?src .
    FILTER(UCASE(REPLACE(STR(?src), "\\s", "")) = UCASE(REPLACE(STR(?code2), "\\s", "")))
  }
  MINUS {
    ?airport :airportcode ?code3 .
    ?f2 :destairport ?dst .
    FILTER(UCASE(REPLACE(STR(?dst), "\\s", "")) = UCASE(REPLACE(STR(?code3), "\\s", "")))
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
SELECT DISTINCT ?airportname
WHERE {
  ?airport :airportcode ?code .
  OPTIONAL { ?airport :airportname ?name . }
  BIND(COALESCE(?name, ?code) AS ?airportname)
  FILTER NOT EXISTS {
    ?f1 :ref-sourceairport ?airport .
  }
  FILTER NOT EXISTS {
    ?f2 :ref-destairport ?airport .
  }
  FILTER NOT EXISTS {
    ?f3 :sourceairport ?src .
    FILTER(UCASE(STR(?src)) = UCASE(STR(?code)))
  }
  FILTER NOT EXISTS {
    ?f4 :destairport ?dst .
    FILTER(UCASE(STR(?dst)) = UCASE(STR(?code)))
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
