SELECT ?openYear ?numOfStaff
WHERE {
  ?museum rdf:type :museum ;
          :name ?name ;
          :open_year ?openYear ;
          :num_of_staff ?numOfStaff .
  FILTER(LCASE(STR(?name)) = "plaza museum")
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?name
WHERE {
  ?m rdf:type :museum ;
     :name ?name ;
     :num_of_staff ?staff .
  FILTER EXISTS {
    ?m2 rdf:type :museum ;
        :num_of_staff ?s2 ;
        :open_year ?y2 .
    FILTER(?y2 > 2010 && ?staff > ?s2)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?id ?name ?age
WHERE {
  ?visitor rdf:type :visitor ;
           :id ?id ;
           :name ?name ;
           :age ?age .
  ?visit rdf:type :visit ;
         :ref-visitor ?visitor .
}
GROUP BY ?visitor ?id ?name ?age
HAVING (COUNT(?visit) > 1)

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?id ?name ?level
WHERE {
  ?visit rdf:type :visit ;
         :ref-visitor ?visitor ;
         :total_spent ?spent .
  ?visitor :id ?id ;
           :name ?name ;
           :level_of_membership ?level .
}
GROUP BY ?visitor ?id ?name ?level
ORDER BY DESC(SUM(?spent))
LIMIT 1

