PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (SUM(?spent) AS ?totalSpent)
WHERE {
  ?visit rdf:type :visit ;
         :ref-visitor ?visitor ;
         :total_spent ?spent .
  ?visitor rdf:type :visitor ;
           :level_of_membership ?level .
  FILTER(?level = 1)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?name
WHERE {
  ?visitor rdf:type :visitor ;
           :name ?name .
  ?visit1 rdf:type :visit ;
          :ref-visitor ?visitor ;
          :ref-museum ?museum1 .
  ?museum1 :open_year ?year1 .
  FILTER(?year1 < 2009)
  ?visit2 rdf:type :visit ;
          :ref-visitor ?visitor ;
          :ref-museum ?museum2 .
  ?museum2 :open_year ?year2 .
  FILTER(?year2 > 2011)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?visitor) AS ?count)
WHERE {
  ?visitor rdf:type :visitor .
  FILTER NOT EXISTS {
    ?visit rdf:type :visit ;
           :ref-visitor ?visitor ;
           :ref-museum ?museum .
    ?museum :open_year ?year .
    FILTER(?year > 2010)
  }
}

