PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(?pet) AS ?count)
WHERE {
  ?hp rdf:type :has_pet ;
      :ref-pet ?pet ;
      :ref-stu ?stu .
  ?pet rdf:type :pets ;
       :pettype ?pettype .
  ?stu rdf:type :student ;
       :sex ?sex .
  FILTER(LCASE(STR(?pettype)) = "dog")
  FILTER(STR(?sex) = "F")
