PREFIX : <http://valuenet/ontop/>
SELECT (COUNT(DISTINCT ?degree) AS ?degreeCount)
WHERE {
  ?dept :department_name ?deptName .
  FILTER(CONTAINS(LCASE(STR(?deptName)), "engineer"))
  {
    ?degree :ref-department ?dept .
  }
  UNION
  {
    ?dept :department_id ?deptId .
    ?degree :degree_summary_name ?degreeName ;
            :department_id ?degDeptId .
    FILTER(STR(?degDeptId) = STR(?deptId))
  }
}

