SELECT ?first_name ?middle_name ?last_name ?student_id
WHERE {
  ?enrol rdf:type :student_enrolment ;
         :ref-student ?student ;
         :ref-semester ?semester ;
         :ref-degree_program ?degree .
  ?student :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name ;
           :student_id ?student_id .
}
GROUP BY ?student ?semester ?first_name ?middle_name ?last_name ?student_id
HAVING (COUNT(?degree) = 2)

