PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?student_id ?first_name ?middle_name ?last_name (COUNT(?enrolment) AS ?num_enrolments) ?student_id2
WHERE {
  ?enrolment rdf:type :student_enrolment ;
             :ref-student ?student .
  ?student rdf:type :students ;
           :student_id ?student_id ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name .
  BIND(?student_id AS ?student_id2)
}
GROUP BY ?student ?student_id ?first_name ?middle_name ?last_name ?student_id2
ORDER BY DESC(COUNT(?enrolment))
LIMIT 1

