PREFIX : <http://valuenet/ontop/>
SELECT ?first_name ?middle_name ?last_name ?student_id (COUNT(?enrolment) AS ?num_enrollments)
WHERE {
  ?enrolment a :student_enrolment ;
             :ref-student ?student .
  ?student a :students ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name ;
           :student_id ?student_id .
}
GROUP BY ?student ?first_name ?middle_name ?last_name ?student_id
ORDER BY DESC(?num_enrollments)
LIMIT 1

