PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?first_name ?middle_name ?last_name
WHERE {
  ?student rdf:type :students ;
           :first_name ?first_name ;
           :middle_name ?middle_name ;
           :last_name ?last_name ;
           :date_left ?date_left .
}
ORDER BY ASC(?date_left)
LIMIT 1

