PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?semesterId
WHERE {
  ?enrol1 rdf:type :student_enrolment ;
          :ref-degree_program ?dp1 ;
          :semester_id ?semesterId .
  ?dp1 :degree_summary_name ?name1 .
  FILTER(CONTAINS(LCASE(STR(?name1)), "master"))

  ?enrol2 rdf:type :student_enrolment ;
          :ref-degree_program ?dp2 ;
          :semester_id ?semesterId .
  ?dp2 :degree_summary_name ?name2 .
  FILTER(CONTAINS(LCASE(STR(?name2)), "bachelor"))
}

