PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?countryName
WHERE {
  ?country rdf:type :country ;
           :name ?countryName .
  ?cl1 rdf:type :countrylanguage ;
       :ref-countrycode ?country ;
       :language ?lang1 .
  FILTER(?lang1 = "English")
  ?cl2 rdf:type :countrylanguage ;
       :ref-countrycode ?country ;
       :language ?lang2 .
  FILTER(?lang2 = "French")
}

