       :isofficial ?off1 .
  FILTER(LCASE(STR(?lang1)) = "english" && STR(?off1) = "T")
  ?cl2 rdf:type :countrylanguage ;
       :ref-countrycode ?country ;
       :language ?lang2 ;
       :isofficial ?off2 .
  FILTER(LCASE(STR(?lang2)) = "french" && STR(?off2) = "T")
}

