PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?name
WHERE {
  ?country rdf:type :country ;
           :name ?name ;
           :surfacearea ?area .
  FILTER EXISTS {
    ?eCountry rdf:type :country ;
              :continent ?continent ;
              :surfacearea ?eArea .
    FILTER(?continent = "Europe" && ?area > ?eArea)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?name
WHERE {
  ?country rdf:type :country ;
           :name ?name ;
           :continent ?continent ;
           :population ?population .
  FILTER(?continent = "Africa")
  FILTER EXISTS {
    ?asiaCountry rdf:type :country ;
                 :continent ?asiaContinent ;
                 :population ?asiaPop .
    FILTER(?asiaContinent = "Asia")
    FILTER(?population < ?asiaPop)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?name
WHERE {
  ?c rdf:type :country ;
     :name ?name ;
     :continent ?continent ;
     :population ?pop .
  FILTER(?continent = "Africa")
  FILTER NOT EXISTS {
    ?a rdf:type :country ;
       :continent ?acont ;
       :population ?apop .
    FILTER(?acont = "Asia" && ?apop <= ?pop)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
