PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?code
WHERE {
  ?country rdf:type :country ;
           :code ?code ;
           :governmentform ?govForm .
  FILTER(STR(?govForm) != "Republic")
  FILTER NOT EXISTS {
    ?cl rdf:type :countrylanguage ;
        :ref-countrycode ?country ;
        :language ?lang .
    FILTER(STR(?lang) = "English")
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?code
WHERE {
  ?country rdf:type :country ;
           :code ?code ;
           :governmentform ?govForm .
  FILTER(?govForm != "Republic")
  FILTER NOT EXISTS {
    ?cl rdf:type :countrylanguage ;
        :countrycode ?code ;
        :language "English" .
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?cityName
WHERE {
  ?city rdf:type :city ;
        :name ?cityName ;
        :ref-countrycode ?country .
  ?country rdf:type :country ;
           :continent ?continent .
  FILTER(?continent = "Europe")
  FILTER NOT EXISTS {
    ?cl rdf:type :countrylanguage ;
        :ref-countrycode ?country ;
        :language ?lang ;
        :isofficial ?official .
    FILTER(?lang = "English" && ?official = "T")
  }
}

