PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?name WHERE {
  ?city rdf:type :city ;
        :name ?name ;
        :population ?population .
  FILTER(?population >= 160000 && ?population <= 900000)
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?countryName ?language ?maxPercentage
WHERE {
  {
    SELECT ?country (MAX(?pct) AS ?maxPercentage)
    WHERE {
      ?cl rdf:type :countrylanguage ;
          :ref-countrycode ?country ;
          :percentage ?pct .
    }
    GROUP BY ?country
  }
  ?cl2 rdf:type :countrylanguage ;
       :ref-countrycode ?country ;
       :percentage ?maxPercentage ;
       :language ?language .
  ?country :name ?countryName .
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?countrycode ?language
WHERE {
  ?cl rdf:type :countrylanguage ;
      :countrycode ?countrycode ;
      :language ?language ;
      :percentage ?percentage .
  FILTER NOT EXISTS {
    ?cl2 rdf:type :countrylanguage ;
         :countrycode ?countrycode ;
         :percentage ?p2 .
    FILTER(?p2 > ?percentage)
  }
}

PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX grddl: <http://www.w3.org/2003/g/data-view#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

PREFIX : <http://valuenet/ontop/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT ?code) AS ?count)
WHERE {
  ?cl rdf:type :countrylanguage ;
      :countrycode ?code ;
      :language ?lang ;
      :percentage ?p .
  FILTER(LCASE(STR(?lang)) = "spanish")
  FILTER NOT EXISTS {
    ?cl2 rdf:type :countrylanguage ;
         :countrycode ?code ;
         :percentage ?p2 .
    FILTER(?p2 > ?p)
  }
}

